(window.GIM_TS=window.GIM_TS||{})["Pesachim.7"]={"from":168,"a":[["\u0003מאי לאו דאכלי באיגרא ואמרי באיגרא\u0004 \u0005[האם לא\u0006 מדובר כאן \u0005שהם אוכלים\u0006 את הפסח \u0005על הגג ואומרים\u0006 הלל \u0005על הגג]\u0006 ומכאן שגגות ירושלים נתקדשו בקדושתה! ודוחים: \u0003לא,\u0004 מכאן אין ראיה, אפשר לומר: \u0003דאכלי בארעא ואמרי באיגרא\u0004 \u0005[שאוכלים על הקרקע ואומרים על הגג]\u0006","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מפטירין אחר הפסח אפיקומן, ואמר רב:\u0004 משמעות הדברים היא: שלאחר אכילת הפסח אין לומר \"אפיקומן\", שמשמעותו הוציאו כליכם ונלך לאכול במקום אחר, אלא \u0003לא יעקרו מחבורה לחבורה.\u0004 משמע שבאותו מקום צריכים לסיים את כל סדר הפסח! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 \u0003כאן\u0004 — מדובר \u0003בשעת אכילה\u0004 שאסור לעקור ממקום למקום, ו\u0003כאן\u0004 שהתירו לומר הלל על הגג — \u0003שלא בשעת אכילה.\u0004","מנסים להביא ראיה נוספת לגוף הדבר \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לדבר, שנינו: \u0003אבא שאול אומר: עליית\u0004 (החדר שמעל) ל\u0003בית קדשי הקדשים חמורה\u0004 באיסורים החלים עליה \u0003מבית קדשי הקדשים.\u0004 כיצד? \u0003שבית קדשי הקדשים כהן גדול נכנס לו פעם אחת בשנה\u0004 ביום הכיפורים להקטיר שם קטורת ולהזיית בין הבדים ואילו \u0003עליית בית קדשי הקדשים אין נכנסין לה אלא פעם אחת בשבוע\u0004 (בשבע שנים) \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003פעמים בשבוע, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 רק \u0003פעם אחת ביובל לידע מה היא צריכה,\u0004 שמא נתקלקל בה דבר וצריך תיקון, ומשמע שיש בגג קדושה אפילו יתירה מזו שבהיכל עצמו.","\u0003אמר רב יוסף:\u0004 וכי \u0003מהיכל ניקום וניתיב איניש\u0004 \u0005[מן ההיכל יעמוד אדם ויקשה]?\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003היכל, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ויתן דויד לשלמה בנו את תבנית האולם ואת בתיו ואת גנזכיו ועליתיו וחדריו הפנימים ובית הכפורת\"\u0004 (דברי הימים א' כח, יא) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 על תכנית זו: \u0003\"הכל בכתב מיד ה' עלי השכיל\"\u0004 (דברי הימים א' כח, יט) וממילא כל הכללים שאמרנו אינם חלים על ההיכל עצמו, שכל פרטיו ברוח הקודש ואינם תלויים בהלכות אחרות.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע\u0005]\u0006 פתרון ממקום אחר: שנינו כי \u0003הלשכות\u0004 (חדרים) שבמקדש שהיו \u0003בנויות\u0004 בתחום ה\u0003קודש ופתוחות ל\u0004\u0003חול\u0004 להר הבית \u0003— תוכן חול, וגגותיהן קודש,\u0004 הרי שנתקדשו גגות! ומשיבים: \u0003תרגמא\u0004 \u0005[הסביר אותה]\u0006 \u0003רב חסדא:\u0004 שמדובר בלשכות כאלה הבנויות מתחת לעזרה ו\u0003גגותיהן שוין לקרקע עזרה,\u0004 ולכן גגותיהן קודש — שהן חלק מן העזרה.","ומקשים: \u0003אי הכי אימא סיפא\u0004 \u0005[אם כך אמור את סופה\u0006 של אותה משנה\u0005]\u0006 היו הלשכות \u0003בנויות בחול ופתוחות לקודש — תוכן קודש וגגותיהן חול. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר \u0003בשגגותיהן שוין לקרקע עזרה,\u0004 אם כן \u0003הויא לה\u0004 \u0005[הרי הן]\u0006 הלשכות עצמן כ\u0003מחילות\u0004 שבמקדש וכבר \u0003אמר ר' יוחנן: מחילות לא נתקדשו!\u0004 ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוחנן\u0004 התכוון למחילות \u0003הפתוחות להר הבית\u0004 שלא נתקדשו, \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 האומרת כי תוכן קודש, היא מדברת בלשכות ש\u0003פתוחות לעזרה\u0004 עצמה.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יהודה אומר: מחילות\u0004 ש\u0003מתחת ההיכל\u0004 הריהם \u0003חול!\u0004 ומשיבים: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 — מדובר בה במחילות ה\u0003פתוחות לחול\u0004 שכבר אמרנו שדנים אותן לפי פתחן.","ועוד מציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 מאותו מקור ראיה אחרת: נאמר שם כי \u0003גגו\u0004 של היכל \u0003קודש\u0004 וגג ההיכל הרי לא נזכר בתכנית המקדש בדברי הימים שיכול אתה לומר כפי שדחית כבר, שמתוך שנאמרו כל פרטיו ברוח הקודש אין אתה יכול ללמוד ממנו על הדומה לו, ומכאן שגגיו התקדשו!","ודוחים: \u0003ותסברא\u0004 \u0005[ו\u0006כי יכול \u0005אתה לסבור\u0006 כן\u0005]\u0006 \u0003והא קתני\u0004 \u0005[והרי שנינו]:\u0006 \u0003גגין הללו\u0004 של העזרה ולשכותיה \u0003אין אוכלין שם קדשי קדשים ואין שוחטין שם קדשים קלים\u0004 שאין דינם כעזרה! \u0003ואלא קשיא\u0004 \u0005[ואם כן קשה]\u0006 מה שאמרנו \u0003גגו קדש! אמר רב חמא בר גוריא\u0004 גג ההיכל נקרא קודש רק לצורך אכסנת \u0003אותן שתי אמות,\u0004 (שני מקלות, או מוטות למידת אמה).","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 \u0003שתי אמות היו\u0004 בלשכה הקרויה \u0003שושן הבירה, אחת על קרן מזרחית צפונית\u0004 בלשכה \u0003ואחת על קרן מזרחית דרומית. זו שעל קרן מזרחית צפונית היתה\u0004 מידתה \u0003יתירה על\u0004 אמה \u0003של משה\u0004 רבנו שהיתה בת שישה טפחים \u0003חצי אצבע, וזו שעל קרן מזרחית דרומית היתה יתירה עליה חצי אצבע, נמצאת\u0004 אמה \u0003זו יתירה על\u0004 אמה \u0003של משה אצבע,\u0004","\u0003ולמה\u0004 עשו אמות מוגדלות ו\u0003היו אחת גדולה ואחת קטנה — שיהיו האומנין\u0004 העושים מלאכה בבית המקדש \u0003נוטלין\u0004 שכרם לפי מה שעשו כפי שנמדד באמה \u0003קטנה ומחזירין\u0004 (עושים עבודה) לפי מידת האמה ה\u0003גדולה, כדי שלא יבואו לידי מעילה.\u0004 כי אם טעו בחשבונם ולקחו מעט יותר מן הראוי להם נמצא שהם מועלים בקודש, ולכן תיקנו שיפחיתו קצת משכרם באופן זה, להמנע מטעות אפשרית! ושואלים: \u0003ותרתי\u0004 \u0005[ושתי]\u0006 אמות מוגדלות \u0003למה לי?\u0004 ומשיבים: \u0003אחת\u0004 הקצרה שבין השנים — \u0003לכספא ודהבא\u0004 \u0005[לכסף וזהב],\u0006 שעבודות אלו מודדין באמה היתירה רק חצי אצבע, שלא יפסידו האומנים הרבה, \u0003ואחת — לבנינא\u0004 \u0005[לבנין]\u0006 שאין קפידה בכך.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 חלל \u0003החלונות ועובי החומה\u0004 דינם \u0003כלפנים.\u0004 ומבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003החלונות משכחת לה דשויה\u0004 \u0005[יכול אתה למצוא\u0006 שהם קדושים בקדושת העזרה \u0005שהם שוים]\u0006 \u0003לקרקע\u0004 ה\u0003עזרה\u0004 ונתקדשו בקדושתה. \u0003אלא עובי החומה\u0004 שהוא הרבה למעלה מן הקרקע \u0003היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]\u0006 הזדמנות שיהא עובי החומה שוה לקרקע העזרה? והרי אם לא כן — אף גגות לא נתקדשו!","ומשיבים: \u0003משכחת לה בבר שורא\u0004 \u0005[מוצא אתה אותה בחומה קטנה]\u0006 המצויה בהר הבית שעשויה להיות שוה בגובהה לעזרה, וחומה כעין זו נזכרת \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאבל חל וחומה\"\u0004 (איכה ב, ח) \u0003ואמר ר' אחא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 בשם \u0003ר' חנינא\u0004 כך פירושו של מקרא זה: \u0003שורא ובר שורא\u0004 \u0005[חומה וחומה קטנה],\u0006 האחת לפנים מן השניה וגובה הקטנה כגובה פני העזרה.","\u0003שתי חבורות שהיו אוכלין\u0004 פסח אחד \u0003בבית אחד,\u0004 אינם צריכים לדאוג שייראו כחבורה אחת אלא \u0003אלו הופכין את פניהם הילך\u0004 (לצד זה) \u0003ואוכלין, ואלו הופכין את פניהם הילך\u0004 (לצד זה) \u0003ואוכלין.\u0004 ויכול להיות שיהא \u0003המיחם\u0004 ששותים ממנו מים חמים \u0003באמצע\u0004 בין החבורות, כדי שיהיה נוח לשמש למזוג ממנו לשתי החבורות ו\u0003כשהשמש\u0004 המסייע לשתי החבורות \u0003עומד למזוג\u0004 לחבורה שאינו נמנה עמה \u0003קופץ\u0004 (סוגר) \u0003את פיו ומחזיר את פניו\u0004 שלא יטעה ויאכל בחבורה שאינה שלו \u0003עד שמגיע אצל חבורתו ואוכל\u0004 בה. \u0003והכלה\u0004 שמתביישת מפני אנשים שאינה מכירה מותר שתהא \u0003הופכת את פניה\u0004 מבני החבורה \u0003ואוכלת\u0004 אף שהדבר נראה כאילו היא מנוייה בחבורה אחרת \u0003.\u0004","שואלים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 ואומרים כשיטת \u0003ר' יהודה היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 נאמר: \u0003\"על הבתים אשר יאכלו אתו בהם\"\u0004 (שמות יב, ז) \u0003מלמד\u0004 פסוק זה \u0003שהפסח\u0004 האחד \u0003נאכל בשתי חבורות\u0004 ואפילו כשהן בשתי בתים. \u0003יכול יהא\u0004 אחד ממנויו \u0003האוכל\u0004 ממנו \u0003אוכל בשתי מקומות תלמוד לומר: \"בבית אחד יאכל\"\u0004 (שמות יב, מו)","\u0003מכאן אמרו: השמש\u0004 שנמנה על הפסח ו\u0003אכל כזית\u0004 מן הפסח \u0003בצד התנור\u0004 שנצלה בו הפסח ובזה עשה את עצמו מעין חבורה לחוד, \u0003אי\u0004 \u0005[אם]\u0006 \u0003פקח הוא ממלא כריסו ממנו\u0004 כמה שירצה משום שאחר כך כשיביאו את הפסח למקום אחר לא יוכל עוד לאכול ממנה שהוא כחבורה אחרת, \u0003ואם רצו בני חבורה לעשות עמו טובה\u0004 כדי שיוכל להוסיף ולאכול \u0003באין ויושבין בצדו,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' שמעון אומר\u0004 היפך הדברים יש להבין מן המקראות \u0003\"על הבתים אשר יאכלו אתו בהם\" — מלמד שהאוכל אוכל בשתי מקומות,\u0004"],["\u0003יכול יהא\u0004 הפסח \u0003נאכל בשתי חבורות\u0004 שיתחלקו אוכליו לאחר שקבעו מקום לעצמם \u0003תלמוד לומר: \"בבית אחד יאכל\".\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומשיבים: \u0003ר' יהודה סבר: יש אם למסורת\u0004 כלומר עיקר ההבנה הוא כפי הכתיב ואנו יכולים לקרוא \"בבית אחד יאכל\", שהדברים מוסבים על אוכל הפסח, שעליו לדאוג שיאכל בבית שהוא נמצא בו, אבל אין הקפדה על החבורה. \u0003ור' שמעון סבר: יש אם למקרא\u0004 שעיקר ההבנה היא לפי הקרי, ולפי הקרי \"יאכל\" הכוונה היא לקרבן הפסח שאין לאכלו מחוץ לחבורתו (ר\"ח).","ומכאן לבירור ההלכה \u0003היו יושבין\u0004 חבורה אחת של אוכלי הפסח יחד \u0003ונפרסה מחיצה ביניהם\u0004 ונעשו כשתי חבורות, \u0003לדברי\u0004 ר' יהודה \u0003האומר פסח נאכל בשתי חבורות — אוכלין, לדברי\u0004 ר' שמעון \u0003האומר אין פסח נאכל בשתי חבורות — אין אוכלין\u0004 שהרי עתה הם שתי חבורות חלוקות. ולהיפך: \u0003היו יושבין\u0004 בשתי חבורות כשמחיצה ביניהם \u0003ונסתלקה מחיצה ביניהן, לדברי\u0004 ר' שמעון \u0003האומר האוכל אוכל בשני מקומות — אוכלין\u0004 שהרי מותר לאכול אף במקום אחר; \u0003לדברי\u0004 ר' יהודה \u0003האומר אין האוכל אוכל בשני מקומות — אין אוכלין\u0004 משום שהמקום בו היתה מונחת המחיצה מוסיף חלל חדש ובשלו נעשה המקום כשני מקומות.","","מסופר: \u0003יתיב רב כהנא קא פשיט ליה מפשט\u0004 \u0005[ישב רב כהנא\u0006 ואמר את הדברים הללו \u0005בפשטות]\u0006 כמסקנה אחרונה ובלי שאלות שפריסת מחיצה מחלקתם לשתי חבורות והסרתה גורמת לחלוקת המקום לשנים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: ותיבעי לך איבעיא\u0004 \u0005[ויסתפק לך\u0006 הדבר\u0005],\u0006 שיש מקום לשאול: האם \u0003סילוק מחיצה ועשיית מחיצה\u0004 תוך כדי אכילת הפסח ובאותו בית \u0003מי הוי\u0004 \u0005[האם הוא]\u0006 \u0003כשני מקומות, וכשתי חבורות דמי\u0004 \u0005[נחשב]\u0006 \u0003או לאו?\u0004 ואכן אם מעיינים בשאלה זו אין לה תשובה ברורה והיא נשארת ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה כי \u0003הכלה הופכת את פניה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הופכת פניה? \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מפני שהיא בושה\u0004 מן המסובין המסתכלים בה.","בהקשר למשנה זו מסופר: \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נתן איקלע\u0004 \u0005[נזדמן]\u0006 \u0003לבי\u0004 \u0005[לבית]\u0006 \u0003רב נחמן בר יצחק. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מה שמך\u0004 \u0005[שימך]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003רב הונא, אמרו: ניתיב מר אפוריא\u0004 \u0005[ישב אדוני\u0006 להסב \u0005על המטה]\u0006 בדרך חשיבות! \u0003יתיב\u0004 \u0005[ישב]\u0006 מיד ולא סרב מעט מפני הנמוס, \u0003יהבו ליה כסא\u0004 \u0005[נתנו לו כוס]\u0006 יין לשתות \u0003קבליה בחד זימנא ושתייה בתרי זימני ולא אהדר אפיה\u0004 \u0005[קבל\u0006 את הכוס מיד, \u0005בפעם הראשונה, ושתה אותה בשתי פעמים,\u0006 לגימות, \u0005ולא החזיר פניו\u0006 מן האנשים\u0005]\u0006 וכל הדברים הללו שנראו כיוצאים מדרך הנימוס המקובלת הפליאו את בעלי הבית, \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא קרית לך רב הונא\u0004 \u0005[מה טעם קורא אתה לעצמך רב הונא]?\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003בעל השם אני,\u0004 כלומר הכל קוראים לי כך עוד מצעירותי, ואין בכך צד יהירות. שאלוהו: \u0003מאי טעמא כי אמרו לך ניתיב אפוריא יתבת\u0004 \u0005[מה טעם כאשר אמרו לך לשבת על המטה ישבת\u0006 מיד\u0005]\u0006 ולא סרבת מפני הנימוס? \u0003אמר להו\u0004 \u0005[להם]:\u0006 כבר שנינו \u0003כל מה שיאמר לך בעל הבית עשה, חוץ מצא\u0004 (דבר שאינו הגון),","","ושאלו עוד: \u0003מאי טעמא כי יהבי לך כסא קבלת בחד זימנא\u0004 \u0005[מה טעם כשנתנו לך כוס קבלת\u0006 מיד \u0005בפעם אחת]\u0006 ולא סרבת מפני הנימוס? \u0003אמר להו\u0004 \u0005[להם] :\u0006 \u0003מסרבין לקטן\u0004 ודרך נימוס הוא, \u0003ואין מסרבין לגדול\u0004 שאדם חשוב המבקש דבר מה דרך כבוד היא לציית לו מיד. והוסיפו עוד לשאול: \u0003מאי טעמא אשתיתיה בתרי זימני\u0004 \u0005[מה טעם שתית בשתי פעמים]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003השותה כוסו בבת אחת הרי זה גרגרן,\u0004 השותה ב\u0003שנים\u0004 זוהי \u0003דרך ארץ,\u0004 שותה ב\u0003שלשה\u0004 הריהו \u0003מגסי הרוח\u0004 שמראה שהוא מפונק ומעודן ביותר. ועוד שאלוהו: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אהדרת אפך\u0004 \u0005[החזרת פניך]\u0006 מן האחרים כמנהג\u0005?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"כלה הופכת פניה\" תנן\u0004 \u0005[שנינו],\u0006 ואדם אחר אין צורך שיהפוך פניו כשאוכל. משום דמיון הדברים מביאים סיפור נוסף: \u0003ר' ישמעאל בר' יוסי איקלע\u0004 \u0005[נזדמן]\u0006 \u0003לבי\u0004 \u0005[לבית]\u0006 \u0003ר' שמעון בר' יוסי בן לקוניא, יהבו ליה כסא\u0004 \u0005[נתנו לו כוס]\u0006 יין לשתות \u0003קבליה בחד זימנא ושתייה בחד זימנא\u0004 \u0005[קבל אותו\u0006 מיד \u0005בפעם אחת\u0006 ולא סירב \u0005ושתה אותו בפעם אחת]\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003לא סבר לה מר\u0004 \u0005[וכי אין אדוני סבור,\u0006 מקבל\u0005]\u0006 את ההלכה ש\u0003השותה כוסו בבת אחת — הרי זה גרגרן? אמר להו\u0004 \u0005[להם]\u0006 \u0003לא אמרי\u0004 \u0005[אומרים]\u0006 דבר זה אלא \u0003בכוסך\u0004 שהוא \u0003קטן ויינך\u0004 שהוא \u0003מתוק\u0004 אבל \u0003כריסי רחבה\u0004 ולכך אין כן הדבר אצלי.","","\u0003אמר רב הונא: בני חבורה נכנסין בשלשה\u0004 וכאשר מצויים שלושה צריך השמש להתחיל לשמשם, \u0003ויוצאין אפילו באחד\u0004 ואינם צריכים להמתין לאחרים, ועל השמש לשרת את היחידים שנשארו עד שיסיימו כולם. \u0003אמר רבה: והוא דעייל בעידנא דרגילי למיעל\u0004 \u0005[שנכנס\u0006 האחרון \u0005בזמן שרגילים להכנס]\u0006 לסעודה, ולא מוקדם או מאוחר מידי, \u0003והוא דרגש בהו דיילא\u0004 \u0005[שידע בהם השמש]\u0006 שזה דרכם שמסיים כל אחד מנתו ויוצא ונשארים האחרים עד תום מנתם ואינם סועדים כולם כאחד.","\u0003אמר רבינא: ונותנין\u0004 היחידים שנותרו והאריכו סעודתם \u0003שכר דמים\u0004 על הזמן הנוסף שיצטרך השמש לשמשם, \u0003וצריך האחרון להוסיף דמים\u0004 לשמש על שטרח בו זמן נוסף. ומעירים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו],\u0006 אלא צריך השמש לסייע עד שיגמור אחרון האורחים בלא תוספת תשלום כלשהי.",""],["\u0003האשה בזמן שהיא בבית בעלה\u0004 אם \u0003שחט עליה\u0004 (עבורה) \u0003בעלה\u0004 קרבן פסח \u0003ושחט עליה\u0004 גם \u0003אביה — תאכל משל בעלה\u0004 שמן הסתם דעתה לאכול אצל בעלה, ומסתבר שהתכוונה להימנות על חבורתו. \u0003הלכה רגל ראשון\u0004 שלאחר נישואיה \u0003לעשות\u0004 אותו \u0003בבית אביה\u0004 כדרך שהיה נהוג, אם \u0003שחט עליה אביה ושחט עליה בעלה — תאכל במקום שהיא רוצה\u0004 שבמקרה זה אין להחליט מה הוא המקום שמעדיפה.","\u0003יתום\u0004 שיש לו כמה אפוטרופסין ו\u0003שחטו עליו אפוטרופסין\u0004 וכל אחד מהם צירף אותו לחבורתו — \u0003יאכל במקום שהוא רוצה. עבד של שני שותפין — לא יאכל משל שניהם,\u0004 לא מזה ולא מזה, אלא אם כן הסכימו מראש היכן יאכל. \u0003מי שחציו עבד וחציו בן חורין — לא יאכל משל רבו\u0004 שלאותו מחצית בן חורין שבו לא התכוון בעליו לתת לו מקרבן הפסח במתנה ונמצא שאינו ממנויי פסח זה ולכן צריך הוא להתנות דבר זה מראש.","על ההלכה שבמשנה שבמקרים מסויימים מקום אכילת הפסח יהא כפי רצון האוכל, אומרים: \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 ש\u0003יש ברירה\u0004 כלומר, שאנו מקבלים את ההנחה שבשעה שהאשה תחליט לאכול מזה או מזה יתברר הדבר למפרע עם איזו חבורה היא נמנית, ושאלה זו בדבר ברירה לא סוכמה בהלכה עדיין. ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 שתאכל במקום שהיא \u0003רוצה\u0004 כוונתו \u0003בשעת שחיטה,\u0004 שאז עליה להחליט מה היא רוצה.","\u0003ורמינהו\u0004 \u0005[משליכים\u0006 מראים סתירה\u0005]\u0006 ממקור אחר ששנינו בו: \u0003אשה, רגל הראשון\u0004 אחר הנישואין \u0003אוכלת\u0004 בקרבן פסח \u0003משל אביה. מכאן ואילך, רוצה — אוכלת משל אביה, רוצה\u0004 אוכלת \u0003משל בעלה,\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה]\u0006 ואין כאן סתירה אלא שני מקרים הם, \u0003כאן\u0004 שאמרנו שיכולה תמיד לבחור \u0003ברדופה לילך\u0004 באשה הלהוטה תמיד ללכת לבית אביה ומן הסתם שם מוצא חן בעיניה יותר ולכן גם בשאר השנים עדיין סביר לומר שהיא מתלבטת על איזה קרבן להימנות, ולכך אוכלת לפי בחירתה. \u0003כאן\u0004 במשנתנו, שלדבריה רק בשנה הראשונה אוכלת לפי בחירתה, אבל בשאר השנים פשוט הדבר שאוכלת משל בעלה בלבד, מדובר \u0003בשאינה רדופה.\u0004","וכעין זה מצאנו על מדרש המקראות: \u0003\"\u0004אני חומה ושדי כמגדלות \u0003אז הייתי בעיניו כמוצאת שלום\"\u0004 (שיר השירים ח, י), \u0003ואמר ר' יוחנן: ככלה שנמצאת שלימה בבית חמיה\u0004 והכל מרוצים בה, \u0003ורדופה\u0004 (להוטה) \u0003לילך להגיד שבחה בבית אביה\u0004 איך היא מקובלת בבית חמיה. \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 בדומה לכך: \u0003\"והיה ביום ההוא נאם ה' תקראי אישי ולא תקראי לי עוד בעלי\"\u0004 (הושע ב, יח), ש\u0003אמר ר' יוחנן:\u0004 שתהא \u0003ככלה בבית חמיה\u0004 לאחר נשואיה \u0003ולא ככלה בבית אביה\u0004 שהיא מאורסת עדיין ואין עוד קרבה בין בני הזוג.","כיון שהוזכרו כתובים אלה דורשים אף בפסוקים קרובים: \u0003\"אחות לנו קטנה ושדים אין לה\"\u0004 (שיר השירים ח, ח) \u0003אמר ר' יוחנן: זו\u0004 רמז ליהודי מדינת \u0003עילם, שזכתה ללמוד\u0004 שהיו בין תושביה כאלה שנעשו תלמידי חכמים, אבל \u0003לא זכתה ללמד\u0004 שלא זכו להשפיע וללמד לרבים.","\u0003\"אני חומה ושדי כמגדלות\"\u0004 (שיר השירים ח, י), \u0003אמר ר' יוחנן: \"אני חומה\" — זו תורה, \"ושדי כמגדלות\" — אלו תלמידי חכמים\u0004 המשפיעים לאחרים מחכמת התורה ובכך מגינים הם על דורם כמגדלי שמירה. \u0003ורבא אמר: \"אני חומה\" — זו כנסת ישראל, \"ושדי כמגדלות\" — אלו בתי כנסיות ובתי מדרשות\u0004 שמהם יונקת כנסת ישראל את כוחה הרוחני.","במדרשים בשבח ישראל \u0003אמר רב זוטרא בר טוביה אמר רב: מאי דכתיב\u0004 \u0005[שנאמר] :\u0006 \u0003\"\u0004\u0003אשר בנינו כנטיעים מגודלים בנעוריהם בנותינו כזוית מחטבות תבנית היכל\"\u0004 (תהילים קמד, יב),","\u0003\"אשר בנינו כנטעים\"\u0004 שלא נפגמו ונשברו, אלא הם כנטיעות בריאות, \u0003אלו בחורי ישראל שלא טעמו טעם חטא. \"בנותינו כזוית\" — אלו בתולות ישראל שאוגדות\u0004 (שומרות) \u0003פתחיהן לבעליהן,\u0004 ואינן נבעלות לאחרים. וראיה לדבר שזויות אלה, הן דבר המלא וסגור? ש\u0003כן הוא אומר: \"ומלאו כמזרק כזוית מזבח\"\u0004 (זכריה ט, טו), הרי שלשון \"זווית\" מורה על משמעות מילוי, וכן הוא באשה שהיא מלאת תאווה לבעלה \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ראיה \u0003מהכא\u0004 \u0005[מכאן]\u0006 מפסוק זה \u0003\"מזוינו מלאים מפיקים מזן אל זן\"\u0004 (תהילים קמד, יג)","\u0003\"מחטבות תבנית היכל\" אלו ואלו\u0004 כלומר בחורי ישראל ובתולות ישראל השומרים אל צניעותם \u0003מעלה עליהן הכתוב כאילו נבנה\u0004 ה\u0003היכל בימיהן.\u0004","וכיון שנזכר מקרא מספר הושע דורשים עוד בדברים האמורים שם. נאמר: \u0003\"דבר ה' אשר היה אל הושע\u0004 בן בארי \u0003בימי עזיהו יותם אחז יחזקיה מלך יהודה\u0004 ובימי ירבעם בן יואש מלך ישראל\u0003\"\u0004 (הושע א, א). אמרו חכמים: \u0003בפרק\u0004 (בזמן) \u0003אחד נתנבאו ארבעה נביאים, וגדול שבכולן\u0004 בשנים \u0003הושע, שנאמר: \"תחלת דבר ה' בהושע\"\u0004 (הושע א, ב) שהוא היה הראשון בין בני חבורתו. שאם לא תפרש כן אפשר לשאול: \u0003וכי בהושע דבר תחלה\u0004 מכל הנביאים? \u0003והלא ממשה עד הושע כמה נביאים! אמר ר' יוחנן:\u0004 הכוונה \u0003תחלה לארבעה נביאים שנתנבאו באותו הפרק, ואלו הן: הושע ישעיה עמוס ומיכה.\u0004","\u0003אמר לו הקדוש ברוך הוא להושע: בניך\u0004 כלומר בני ישראל \u0003חטאו. והיה לו\u0004 להושע \u0003לומר\u0004 לה' בתחילה: הלוא \u0003בניך הם, בני חנוניך\u0004 (אהוביך) \u0003הם, בני אברהם יצחק ויעקב, גלגל רחמיך עליהן,\u0004 אבל \u0003לא דיו שלא אמר כך, אלא אמר לפניו: רבונו של עולם, כל העולם שלך הוא,\u0004 וכיון שחטאו ישראל \u0003העבירם\u0004 (החליפם) \u0003באומה אחרת.\u0004","\u0003אמר הקדוש ברוך הוא: מה אעשה לזקן זה\u0004 שאינו יודע לסנגר על ישראל? \u0003אומר לו: לך וקח אשה זונה והוליד לך בנים זנונים, ואחר כך אומר לו: שלחה מעל פניך. אם הוא יכול לשלוח — אף אני אשלח את ישראל. שנאמר: \"ויאמר ה' אל הושע לך קח לך אשת זנונים וילדי זנונים\"\u0004 (הושע א, ב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 לאחר מכן: \u0003\"וילך ויקח את גמר בת דבלים\"\u0004 (הושע א, ג), ודרשו חכמים את שמה \u0003\"גמר\" אמר רב: שהכל גומרים בה\u0004 את ביאתם ותאותם. \u0003\"בת\u0004"],["\u0003דבלים\",\u0004 הוא כפל המלה דיבה, \u0003דבה רעה בת דבה רעה\u0004 כלומר גם היא וגם אמה היו נושא לדיבה ורינון. \u0003ושמואל אמר:\u0004 דבלים היא כפל המלה דבלה, \u0003שמתוקה בפי הכל כדבלה\u0004 שכל הגברים יודעים אותה. \u0003ור' יוחנן אמר: שהכל דשים בה כדבלה,\u0004 שדבלה, שהיא מן התאנים המיובשות וכבושות, נעשית על ידי דישת וכבישת הגרוגרות.","\u0003דבר אחר: \"גמר\", אמר רב יהודה:\u0004 רמז הוא \u0003שבקשו\u0004 הגויים \u0003לגמר\u0004 (לכלות) \u0003ממונן של ישראל בימיה, ר' יוחנן אמר:\u0004 לא בקשו בלבד אלא כך עשו \u0003בזזו וגמרו, שנאמר: \"כי אבדם מלך ארם וישמם כעפר לדש\"\u0004 (מלכים ב' יג, ז).","נאמר: \u0003\"ותהר ותלד לו בן ויאמר ה' אליו קרא שמו יזרעאל כי עוד מעט ופקדתי את דמי יזרעאל על בית יהוא והשבתי ממלכות בית ישראל ותהר עוד ותלד בת ויאמר לו קרא שמה לא רחמה\u0004 כ\u0003י לא אוסיף עוד ארחם את בית ישראל כי נשא אשא להם ותהר ותלד בן ויאמר ה' אליו קרא שמו לא עמי כי אתם לא עמי ואנכי לא אהיה לכם\"\u0004 (הושע א, ג-ט),","\u0003לאחר שנולדו לו שני בנים ובת אחת, אמר לו הקדוש ברוך הוא להושע: לא היה לך ללמוד ממשה רבך?\u0004 שהוא רבם של כל הנביאים \u0003שכיון שדברתי עמו פירש מן האשה, אף אתה — בדול עצמך ממנה\u0004 מאשה זו, \u0003אמר לו: רבונו של עולם יש לי בנים ממנה ואין אני יכול להוציאה ולא לגרשה.\u0004","כיון שכך \u0003אמר לו הקדוש ברוך הוא: ומה אתה שאשתך זונה ובניך בני זנונים ואין אתה יודע אם שלך הן אם של אחרים הן כך\u0004 אתה קשור בהם, \u0003ישראל שהן בני, בני בחוני\u0004 (שנבחנו ועמדו בנסיונות) \u0003בני אברהם יצחק ויעקב,\u0004 והם \u0003אחד מארבעה קנינין שקניתי בעולמי\u0004 כלומר שהם חשובים כל כך שנאמר עליהם שהם קנינו של הקדוש ברוך הוא","ואלו הם: \u0003תורה קנין אחד, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ה' קנני ראשית דרכו\"\u0004 (משלי ח, כב). \u0003שמים וארץ קנין אחד, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ברוך אברם לאל עליון \u0003קנה שמים וארץ\"\u0004 (בראשית יד, יט). \u0003בית המקדש קנין אחד, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ויביאם אל גבול קדשו \u0003הר זה קנתה ימינו\"\u0004 (תהלים עח, נד). \u0003ישראל קנין אחד דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עם זו קנית\"\u0004 (שמות טו, טז) \u0003ואתה אמרת העבירם\u0004 (החליפם) \u0003באמה אחרת!\u0004","\u0003כיון שידע שחטא עמד לבקש רחמים על עצמו\u0004 שימחל לו חטאו שדבר רעה על ישראל. \u0003אמר לו הקדוש ברוך הוא: עד שאתה מבקש רחמים על עצמך בקש רחמים על ישראל שגזרתי עליהם שלש גזירות\u0004 רעות שאמר עליהם \"יזרעאל\" (גלות), \"לא עמי\" ו\"לא רוחמה\" \u0003בעבורך\u0004 משום שקטרגת עליהם.","\u0003עמד ובקש רחמים ובטל גזירה. והתחיל לברכן, שנאמר: \"והיה מספר בני ישראל כחול הים\u0004 אשר לא ימד ולא יספר \u0003והיה במקום אשר יאמר להם לא עמי אתם יאמר להם בני אל חי ונקבצו בני יהודה ובני ישראל יחדיו וזרעתיה לי בארץ ורחמתי את לא רחמה ואמרתי ללא עמי עמי אתה\"\u0004 (הושע ב' א-כה).","\u0003אמר ר' יוחנן: אוי לה לרבנות\u0004 (לשררה) \u0003שמקברת את בעליה\u0004 שמקצרת את ימיהם. וראיה לדבר \u0003שאין לך כל נביא ונביא שלא קיפח\u0004 (איבד) \u0003ארבעה מלכים בימיו,\u0004 כפי שנאמר בהושע, וכן \u0003נאמר\u0004 עוד: \u0003\"חזון ישעיהו בן אמוץ אשר חזה על יהודה וירושלים\u0004 בימי עוזיהו יותם אחז יחזקיהו מלכי יהודה\u0003\"\u0004 (ישעיה א, א), שארבעה מלכים מתו בימיו, ושררתם היא שגרמה להם למות בקיצור ימים והוא האריך ימים מכולם.","\u0003אמר ר' יוחנן מפני מה זכה ירבעם בן יואש מלך ישראל להמנות\u0004 בכתוב \u0003עם מלכי יהודה\u0004 הצדיקים \u0003מפני שלא קבל לשון הרע על עמוס.\u0004","ושואלים: \u0003ומנלן דאימני\u0004 \u0005[ומנין לנו שנמנה]\u0006 עמם? ומשיבים: שנאמר \u0003\"דבר ה' אשר היה אל הושע בן בארי בימי עזיה יותם אחז יחזקיה מלכי יהודה ובימי ירבעם בן יואש מלך ישראל\"\u0004 (הושע א, א).","\u0003ומנלן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003לא קיבל לשון הרע — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישלח אמציה כהן בית אל אל ירבעם מלך ישראל לאמר קשר עליך\u0004 עמוס בקרב בית ישראל וגו'\u0003\"\u0004 (עמוס ז, י), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כי כה אמר עמוס בחרב ימות ירבעם\u0004 וישראל גלה יגלה מעל אדמתו\u0003\"\u0004 (עמוס ז, יא) \u0003אמר\u0004 ירבעם: \u0003חס ושלום אמר אותו צדיק כך\u0004 שירבעם ימות בחרב \u0003ואם אמר — מה אעשה לו\u0004 ומדוע יענש? \u0003שכינה אמרה לו\u0004 והוא חייב לנבא.","\u0003אמר ר' אלעזר: אפילו בשעת כעסו של הקדוש ברוך הוא\u0004 הריהו \u0003זוכר את הרחמים. שנאמר: \"כי לא אוסיף עוד ארחם את בית ישראל\"\u0004 (הושע א, ו), שגם בשעת הדין נזכרת לשון רחמים (\"ארחם\"). \u0003ר' יוסי בר ר' חנינא אמר מהכא\u0004 \u0005[מכאן]\u0006 מהמשך הפסוק: \u0003\"כי נשא אשא להם\",\u0004 משמע שה' מבטיח להם סליחה.","\u0003ואמר ר' אלעזר: לא הגלה הקדוש ברוך הוא את ישראל לבין האומות אלא כדי שיתוספו עליהם גרים, שנאמר: \"וזרעתיה לי בארץ\"\u0004 (הושע ב, כה). \u0003כלום אדם זורע סאה — אלא\u0004 כדי \u0003להכניס כמה כורין\u0004 ואף ישראל יתוספו עליהם עוד מבני הגרים בזמן הגלות.","\u0003ור' יוחנן אמר מהכא\u0004 \u0005[מכאן]\u0006 יש להביא ראיה לרעיון זה שנאמר: \u0003\"ורחמתי את לא רחמה\u0004 ואמרתי ללא עמי עמי אתה\u0003\"\u0004 (הושע ב, כה) כלומר גם אלה שלא היו עם ישראל (\"לא עמי\") יהפכו ליהודים (\"עמי אתה\").","ועוד \u0003אמר ר' יוחנן משום ר' שמעון בן יוחי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אל תלשן עבד אל אדנו פן יקללך ואשמת\"\u0004 (משלי ל, י), \u0003וכתיב: \"דור אביו יקלל ואת אמו לא יברך\"\u0004 (משלי ל, יא), ולכאורה יש לתמוה \u0003משום\u0004 את \u0003אביו יקלל ואת אמו לא יברך אל תלשן?\u0004","ומה הקשר בין הפסוקים \u0003אלא\u0004 בא להדגיש וללמדך \u0003אפילו דור\u0004 של רשעים \u0003ש\u0004את \u0003אביו יקלל ואת אמו לא יברך\u0004 — בכל זאת \u0003אל תלשן עבד אל אדניו. מנלן\u0004 \u0005[מנין לנו]\u0006 ראיה לזה — \u0003מהושע\u0004 שכעס ה' עליו על שקיטרג על ישראל — למרות חטאיהם.","\u0003אמר ר' אושעיא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"צדקת פרזונו בישראל\"\u0004 (שופטים ה, יא), \u0003צדקה עשה הקדוש ברוך הוא בישראל שפזרן לבין האומות\u0004 שאילו הגלה אותם למקום אחד בשעת הגזירה היו חס ושלום מתכלים כאחד. \u0003והיינו דאמר ליה ההוא מינא\u0004 \u0005[זהו שאמר לו מין אחד]\u0006 \u0003לר' חנינא: אנן מעלינן מינייכו\u0004 \u0005[אנחנו\u0006 הגויים \u0005מעולים מכם\u0006 היהודים\u0005]\u0006 לגבי סובלנות, \u0003כתיב בכו\u0004 \u0005[נאמר בכם]:\u0006 \u0003\"כי ששת חדשים ישב שם\u0004 יואב וכל ישראל עד הכרית כל זכר באדום\u0003\"\u0004 (מלכים א' יא, טז), \u0003ואלו אנן איתינכו גבן כמה שני ולא קא עבדינן לכו מידי\u0004 \u0005[ואלו אנחנו אתם נמצאים אצלנו כמה שנים ואין אנו עושים לכם דבר]\u0006 \u0003אמר לו: רצונך יטפל לך תלמיד אחד\u0004 והוא ישיבך תשובה בענין זה.","\u0003נטפל ליה\u0004 \u0005[לו]\u0006 \u0003ר' אושעיא אמר ליה\u0004 \u0005[לו]:\u0006 טעם הדבר אינו משום צדקתכם, אלא \u0003משום דלא ידעיתו היכי תעבדו\u0004 \u0005[משום שאינכם יודעים איך תעשו]\u0006 שבענין זה, \u0003תכלינן כולהו — ליתנהו גבייכו\u0004 \u0005[תכלו את כל\u0006 היהודים \u0005אין הם\u0006 נמצאים \u0005אצלכם]\u0006 \u0003מאי דאיכא גבייכו\u0004 \u0005[\u0006אם תכלו את \u0005מי שנמצאים אצלכם],\u0006 \u0003קרי לכו מלכותא קטיעתא\u0004 \u0005[יקראו לכם מלכות קטועה]\u0006 שהורגת חלק מאנשיה. \u0003אמר\u0004 לו אותו מין: \u0003גפא דרומאי!\u0004 נשבע באלילי רומי, \u0003בהא נחתינן ובהא סלקינן\u0004 \u0005[ב\u0006בעיה \u0005זו אנו עולים וב\u0006בעיה \u0005זו אנו יורדים]\u0006 שאנו מתחבטים באמת תמיד בבעיה זו ואיננו יודעים מה לעשות בישראל.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: מאי דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אלהים הבין דרכה והוא ידע את מקומה\"\u0004 (איוב כח, כג) \u0003יודע הקדוש ברוך הוא את ישראל שאינן יכולין לקבל גזירות אכזריות אדום לפיכך הגלה אותם לבבל\u0004 שאנשיה פחות אכזריים. \u0003ואמר ר' אלעזר: לא הגלה הקדוש ברוך הוא את ישראל לבבל אלא מפני שעמוקה כשאול\u0004 שהרי היא ארץ עמקים ובקעה כדי לרמז להם את מה \u0003שנאמר: \"מיד שאול אפדם ממות אגאלם\"\u0004 (הושע יג, יד). \u0003ר' חנינא אמר: מפני שקרוב לשונם\u0004 של בני בבל, הוא הארמית, \u0003ללשון תורה\u0004 ומסייע הדבר לישראל הגרים בה ללמוד תורה.","\u0003ר' יוחנן אמר: מפני ששיגרן לבית אמן\u0004 שהרי מולדת אבות האומה היא בארם נהריים אשר בבבל. \u0003משל לאדם שכעס על אשתו להיכן משגרה — לבית אמה.\u0004","\u0003והיינו\u0004 \u0005[וזו היא]\u0006 דרשתו של \u0003ר' אלכסנדרי\u0004 ש\u0003אמר: שלשה חזרו למטעתן\u0004 (למקומן הראשון), \u0003אלו הן: ישראל, כסף מצרים, וכתב\u0004 שהיה על \u0003לוחות\u0004 הברית. \u0003ישראל — הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 שחזרו לבבל. \u0003כסף\u0004 שבזזו ישראל מ\u0003מצרים דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי בשנה החמישית למלך רחבעם עלה שושק מלך מצרים על ירושלם\u0004 ויקח את אוצרות בית ה' ואת אוצרות בית המלך ואת הכל לקח\u0003\"\u0004 (מלכים א' יד, כה-כו). \u0003כתב הלוחות דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ואתפוש בשני הלוחות ואשליכם מעל שתי ידי \u0003ואשברם לעיניכם\"\u0004 (דברים ט, יז), ו\u0003תנא\u0004 \u0005[שנויה\u0006 תוספתא\u0005]:\u0006 \u0003לוחות נשברו ואותיות פורחות\u0004 וחוזרות למקומן הראשון לעיני ישראל הרואים זאת.","\u0003עולא אמר:\u0004 שגלו ישראל לבבל \u0003כדי שיאכלו\u0004"],["\u0003תמרים\u0004 הגדלים הרבה בבבל וניתן להשיגם בקלות ובזול \u0003ויעסקו בתורה.\u0004 אגב כך מסופר: \u0003עולא איקלע לפומבדיתא קריבו ליה טירינא דתמרי\u0004 \u0005[עולא הזדמן לפומבדיתא הביאו לו סל תמרים]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 למארחיו: \u0003כמה כי הני בזוזא\u0004 \u0005[כמה כאלה בדינר]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003תלת בזוזא\u0004 \u0005[שלושה\u0006 כאלה \u0005בדינר]\u0006 \u0003אמר: מלא צנא דדובשא בזוזא, ובבלאי לא עסקי באורייתא\u0004 \u0005[מלוא הכד דבש בזוז\u0006 אחד \u0005והבבלים אינם עוסקים בתורה]\u0006 כראוי להם, והרי אין להם צורך לטרוח הרבה במזונותיהם, והיה עליהם לעסוק יותר בתורה.","\u0003בליליא צערוהו\u0004 \u0005[בלילה ציערו אותו\u0006 התמרים\u0005]\u0006 שאכילת תמרים הרבה גורמת לבעיות עיכול והצטער בשלהם כל הלילה. \u0003אמר\u0004 על כך: \u0003מלא צנא סמא דמותא בזוזא בבבל\u0004 \u0005[מלא הכד סם המות\u0006 עולה רק \u0005זוז בבבל]\u0006 ולמרות שניזונים מסם מוות זה, בכל זאת \u0003בבלאי עסקי באורייתא\u0004 \u0005[הבבלים עוסקים בתורה].\u0006","ומכאן חוזרים אנו לענין נבואות נחמה הקשורות גם בנביא הושע. \u0003ואמר ר' אלעזר מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלהי יעקב\u0004 ויורנו מדרכיו ונלכה באורחותיו\u0003\"\u0004 (ישעיה ב, ג), ויש לתמוה: וכי הוא \u0003אלהי יעקב ולא אלהי אברהם ויצחק?\u0004 ומה טעמה של הדגשה זו?","\u0003אלא\u0004 בא הדבר לרמז לנו כי בית ה' יהיה באופן שקראהו יעקב, \u0003לא כאברהם שכתוב בו\u0004 שכינה את מקום המקדש בשעת תפילתו שם \u0003\"הר\", שנאמר: \"אשר יאמר היום בהר ה' יראה\"\u0004 (בראשית כב, יד), \u0003ולא כיצחק שכתוב בו\u0004 שכינהו בשעת תפילתו שם בלשון \u0003\"שדה\", שנאמר: \"ויצא יצחק לשוח בשדה\"\u0004 (בראשית כד, סג), \u0003אלא כיעקב שקראו\u0004 בשעת תפילתו שם \u0003\"בית\", שנאמר: \"ויקרא את שם המקום ההוא בית אל\"\u0004 (בראשית כח, יט).","\u0003אמר ר' יוחנן: גדול קבוץ גליות כיום שנבראו בו שמים וארץ.\u0004 וראיה לדבר ממה \u0003שנאמר: \"ונקבצו בני יהודה ובני ישראל יחדו ושמו להם ראש אחד ועלו מן הארץ כי גדול יום יזרעאל\"\u0004 (הושע ב, ב), וכן נאמר: \u0003\"ויהי ערב ויהי בקר יום אחד\"\u0004 (בראשית א, ה), ולמדים יום יום לגזירה שוה.","במשנה שנינו כי \u0003יתום ששחטו עליו אפוטרופסין\u0004 שלו אוכל במקום שרוצה. ומעירים: \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 ש\u0003יש ברירה\u0004 כי היתום יכול לבחור לאחר השחיטה באיזה פסח יאכל ואז יחשב כאילו היתה דעתו על כך מתחילה. ופתרנו על ידי כך בעיה יסודית אם יש או אין ברירה. כלומר אם מיחסים ערך רטרואקטיבי להחלטה שנתקבלה מאוחר יותר, \u0003אמר ר' זירא:\u0004 אין זו הוכחה, שכן נאמר: \u0003\"\u0004שה לבית אבות \u0003שה לבית\"\u0004 (שמות יב, ג) — \u0003מכל מקום.\u0004 כלומר: אדם לוקח ושוחט עבור בני ביתו הקטנים, ואין צורך להסכמתם לכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"שה לבית\" — מלמד שאדם מביא ושוחט\u0004 קרבן פסח \u0003על ידי\u0004 (עבור) \u0003בנו ובתו הקטנים ועל ידי עבדו ושפחתו הכנענים בין מדעתן בין שלא מדעתן, אבל אינו שוחט על ידי בנו ובתו הגדולים ועל ידי עבדו ושפחתו העברים ועל ידי אשתו אלא מדעתן\u0004 שאלה יש להם אישיות עצמאית ואינו יכול לכפות אותם.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003לא ישחוט אדם לא על ידי בנו ובתו הגדולים ועל ידי עבדו ושפחתו העברים ועל יד אשתו אלא מדעתן. אבל שוחט הוא על ידי בנו ובתו הקטנים ועל ידי עבדו ושפחתו הכנענים בין מדעתן ובין שלא מדעתן, וכולן ששחטו\u0004 הם עצמם פסח \u0003ושחט רבן עליהן — יוצאין בשל רבן ואין יוצאין בשל עצמן\u0004 משום שאין להם רשות לעשות משל עצמם אם רבן מתכוון להאכיל אותן משלו,","\u0003חוץ מן האשה שיכולה למחות\u0004 בבעלה ולומר לו: \"איני ניזונת ואיני עושה עמך מלאכה\", ולכך יכולה אף להקריב משלה.","ושואלים: \u0003מאי שנא אשה\u0004 \u0005[במה שונה אשה]\u0006 ומדוע שונה דינה מדין בנו ובתו הגדולים או עבדו ושפחתו העבריים? \u0003אמר רבא\u0004 הכוונה היא \u0003אשה וכל דדמי לה\u0004 \u0005[אשה וכל הדומה לה]\u0006 שכל אלה שיש להם אישיות עצמאית מבחינה משפטית אם שחטו לעצמם — יוצאים משל עצמם.","ומעירים: \u0003הא גופא קשיא\u0004 \u0005[זו עצמה קשה]\u0006 \u0003אמרת\u0004 תחילה \u0003חוץ מן האשה שיכולה למחות, טעמא\u0004 \u0005[הטעם\u0006 דוקא\u0005]\u0006 \u0003דמחי\u0004 \u0005[שמחתה]\u0006 \u0003הא לא מחי\u0004 \u0005[הרי אם לא מחתה]\u0006 \u0003נפקא\u0004 \u0005[יוצאת]\u0006 \u0003בשל בעלה, והא קתני רישא\u0004 \u0005[הרי שנינו בראש\u0006 אותה ברייתא\u0005]\u0006 שאינו שוחט על ידי בנו \u0003ולא על ידי אשתו אלא מדעתן\u0004 ונדייק: \u0003הא סתמא\u0004 \u0005[הרי סתם]\u0006 אם לא גלתה דעתה — אינה יוצאת!","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אלא מדעתן\" לאו דאמרי אין\u0004 \u0005[לא שאמרו כן]\u0006 וגילו דעתם בפירוש שמסכימים, \u0003אלא בסתמא\u0004 \u0005[בסתם]\u0006 הרי זה כמדעתם, שבודאי הסכימו לכך, \u0003לאפוקי היכא דאמור לא\u0004 \u0005[להוציא מקום שאמרו לא].\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 שנינו שם: \u0003כולם ששחטו ושחט רבן עליהן — יוצאין בשל רבן דבסתמא\u0004 \u0005[ב\u0006מקרה של \u0005סתם\u0006 שלא מחו ולא הסכימו במפורש\u0005]\u0006 \u0003וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003חוץ מן האשה מפני שיכולה למחות,\u0004 משמע שבסתם אינו כמדעתם!","\u0003אמר רבא: כיון ששחטו\u0004 לעצמן \u0003אין לך מיחוי גדול מזה\u0004 שכאילו שבכך אמרו במפורש שלא רצו לאכול משל הבעל והאב אלא לאכול משל עצמם.","שנינו במשנה: \u0003עבד של שני שותפים\u0004 אינו יכול לאכול לא משל זה ולא משל זה. \u0003רמי ליה\u0004 \u0005[הקשה לו,\u0006 הראה סתירה\u0005]\u0006 \u0003רב עינא סבא\u0004 \u0005[הזקן]\u0006 \u0003לרב נחמן: תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 \u0003עבד של שני שותפין לא יאכל משל שניהן. והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003רצה — מזה אוכל, רצה — מזה אוכל!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003עינא סבא\u0004 \u0005[הזקן]\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 אמר לו \u0003פתיא אוכמא\u0004 \u0005[סיר שחור]\u0006 שהוא כינוי חיבה לאדם שיגע ועמל הרבה עד שהושחר מעמל התורה, \u0003מיני ומינך תסתיים שמעתתא\u0004 \u0005[ממני וממך תסתיים\u0006 ותתברר \u0005ההלכה].\u0006 \u0003מתניתין\u0004 \u0005[משנתינו],\u0006 מדובר \u0003בדקפדי אהדדי\u0004 \u0005[שמקפידים\u0006 הבעלים \u0005זה על זה]\u0006 ואינם רוצים ליהנות זה מזה ולכן בהאכלת העבד המשותף גם כן מקפידים, \u0003ברייתא — דלא קפדי אהדדי\u0004 \u0005[בברייתא\u0006 מדובר \u0005שאינם מקפידים זה על זה]\u0006 וכיון שכך יכול לאכול משל מי שירצה.","שנינו במשנה: \u0003מי שחציו עבד וחציו בן חורין לא יאכל משל רבו,\u0004 ונדייק: \u0003משל רבו הוא\u0004 ש\u0003לא יאכל, אבל משל עצמו — יאכל. והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לא יאכל לא משלו ולא משל רבו.\u0004","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003כאן\u0004 שאמרנו שלא יאכל לא משל עצמו ולא משל רבו, מדובר \u0003כמשנה ראשונה\u0004 כדעת בית הלל שהעבד נחשב מחצה לעצמו ומחצה לרבו. \u0003כאן\u0004 שאמרנו שיכול לאכול משל עצמו, מדובר \u0003כמשנה אחרונה,\u0004 ששינו את מעמדו של מי שחציו עבד. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שחציו עבד וחציו בן חורין\u0004 עושה סדר זה: \u0003עובד את רבו יום אחד ואת עצמו\u0004 (עבור עצמו) כאדם חופשי \u0003יום אחד,\u0004 אלו \u0003דברי בית הלל, בית שמאי אומרים:\u0004"],["\u0003תקנתם\u0004 אמנם \u0003את רבו\u0004 שעל ידי סדור זה אינו מפסיד כלום, אולם \u0003את עצמו לא תקנתם.\u0004 כיצד? \u0003לישא שפחה — אינו יכול שכבר חציו בן חורין\u0004 וישראל בן חורין אסור בשפחה, \u0003לישא בת חורין אינו יכול שעדיין חציו עבד\u0004 ואסור לבת ישראל להנשא לעבד. ואם תאמר \u0003יבטל\u0004 מנשואין כלל, \u0003והלא לא נברא העולם אלא לפריה ורביה, שנאמר: \"לא תהו בראה אלא לשבת יצרה\"\u0004 (ישעיה מה, יח). \u0003אלא מפני תיקון העולם כופין את רבו ועושה אותו בן חורין, וכותב\u0004 העבד \u0003שטר על חצי דמיו\u0004 ומשלם לרבו.","\u0003וחזרו בית הילל\u0004 בהם \u0003להורות כבית שמאי.\u0004 ולפי משנה אחרונה זו שלאחר חזרת בית הלל, נמצא שמי שחציו עבד הריהו כבן חורין גמור, שהרי רבו חייב לשחררו.","\u0003האומר לעבדו: צא ושחוט עלי\u0004 (עבורי) \u0003את הפסח,\u0004 ולא פירש מה לשחוט עבורו. אם \u0003שחט גדי — יאכל, שחט טלה — יאכל. שחט גדי וטלה — יאכל מן הראשון\u0004 שנשחט והשני ישרף.","אמר לו רבו מה לשחוט לפסח אבל \u0003שכח\u0004 העבד \u0003מה אמר לו רבו כיצד יעשה? ישחט טלה וגדי,\u0004 ויתנה \u0003ויאמר: אם גדי אמר לי רבי\u0004 הרי \u0003גדי\u0004 יהיה לקרבנו \u0003שלו וטלה\u0004 יהיה לקרבן \u0003שלי. ואם טלה אמר לי רבי\u0004 הרי \u0003הטלה שלו וגדי שלי\u0004 ולאחר זמן יבחר הרב מה שירצה.","\u0003שכח\u0004 גם \u0003רבו מה אמר\u0004 לו הרי אינו יכול לאכול אף מאחד מהם, שמא לא זה הוא הקרבן שנמנה עליו, לכן \u0003שניהן\u0004 גם הגדי וגם הטלה \u0003יצאו לבית השריפה\u0004 שהם קרבנות שאין להם אוכלים, אבל \u0003פטורין\u0004 האדון והעבד \u0003מלעשות פסח שני\u0004 שהרי מכל מקום נשחט האחד ונזרק דמו כדין, אף שאין ידוע איזהו.","על ההלכה הראשונה שבמשנה תוהים: \"שחט גדי — יאכל, שחט טלה — יאכל\", \u0003פשיטא\u0004 \u0005[פשוט\u0006 מובן מאליו\u0005]\u0006 שאם לא פירש רצונו, הרי כל מה שנשחט עבורו הריהו כמנוי עליו! ומתרצים: אם \u0003שחט גדי יאכל, אף על גב\u0004 \u0005[אף על פי]\u0006 שהאדון \u0003רגיל בטלה\u0004 שבכל שנה לוקח טלה לפיסחו אם שחט עבדו גדי — יאכלנו, וכן אם \u0003שחט טלה יאכל, אף על גב\u0004 שהאדון \u0003רגיל בגדי.\u0004","אמרנו במשנה: אם \u0003שחט גדי וטלה יאכל מן הראשון\u0004 ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין נמנין על שני פסחים כאחד\u0004 והרי כאן יש לו גם טלה וגם גדי לפניו והוא בורר מביניהם לאחר שחיטה!","ומשיבים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003במלך ומלכה\u0004 וכיוצא בהם כל הסומכים במאכלם על עבדיהם ונוח להם בכל מה שנשחט עבורם, ולכך משנשחט הראשון הרי קיבלוהו כקרבנם והשני נשחט בחינם.","\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין נמנין על שני פסחים כאחד, ומעשה במלך ומלכה שאמרו לעבדיהם: צאו ושחטו עלינו את הפסח, ויצאו ושחטו עליהן שני פסחים. באו ושאלו את המלך\u0004 איזה מהם רצונו לאכול, \u0003אמר להם: לכו ושאלו את המלכה. באו ושאלו מן המלכה אמרה להם: לכו ושאלו את רבן גמליאל\u0004 ויפסוק הלכה.","\u0003באו ושאלו את רבן גמליאל אמר להם: מלכה ומלך דדעתן קלה עליהן\u0004 ואין זה חשוב בעיניהם אם יאכלו טלה או גדי, שאינם מקפידים על איבוד הכסף, ולא על המאכל, שכן יש להם רוב מעדנים — \u0003יאכלו מן הראשון\u0004 שנשחט. אבל \u0003אנן\u0004 \u0005[אנחנו]\u0006 שאר אנשים \u0003לא נאכל לא מן הראשון ולא מן השני\u0004 שהרי אין נמנים על שני פסחים כאחד. אגב סיפור זה מספרים מעשה דומה.","\u0003ושוב פעם אחת נמצאת הלטאה\u0004 מתה \u0003בבית המטבחים\u0004 של בית המלך והלטאה היא מן השרצים שנבלתם מטמאה במגע \u0003ובקשו לטמא כל הסעודה כולה, באו ושאלו את המלך, אמר להם: לכו ושאלו את המלכה, באו ושאלו את המלכה, אמרה להם: לכו ושאלו את רבן גמליאל\u0004","\u0003באו ושאלו אותו אמר להם: בית המטבחים\u0004 היה \u0003רותח\u0004 (חם מאוד) \u0003או צונן? אמרו לו: רותח. אמר להם: לכו והטילו עליה\u0004 על הלטאה \u0003כוס של צונן. הלכו והטילו עליה כוס של צונן וריחשה\u0004 (וזחלה מעט) ונמצא שעדיין היא חיה וכיון שכך \u0003טהר רבן גמליאל כל הסעודה כולה\u0004 שהרי שרץ חי אינו מטמא.","והעירו: \u0003נמצא מלך תלוי במלכה, ונמצאת מלכה תלויה ברבן גמליאל, ונמצאת כל הסעודה\u0004 של המלך \u0003תלויה ברבן גמליאל.\u0004","שנינו במשנה: אם \u0003שכח\u0004 העבד \u0003מה שאמר לו רבו\u0004 יקח טלה וגדי ויתנה ויאמר: אם גדי אמר לי רבי, הרי גדי שלו והטלה שלי, ותוהים: \u0003שלי?!\u0004 כיצד יכול העבד לומר שטלה זה הוא שלו הלוא לעבד אין זכות של קנין פרטי לפי הכלל: \u0003מה שקנה עבד קנה רבו,\u0004 ואם כן לא נפתר דבר על ידי כך.","\u0003אמר אביי\u0004 כך יש לעשות: \u0003הולך\u0004 העבד \u0003אצל רועה הרגיל רבו אצלו, דניחא ליה בתקנתא דרביה\u0004 \u0005[\u0006שאותו רועה \u0005נוח לו,\u0006 שרוצה \u0005בתקנת בעליו\u0006 של העבד\u0005]\u0006 שייצא ידי חובת הפסח \u0003ומקני ליה\u0004 \u0005[ומקנה לו]\u0006 הרועה \u0003חד מינייהו\u0004 \u0005[אחד מהם]\u0006 \u0003על מנת שאין לרבו רשות בו\u0004 ועל סמך תנאי זה קונה העבד לעצמו, וכיון שקנה לעצמו יכול העבד להתנות מה שלו ומה של רבו.","שנינו במשנה שאם פירש הרב לעבד על העדפתו ואחר כך \u0003שכח רבו\u0004 עצמו \u0003מה שאמר לו\u0004 ישרפו שני הפסחים ופטורים הוא ורבו מפסח שני. \u0003אמר אביי: לא שנו\u0004 שנפטרו בפסח זה \u0003אלא ששכח אחר זריקה, דבעידנא דאיזריק דם הוה חזי לאכילה\u0004 \u0005[שבזמן שנזרק הדם\u0006 של שניהם \u0005היה\u0006 הפסח \u0005ראוי לאכילה]\u0006 ונשחט הפסח בכשרות. ואף שלאחר מכן נשכח ואינם יכולים לאכלו מכל מקום פטור מפסח שני, \u0003אבל שכח לפני זריקה, דכי איזריק דם לא הוה חזי לאכילה\u0004 \u0005[שכאשר נזרק הדם לא היה ראוי לאכילה]\u0006 — \u0003חייב בפסח שני.\u0004","\u0003איכא דמתני לה אברייתא\u0004 \u0005[יש ששונים את\u0006 דבריו אלה של אביי \u0005על ברייתא]\u0006 והיא: \u0003חמשה שנתערבו עורות פסחיהן זה בזה, ונמצאת יבלת באחד מהן\u0004 שנתברר איפוא שהיה הפסח פסול מעיקרו הרי כל הפסחים \u0003כולן יוצאין לבית השריפה\u0004 מחשש שכל אחד מהם הוא הקרבן הפסול, \u0003ופטורין\u0004 בעליהם \u0003מלעשות פסח שני.\u0004","ועל כך \u0003אמר אביי: לא שנו אלא שנתערבו\u0004 העורות \u0003לאחר זריקה, דבעידנא דאיזריק דם מיהא הוה חזי לאכילה\u0004 \u0005[שבזמן שנזרק הדם על כל פנים היו ראויים\u0006 שאר הקרבנות \u0005לאכילה]\u0006 \u0003אבל נתערבו\u0004 העורות \u0003לפני זריקה — חייבין לעשות פסח שני.\u0004","ומעירים: \u0003מאן דמתני אמתניתין\u0004 \u0005[מי ששונה\u0006 ומייחס דבריו אלה של אביי \u0005לגבי משנתנו],\u0006 שאף שודאי שתי הבהמות כשרות לקרבן, מכל מקום חוסר ידע לגבי זהות המנויים שנוצר לפני זריקת הדם פוסל את שתיהן, \u0003כל שכן\u0004 שאומר הוא כן לגבי ה\u0003ברייתא,\u0004 שהרי בברייתא בהמה אחת ודאי פסולה לקרבן אולם \u0003מאן דמתני אברייתא\u0004 \u0005[מי ששונה\u0006 מייחס זאת, \u0005לברייתא],\u0006 \u0003אבל אמתניתין\u0004 \u0005[על משנתנו]\u0006 \u0003לא.\u0004 והטעם: \u0003כיון\u0004 ששני הפסחים \u0003כשרין נינהו\u0004 \u0005[הם]\u0006 \u0003דאי אידכר הוי חזי לאכילה\u0004 \u0005[שאם\u0006 היה \u0005נזכר היה ראוי לאכילה]\u0006 אחד מהם, \u0003קמי שמיא גליא\u0004 \u0005[לפני השמים,\u0006 ה', \u0005גלוי]\u0006 איזה מהם היה ראוי, שלא היה אחד מהם פסול ממש בגופו אלא נפסל מתוך חוסר ידיעה. מה שאין כן בברייתא שאחד מן הפסחים היה ודאי פסול.","לגופה של אותה ברייתא דנים \u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא שכולם \u0003פטורין מלעשות פסח שני.\u0004 ושואלים: \u0003והא איכא חד דלא נפיק\u0004 \u0005[והרי יש אחד\u0006 מהם \u0005שלא יצא]\u0006 בפסח ראשון שאמנם אותם ארבעה שנשחט עליהם הפסח בכשרות ואינם יודעים איזה הוא — הם ודאי יצאו ידי חובת הפסח, אולם זה שהיתה יבלת בפסחו הרי בשעת זריקה לא היה קרבנו ראוי, ולא יצא ידי חובה!","ומשיבים: \u0003משום\u0004 ש\u0003לא איפשר\u0004 לעשות אחרת; שכיצד יעשו? \u0003ליתי כל חד וחד פסח\u0004 \u0005[\u0006אם \u0005יביא כל אחד ואחד\u0006 מהם \u0005פסח\u0006 שני\u0005],\u0006 אם כן \u0003קא מייתי\u0004 \u0005[הריהו מביא]\u0006 \u0003חולין לעזרה\u0004 שהרי \u0003ארבעה מינייהו עבדי להו\u0004 \u0005[שארבעה מהם\u0006 כבר \u0005עשו אותו]\u0006 את הפסח.","ואם \u0003ליתי כולהו חד פסח\u0004 \u0005[שיביאו כולם פסח אחד]\u0006 כחבורה אחת, אם כן \u0003נמצא פסח נאכל שלא למנויו\u0004 שהרי ארבעה מהם כבר נמנו ויצאו ידי חובתם בפסח ראשון, ואף פסח שני נפסל בכך.","על תרוץ זה תוהים: \u0003האי מאי\u0004 \u0005[זה מהו],\u0006 כלומר מה טעם בדבר? הלוא אפשר לעשות כך: \u0003ניתי כל חד מינייהו פסחו\u0004 \u0005[יביא כל אחד מהם את פסחו]\u0006 \u0003וניתני, ונימא\u0004 \u0005[ויתנה ויאמר]:\u0006 \u0003אי דידי בעל מום האי דאייתי השתא ניהוי פסח\u0004 \u0005[אם שלי\u0006 היה הקרבן \u0005בעל המום\u0006 הרי \u0005זה שאני מביא כעת יהא פסח]\u0006 \u0003ואי דידי תם\u0004 \u0005[ואם שלי תם,\u0006 שלם בלא מום, היה\u0005],\u0006 \u0003האי דאייתי השתא ניהוי שלמים\u0004 \u0005[זה שהבאתי עכשיו יהיה שלמים]!\u0006","ודוחים: \u0003לא אפשר\u0004 לעשות כן,"],["\u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003חזה ושוק דכהנים הוא דאכלי ליה\u0004 \u0005[שהכהנים הם שאוכלים אותו]\u0006 מקרבנות השלמים, אבל מקרבן פסח אין הכהנים מקבלים חזה ושוק, ומה יעשו בקרבן זה שהוא ספק פסח ספק שלמים? שהרי אם יתנו מחמת הספק את החזה והשוק לכהן והוא אכן פסח ולא שלמים — נמצאו מאכילים את הכהנים מפסח שלא נמנו עליו!","ומציעים: \u0003וניתי כל חד וחד כהן בהדיה\u0004 \u0005[ויביא כל אחד ואחד כהן עמו]\u0006 בפסח השני וימנה אותו על פסחו, ויתן לכהן את החזה והשוק ממה נפשך, אם קרבן זה שלמים הוא — הרי קיבל את החזה והשוק כדין שלמים, ואם הוא פסח — הרי אוכל הוא בתורת פסח.","ודוחים: \u0003האי כהן היכי דמי\u0004 \u0005[אותו כהן מה טיבו בדיוק]\u0006 \u0003אי דעביד פסח\u0004 \u0005[אם\u0006 היה זה כהן שכבר \u0005עשה פסח]\u0006 ראשון, \u0003דילמא האי\u0004 \u0005[שמא\u0006 קרבן \u0005זה]\u0006 שמביא אכן \u0003פסח הוא\u0004 ולא שלמים \u0003ונמצא פסח נאכל שלא למנויו\u0004 שהרי כהן זה כבר יצא בפסח ראשון ואינו יכול להמנות שוב על הפסח השני. \u0003ואי דלא עביד פסח\u0004 \u0005[ואם\u0006 הוא כהן \u0005שלא עשה פסח]\u0006 ראשון, \u0003דילמא\u0004 \u0005[שמא]\u0006 קרבן מסויים זה \u0003שלמים הוא,\u0004 ונמצא ש\u0003לא עביד\u0004 \u0005[לא עשה]\u0006 אותו כהן \u0003פסח\u0004 כלל!","ומציעים תיקון: \u0003וניתי\u0004 \u0005[ושיביאו]\u0006 \u0003כל חמשה\u0004 יחד \u0003חד כהן דלא עבד פסח\u0004 \u0005[כהן אחד שלא עשה פסח]\u0006 \u0003ונימני עילויה הני חמשה פסחים\u0004 \u0005[וימנה על כל חמשת הפסחים הללו]\u0006 ש\u0003ממה נפשך\u0004 מוכרח אתה לומר: \u0003איכא חד דלא עביד פסח וקא נפקי ביה\u0004 \u0005[יש אחד שלא עשה קרבן פסח ויצאו בו]\u0006 בעל הקרבן והכהן, וכיון שרק אחד הוא קרבן פסח אין בו חשש של אכילת שני פסחים כאחד.","\u0003אלא\u0004 הטעם שאין מביאים פסח שני הריהו \u0003משום דקא\u0004 \u0005[שהוא]\u0006 \u0003ממעיט באכילת שלמים\u0004 ש\u0003אלו\u0004 ה\u0003פסח\u0004 נאכל \u0003ליום ולילה\u0004 וה\u0003שלמים\u0004 נאכלים \u0003לשני ימים ולילה אחד.\u0004 ונמצא שממעטים בזמן אכילת שלמים. ואף שנותר ממנו ליום השני, אם הוא שלמים — הריהו מותר באכילה. ומכיון שאין יודעים מהו , הרי כל הנותר ביום השני נשרף ונמצא שורף קדשים כשרים.","ועוד מציעים: \u0003וניתי\u0004 \u0005[ושיביא]\u0006 \u0003מותר הפסח\u0004 כלומר קרבן שהוקדש לפסח ומשום סיבה כלשהי לא הוקרב, שדינו כשלמים אלא שנאכל ליום ולילה בלבד.","\u0003ונימא\u0004 \u0005[ויאמר]\u0006 יתנה כך: \u0003אי דידי\u0004 \u0005[אם\u0006 הקרבן \u0005שלי]\u0006 היה \u0003בעל מום, האי דאייתי השתא ניהוי פסח\u0004 \u0005[זה שאני מביא עכשיו שיהיה פסח],\u0006 \u0003אי דידי תם הוא ניהוי האי דאייתי השתא שלמים\u0004 \u0005[אם שלי תם,\u0006 שלם בלי מום \u0005היה\u0006 ויצאתי בו ידי חובה \u0005מה שאני מביא עכשיו יהיה שלמים]\u0006 והרי שנינו כי \u0003מותר הפסח נאכל ליום ולילה אחד\u0004 ואם כן דינו כשלמים וכפסח ואין בו החשש שממעטים בזמן אכילתו.","ומקשים: \u0003וכי מפרישין\u0004 מלכ\u0003תחלה למותרות\u0004 הלוא אין לעשות כן, וממילא לא יהיה לאותם אנשים מותר הפסח ולא יוכלו להשתמש בתקנה זו. ומקשים: \u0003ונטרחו ונייתי מותר הפסח\u0004 \u0005[ושיטרחו\u0006 וימצאו אדם שנשאר לו פסח ויביאו מותר הפסח\u0005]\u0006 וייאכל ליום ולילה!","\u0003אלא\u0004 טעם שאין מביאים פסח שני הוא \u0003משום סמיכה,\u0004 ש\u0003אילו פסח לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003סמיכה\u0004 כדין שלמים, ואם יסמוך ואינו אלא פסח — נמצא שעושה עבודה בקדשים. \u0003ואילו מותר בעי\u0004 \u0005[צריך]\u0006 \u0003סמיכה.\u0004 ומשום כך אי אפשר להשתמש בתקנה שהוצעה קודם.","ועדיין שואלים: \u0003הא תינח\u0004 \u0005[נניח]\u0006 שקיים נימוק זה ב\u0003קרבן אנשים\u0004 (גברים) שהם סומכים על קרבנם, אבל אם אירע כל הענין ב\u0003קרבן נשים\u0004 שמדין תורה אינן חייבות לסמוך על קרבנן, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא\u0004 יש לחזור מנמוק זה ולומר כי הטעם הוא \u0003משום מתנות\u0004 דם הקרבן על המזבח. ש\u0003אילו\u0004 דמו של קרבן \u0003פסח\u0004 — ניתן ב\u0003מתנה\u0004 (בזריקה) \u0003אחת, ואילו שלמים\u0004 ניתנים ב\u0003שתים שהן ארבע\u0004 שמזים את הדם שתי הזאות על זויות המזבח, והדם ניתז לשני צדדים כך שכל מתנה נעשית כשתים.","ועדיין תוהים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 מה החשיבות בדבר \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל\u0004 אותן דמים של קרבנות \u0003הניתנין על מזבח החיצון שנתנן במתן אחת — כפר,\u0004 שלכתחילה יש ליתן שתי מתנות שהן ארבע, אבל בדיעבד יוצאים בנתינת דם פעם אחת,","\u0003אלא\u0004 הטעם שאין מביאים פסח שני \u0003משום\u0004 ש\u0003אילו פסח\u0004 דינו \u0003בשפיכה\u0004 שאת דמו רק שופכים בנחת על קיר המזבח \u0003ואילו שלמים\u0004 דינם \u0003בזריקה\u0004 עליו.","ומקשים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 (מה החשיבות בדבר) \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל\u0004 הקרבנות \u0003הניתנין בזריקה שנתנן בשפיכה — יצא,\u0004 ומשיבים: \u0003אימר דקא אמרינן\u0004 \u0005[אמור שאנחנו אומרים]\u0006 שיצא בכל אלה הרי זה רק \u0003דאי עבד\u0004 \u0005[אם עשה]\u0006 מעשה אולם \u0003לכתחלה נמי?!\u0004 \u0005[לכתחילה גם כן]\u0006 יעשו שלא כדין? וכיון שמפני טעם זה אי אפשר להקריב פסח זה לכתחילה פטורים כולם מלעשותו.","\u0003האומר לבניו: הריני שוחט את הפסח על מי שיעלה מכם ראשון לירושלים\u0004 ויגיע אליה, \u0003כיון שהכניס הראשון\u0004 מן האחים \u0003ראשו ורובו\u0004 לעיר \u0003זכה ומזכה את אחיו עמו\u0004 בחלקו.","ושואלים: \u0003שמע מינה\u0004 \u0005[\u0006האם \u0005נלמד מכאן]\u0006 כי \u0003יש ברירה,\u0004 שהרי בשעת השחיטה אין הוא יודע מראש איזה בן יגיע ראשון וכאשר יגיע אותו בן יתברר הדבר למפרע!","\u0003אמר ר' יוחנן\u0004 שאין להוכיח דבר זה מכאן, כי באמת האב מינה את בניו כולם, אלא \u0003כדי לזרזן במצות קאמר\u0004 \u0005[אמר],\u0006 שרצה לזרזן במצוות ולכן יצר תחרות ביניהם שהראשון שיגיע יזכה עבור אחיו, אבל אין לכך משמעות הלכתית.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 כדברי ר' יוחנן \u0003דקתני\u0004 \u0005[ש\u0006הרי \u0005שנינו]:\u0006 \u0003ומזכה אחיו עמו, אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003דאמנינהו מעיקרא שפיר\u0004 \u0005[שמינה אותם\u0006 האב \u0005מתחילה —\u0006 \u0005יפה],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003לא אמנינהו מעיקרא\u0004 \u0005[מינה אותם מתחילה],\u0006 אם כן \u0003לבתר דשחיט מי קא מתמנו\u0004 \u0005[אחרי ששחט האם\u0006 יכולים \u0005להתמנות]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נמנין\u0004 על הפסח או \u0003מושכין ידיהן ממנו עד שישחט\u0004 ולא אחר כך. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא,","ומוסיפים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 שאין זה פגם במינוי אלא ענין של זריזות בלבד: \u0003מעשה\u0004 במקרה כגון זה \u0003וקדמו בנות לבנים ונמצא בנות זריזות ובנים שפלים\u0004 (עצלים) ואם כן ענין של זריזות וחוסר זריזות יש כאן, אבל אין זה פסול מאכילת קרבן הפסח.","\u0003לעולם נמנין עליו\u0004 על הפסח \u0003עד שיהיה בו כזית לכל אחד ואחד\u0004 ולא פחות. ועוד: \u0003נמנין ומושכין את ידיהן ממנו עד שישחט\u0004 בלבד. \u0003ר' שמעון אומר: עד שיזרק את הדם.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 במשפט הראשון של המשנה? ומשיבים: \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003דאף על גב דאימני עליו\u0004 \u0005[שאף על פי שנמנו עליו]\u0006 על הפסח \u0003חבורה זו, חוזרת\u0004 חבורה זו \u0003ונמנין עליו\u0004 בני \u0003חבורה אחרת\u0004 ואין גבול למספר האנשים כל עוד יש כזית לכל אחד.","שנינו במשנה: \u0003נמנין ומושכין את ידיהן עד שישחט\u0004 ור' שמעון אומר עד שיזרק הדם. \u0003אמר אביי: מחלוקת\u0004 תנא קמא ור' שמעון לענין גבול הזמן \u0003לימשך\u0004 מן הקרבן","\u0003דרבנן סברי\u0004 \u0005[שהחכמים סוברים]\u0006 שמן הכתוב \"ואם ימעט הבית \u0003מהיות משה\u0004 ולקח הוא ושכנו הקרוב אל ביתו במכסת נפשות איש לפי אכלו תכוסו על השה\" (שמות יב, ד) יש לדרוש: \u0003מחיותיה דשה\u0004 \u0005[מחיותו\u0006 חייו \u0005של השה]\u0006 ומכאן שרק בעוד השה חי אפשר להמשך ממנו. \u0003ור' שמעון סבר\u0004 דרש \"מהיות\" — \u0003מהוייתיה דשה\u0004 \u0005[מהוויתו של השה]\u0006 כל עוד לא הושלמו בו כל עבודות הקדש, לאמר עד שיזרק הדם. \u0003אבל\u0004 לענין \u0003לימנות\u0004 על הפסח \u0003דברי הכל\u0004 זמנו \u0003עד שישחט\u0004 בלבד, \u0003דאמר קרא\u0004 \u0005[שאמר המקרא]:\u0006 \u0003\"במכסת נפשת\" והדר\u0004 \u0005[ואחר]\u0006 כך \u0003\"תכסו\"\u0004 (במובן — תשחטו, כבארמית) ללמד ש\"מכסת נפשות\" של המנין על השה היא דווקא לפני השחיטה.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003נמנין\u0004 מקרבן הפסח \u0003ומושכין את ידיהן ממנו עד שישחט, ר' שמעון אומר: נמנין עד שישחט, ומושכין\u0004 את ידיהם ממנו אפילו \u0003עד שיזרק הדם.\u0004"],["\u0003הממנה עמו אחר בחלקו\u0004 בלא לקבל רשות משאר בני החבורה \u0003רשאין\u0004 שאר \u0003בני החבורה ליתן לו את\u0004 חלקו \u0003שלו, והוא\u0004 וחברו שנמנה על פסחו \u0003אוכל משלו, והן,\u0004 השאר, \u0003אוכלין משלהן,\u0004 שיכולים הם לומר שאין רצונם שיאכל עוד אדם אחר ויתמעט חלקם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003בני חבורה שהיו ידיו של אחד מהן יפות\u0004 כלומר, בלשון נקיה, שהיה ממהר לחטוף ולאכול, \u0003מהו שיאמרו לו\u0004 בני חבורה \u0003טול חלקך\u0004 לפי השיעור המגיע לך \u0003וצא,\u0004 ואכול חלקך לבדך ואל תחסר מחלקנו. \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003מצי אמר להו הא קבילתון\u0004 \u0005[יכול הוא לומר להם: הרי קבלתם,\u0006 את חברתי\u0005]\u0006 \u0003או דילמא מצו למימר ליה: כי קבלינן — לתיקוני זביחה, אדעתא דאכלת טפי מינן לא קבלינך\u0004 \u0005[או שמא יכולים לומר לו: כאשר קבלנו\u0006 אותך היה זה \u0005כדי לתקן את הזביחה\u0006 להקריב יחד את הפסח ולמנוע מצב שנשאר ממנו בשל מיעוט הסועדים ויהיה נותר, אבל \u0005על דעת שתאכל יותר מאתנו לא קיבלנוך].\u0006 ומביאים ראיות שונות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003הממנה אחרים עמו על חלקו — רשאין בני חבורה ליתן לו את\u0004 חלקו \u0003שלו\u0004 לחוד, \u0003והוא\u0004 ואותם אחרים שנמנו על חלקו \u0003אוכל את שלו והן אוכלין את שלהן. מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של דבר? — \u0003לאו משום דהוי ליה\u0004 \u0005[האם לא משום שנעשה לו]\u0006 \u0003כ\u0004אילו \u0003ידים של אחד מהן יפות\u0004 שהרי הוא וחברו אוכלים יותר מחלק אחד. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 שמי ש\u0003ידיו יפות מצי אמר להו קבילתון\u0004 \u0005[יכול לומר להם קבלתם אותי\u0006 על עצמכם\u0005]\u0006 \u0003ניהוי האי\u0004 \u0005[שיהא זה]\u0006 שמינה אחר עמו כאילו היו \u0003ידיו יפות,\u0004 ונוטל כפליים!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא, דעות\u0004 כלומר אנשים נוספים בעלי דעות שונות, \u0003שאני\u0004 \u0005[שונה],\u0006 שיכולים בני החבורה לומר \u0003אי נמי תרוייהו כחד מבני חבורה הוא דאכלי\u0004 \u0005[אם גם שניהם כ\u0006אדם \u0005אחד מבני חבורה אוכלים]\u0006 ובכל זאת \u0003מצי אמרי ליה דלא ניחא לן אינש נוכרא גבן\u0004 \u0005[יכולים\u0006 לומר לו: \u0005לא נוח לנו באדם זר\u0006 שיהא \u0005אצלנו]\u0006 ואין איפוא להוכיח מכאן.","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לשאלה ממה ששנינו במשנה: \u0003השמש שאכל כזית בשר\u0004 מן הפסח \u0003בצד התנור, אם היה פקח ממלא כריסו ממנו\u0004 שם, שהרי קבע לעצמו מקום אכילה שם ואסור לו לאכול במקום נוסף. \u0003אם רצו בני חבורה לעשות טובה עמו — באין ויושבין בצדו ואוכלין,\u0004 אלו \u0003דברי ר' יהודה.\u0004 ונדייק: \u0003רצו — אין\u0004 \u0005[כן]\u0006 ואם \u0003לא רצו — לא,\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 לא יעשו כן? \u0003נימא להו\u0004 \u0005[שיאמר להם]:\u0006 \u0003הא קבילתון\u0004 \u0005[הרי קבלתם]\u0006 על עצמכם את חברתי, ורשאי אני לאכול כל צרכי מחלקי, ועליכם לבוא משום כך לידי כדי שאוכל לאכול כראוי.","ודוחים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דאמרי ליה: כי קבלינך — אדעתא דנטרחך קמן\u0004 \u0005[שאומרים לו: כאשר קיבלנוך היה זה על דעת שתטרח לפנינו\u0006 כשמש\u0005]\u0006 \u0003למטרח לן לדידך לא קבלינך\u0004 \u0005[שאנחנו נטרח עבורך\u0006 ונשב במקום הנוח לך \u0005לא קיבלנוך].\u0006","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון מפורש לשאלה זו מן התוספתא: \u0003בני חבורה שהיו ידו של אחד מהן יפות רשאין לומר לו: טול חלקך וצא. ולא עוד,\u0004 לא רק בחבורת פסח \u0003אלא אפילו חמשה ועשו סיבולת\u0004 (סעודת רעים משותפת) בשאר ימות השנה \u0003רשאין לומר\u0004 למי שידיו יפות: \u0003טול חלקך וצא. שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הדין.","על לשונה של תוספתא זו שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות הלשון \u0003'ולא עוד'\u0004 מה חידוש יש בדבר? ומשיבים: \u0003לא מיבעיא קאמר\u0004 \u0005[\u0006בסגנון \u0005\"לא נצרכה\" אמר].\u0006 \u0003לא מבעיא פסח\u0004 \u0005[לא נצרכה\u0006 לומר \u0005בפסח]\u0006 שיש להם נימוק תקף, \u0003דמצי אמרי ליה: כי קבלינך לתקוני זביחה\u0004 \u0005[שיכולים הם לומר לו: כאשר קבלנוך\u0006 הרי היה זה \u0005כדי לתקן את הזבח]\u0006 שאנחנו צריכים מספר מסוים של אנשים, אבל לא לאכילה משותפת. \u0003אלא אפילו סיבולת נמי\u0004 \u0005[גם כן]\u0006 \u0003דצוותא בעלמא הוא\u0004 \u0005[שחברות,\u0006 שיתוף, \u0005בלבד הוא]\u0006 \u0003רשאין לומר לו: טול חלקך וצא.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]:\u0006 \u0003הא לא איבעיא לן\u0004 \u0005[\u0006בעיה \u0005זו לא נסתפקה לנו]\u0006 אם יכולים בני חבורה לומר לאחד מהמנויים שידיו יפות טול חלקך, \u0003אלא הכי הוא דאיבעיא לן\u0004 \u0005[כך נסתפק לנו]:\u0006 \u0003בני חבורה רשאין לחלק\u0004 לשתי חבורות גם אם אין טעם מיוחד בדבר \u0003או אינן רשאין לחלק?\u0004","\u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון: \u0003בני חבורה שהיו ידיו של אחד מהן יפות — רשאין לומר לו: טול חלקך וצא.\u0004 נלמד מכאן: אם היו \u0003ידיו יפות — אין\u0004 \u0005[כן],\u0006 אם \u0003אין ידיו יפות — לא.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 שאין רשאים להיחלק ללא סיבה.","ואגב הדבר מסופר מעשה שהיה: \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע עריבו ריפתא בהדי הדדי\u0004 \u0005[ערבו את לחמם זה עם זה]\u0006 לאכול בצוותא, \u0003אדאכיל רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע חדא\u0004 \u0005[\u0006פרוסה \u0005אחת]\u0006 \u0003אכיל רב פפא ארבע\u0004 פרוסות, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פלג לי\u0004 \u0005[חלק לי]\u0006 את הסעודה, שאוכל לאכול את חלקי. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קבילתון\u0004 \u0005[קבלתם\u0006 על \u0005עצמכם\u0006 את חברתי\u0005],\u0006","\u0003איתיביה כל הני תיובתא, ושני כדשנינן\u0004 \u0005[הקשה לו כל אותן קושיות\u0006 שהקשינו והוכחות שהבאנו \u0005ותירץ לו כפי שתירצנו]\u0006 ששם מדובר במקרה מיוחד. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו במפורש בענין \u0003בני חבורה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם דאמרי ליה כי קבלינך לתיקוני זביחה\u0004 \u0005[שם שאומרים לו\u0006 החברים \u0005כאשר קיבלנו אותך\u0006 היה זה \u0005כדי לתקן את הזבח]\u0006 אבל בסעודת רעים אם מקבלים אדם מקבלים אותו לצורך כל הסעודה בכל דרך וכמות שיאכל. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 מענין \u0003סיבולת, פלג ליה\u0004 \u0005[חלק לו].\u0006","בהזדמנות אחרת \u0003אזל\u0004 ר' הונא בנו של ר' יהושע \u0003עריב בהדי רבינא\u0004 \u0005[עירב\u0006 את סעודתו \u0005יחד עם רבינא]\u0006 \u0003אדאכיל\u0004 \u0005[עד שאכל]\u0006 \u0003רב הונא, בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע חדא\u0004 \u0005[\u0006פרוסה \u0005אחת]\u0006 \u0003אכיל\u0004 \u0005[אכל]\u0006 \u0003רבינא תמניא\u0004 \u0005[שמונה].\u0006 \u0003אמר\u0004 רב הונא בהיתול: מוטב להשתתף עם \u0003מאה פפי ולא חדא רבינא\u0004 \u0005[מאה\u0006 רב \u0005פפא ולא רבינא אחד]\u0006 ששותפות עמו קשה יותר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הממנה אחרים עמו על פסחו ועל חגיגתו\u0004 (חגיגת ארבעה עשר בניסן) והוא מקבל מהם כסף עבור חלקם — \u0003מעות שבידו חולין\u0004 ואין בהן קדושה. \u0003והמוכר עולתו ושלמיו\u0004 לאחר — \u0003לא עשה ולא כלום\u0004 שאין תוקף למכר זה כל עיקר \u0003ומעות כל שהן\u0004 אותו הכסף שקבל \u0003יפלו לנדבה\u0004 לעולות ציבור במקדש.","ומקשים: \u0003וכי מאחר\u0004 ש\u0003לא עשה ולא כלום מעות אמאי\u0004 \u0005[מדוע]\u0006 \u0003יפלו לנדבה?\u0004 הרי הן חולין גמורים! \u0003אמר רבא: קנסא\u0004 \u0005[קנס]\u0006 שקנסו אותו חכמים שלא כדי יעשה כן. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"כל שהן\"\u0004 ששנינו שם — הכוונה \u0003אף על גב דלא הוו שוו אלא ארבעה\u0004 \u0005[אף על פי שאין שוים\u0006 קרבנות אלה \u0005אלא ארבעה]\u0006 זוזים \u0003ויהבו ליה\u0004 \u0005[ונתנו לו]\u0006 \u0003חמשה\u0004 והיתה בכך טעות \u0003אפילו בההיא יתירא נמי קנסוהו רבנן\u0004 \u0005[אפילו באותו\u0006 דינר \u0005יתר גם כן קנסו אותו חכמים]\u0006 שיפול לנדבה ואינו נחשב כמתנה.","\u0003אמר עולא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' אושעיא: איפשר ידעי חברין בבלאי טעמא דהאי מילתא\u0004 \u0005[שמא יודעים חברנו הבבליים טעמו של דבר זה],\u0006 שהרי \u0003זה\u0004 בעל הטלה \u0003הפריש טלה לפסחו\u0004 וחלה עליו איפוא קדושה, \u0003וזה הפריש מעות לפסחו\u0004 ומעות אלה קודש הן ובהן הוא קונה חלק מן הקרבן, \u0003היאך הקדש חל על הקדש\u0004 כיצד יכול להיות שהקדש של המעות חל על טלה ההקדש, \u0003דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003מעות שבידו חולין,\u0004 וכיצד נתחללו אותן מעות על אותו פסח שהיה אף הוא מוקדש מתחילתו?"],["\u0003אמר אביי: אי לאו דאוקמיה\u0004 \u0005[אם לא היה מעמיד,\u0006 מסביר\u0005]\u0006 \u0003ר' אושעיא לההיא\u0004 \u0005[לאותה\u0006 משנה\u0005]\u0006 ששנינו שאיסור אתנן חל על מוקדשים \u0003בממנה זונה על פסחו\u0004 כאתנן והיה אומר כי אותה משנה כשיטת \u0003רבי היא\u0004 שקרבן פסח הוא רכוש בעליו לכל דבר ולכן יכול להמנותה עליו ובכך חל עליו איסור אתנן, \u0003הוה מוקמינא לה לההיא\u0004 \u0005[הייתי מעמיד אותה]\u0006 את המשנה הזו \u0003בקדשים קלים, ואליבא\u0004 \u0005[ועל פי\u0006 שיטת\u0005]\u0006 \u0003ר' יוסי הגלילי\u0004 ש\u0003אמר: קדשים קלים ממון בעלים הוא\u0004 ויש לבעלים אפשרות מסוימת לעשות בהם כבשלהם עד זמן שחיטתם ובכלל זה גם להשתמש בהם כאתנן ולכן גם איסור אתנן חל עליהם,","\u0003אבל בפסח לא משייר איניש\u0004 \u0005[ב\u0006קרבן \u0005פסח\u0006 עצמו \u0005אין אדם משייר]\u0006 וכשהוא מקדישו לכך הוא מקדיש את כולו, ואילו בהקדש \u0003מעות ודאי משייר איניש\u0004 \u0005[אדם]\u0006 \u0003דמעיקרא כי מפריש להו — אדעתא דהכי מפריש להו\u0004 \u0005[שמתחילה כשהוא מפריש אותן על דעת כן מפריש אותם]\u0006 שלא תחול עליהן קדושה גמורה, אלא שיוכל לתת את הכסף ככסף חולין עבור שיתופו בקרבן הפסח","\u0003והא\u0004 \u0005[ו\u0006דבר \u0005זה]\u0006 כשיטת \u0003רבי היא, ומשום הכי\u0004 \u0005[כך]\u0006 \u0003מעות שבידו חולין,\u0004 ש\u0003בפסח לא משייר איניש\u0004 \u0005[אדם]\u0006 \u0003ובמעות ודאי משייר איניש\u0004 \u0005[אדם]\u0006","\u0003וההיא דקא מוקי לה ר' אושעיא כרבי — לא מוקמינא ליה אנא כרבי\u0004 \u0005[ואותה\u0006 משנה \u0005שמעמיד אותה ר' אושעיא\u0006 כשיטת \u0005רבי, אין אני מעמיד אותה\u0006 כשיטת \u0005רבי]\u0006 שלדעתו \u0003בפסח לא משייר איניש\u0004 \u0005[אדם]\u0006 ואילו \u0003במעות משייר איניש\u0004 \u0005[אדם]\u0006 \u0003דמעיקרא כי מפריש להו אדעתא דהכי מפריש להו\u0004 \u0005[שמתחילה כשהוא מפריש אותן על דעת כן מפריש אותן]\u0006","\u0003והא\u0004 \u0005[ו\u0006את \u0005זו]\u0006 את הברייתא שלנו שעסקנו בה \u0003ליכא לאוקמי כר' יוסי\u0004 \u0005[אי אפשר להעמידה כר' יוסי]\u0006 \u0003דהא תני בה\u0004 \u0005[שהרי שנינו בה]:\u0006 \u0003המוכר עולתו ושלמיו — לא עשה ולא כלום.\u0004 ואילו לשיטת ר' יוסי שלמים ממונו הוא, ואם מכרם — הרי זה מכור.","אולם \u0003השתא דאוקמיה\u0004 \u0005[עכשיו שהעמיד\u0006 הסביר\u0005]\u0006 \u0003ר' אושעיא לההיא\u0004 \u0005[לאותה]\u0006 משנה \u0003בממנה זונה על פסחו,\u0004 וכשיטת \u0003רבי היא, שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003דסבירא ליה\u0004 \u0005[שסבור הוא]\u0006 כי אף \u0003בפסחו\u0004 עצמו \u0003משייר איניש\u0004 \u0005[אדם]\u0006 ואינו כמקדיש את כולו, אלא מניח מקום שכל הרוצה ישתתף בו וישלם מקצתו עד שעת שחיטה וכל שכן שבמעות הפסח אדם מתיר לעצמו. ובכך תשובה לשאלת עולא (או ר' אושעיא לשיטה אחרת) איך הקדש מעות הפסח חל על הקדש טלה פסח ויוצאות המעות לחולין. שהרי מתחילה אינם אלא חולין ושלו הם ושיטת רבי.","ושואלים: \u0003מאי היא\u0004 \u0005[מה היא]\u0006 על מה דבר \u0003ר' אושעיא\u0004 שאביי מתייחס אליו? ומשיבים שהדבר מתייחס למה \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003נתן לה\u0004 לזונה דברים שהיו \u0003מוקדשין\u0004 כקרבנות \u0003באתננה — הרי אלו מותרין,\u0004 אף שאסור להקריב אתנן זונה, כיון שהיו מוקדשים אין האיסור יכול לחול עליהם.","נתן לה \u0003עופות\u0004 של \u0003חולין — הרי אלו אסורין\u0004 להקדישן. ויש חידוש בהלכה זו, \u0003שהיה בדין\u0004 לומר אחרת: \u0003ומה אם\u0004 קרבנות \u0003מוקדשים שהמום פוסל בהן\u0004 גם לאחר שהוקדשו, בכל זאת \u0003אין\u0004 האיסור של \u0003אתנן\u0004 זונה \u0003ומחיר\u0004 כלב \u0003חל עליהן, עופות שאין המום פוסל בהן\u0004 שכן אף עוף בעל מום כשר לקרבן \u0003אינו דין שאין\u0004 איסור \u0003אתנן ומחיר חל עליהם? תלמוד לומר: \"\u0004לא תביא אתנן זונה ומחיר כלב בית ה' אלהיך \u0003לכל נדר\"\u0004 (דברים כג, יט) — \u0003לרבות את העופות\u0004 שאף הם באים בנדר.","ומעתה לצד שני: נלמד \u0003קל וחומר למוקדשין\u0004 שיחול עליהם איסור אתנן אף לאחר הקדשתם, \u0003מעתה: מה עופות שאין המום פוסל בהן — אתנן ומחיר חל עליהן,\u0004 קרבנות \u0003מוקדשין שהמום פוסל בהן — אינו דין שאתנן ומחיר חל עליהן? תלמוד לומר: \"לכל נדר\" — פרט לנדור\u0004 כבר.","וממדרש הלכה זו נדייק: \u0003אלא טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003\"נדר\", הא לאו הכי הוה אמינא\u0004 \u0005[הרי אם לא היה כך הייתי אומר]\u0006 אף \u0003מוקדשים חל איסור אתנן עליהן\u0004 ויש לתמוה \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין אדם אוסר דבר שאינו שלו\u0004 והמוקדשים כיון שהקדישם כבר הריהם רכוש גבוה, ואין אדם יכול לאסור דבר שאינו שלו!","\u0003אמר ר' אושעיא:\u0004 מדובר כאן \u0003בממנה זונה על פסחו\u0004 שהוא נותן לה חלק בטלה שהוקדש כבר לפסח ושיטת \u0003רבי היא\u0004 שקרבן הפסח הריהו רכוש בעליו לענין זה.","לגוף הדברים שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הוא אותו דבר שאמרנו בשם \u0003רבי?\u0004 ומשיבים: \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על הכתוב \u0003\"ואם ימעט הבית מהיות משה\u0004 ולקח הוא ושכנו הקרוב אל ביתו\u0003\"\u0004 (שמות יב, ד), והוא נדרש כאן שאם \"ימעט הבית\" ואין לו לבעל השה די מעות כדי צורכו לצרכי הפסח הרי \"מהיות משה\" דרש \u0003החייהו\u0004 לבעל הבית \u0003משה,\u0004 שיטול מעות משכנו וימננו על הפסח ובאותם מעות יקנה צרכיו וזהו דווקא כשחסר לו \u0003מכדי אכילה, ולא מכדי מקח\u0004 שהוא נזקק למעות אף לצרכים אחרים.","\u0003רבי אומר: אף מכדי מקח, שאם אין לו\u0004 מעות לצרכי עצמו — \u0003ממנה אחרים על פסחו ועל חגיגתו, ומעות שבידו חולין הן, שעל מנת כן הקדישו ישראל את פסחיהן\u0004 מלכתחילה.","\u0003רבה ור' זירא\u0004 נחלקו בבירור הדברים \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 היה זקוק \u0003בעצים לצלייתו\u0004 של קרבן הפסח \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 \u0003דכיון דתקנתא דפסח הוא — כגופא דפסח דמי\u0004 \u0005[שכיון שלתקנתו של הפסח הוא —\u0006 \u0005כגופו של הפסח נחשב]\u0006 ומותר להמנות לצורך כך אחרים \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה בזקוק לכסף כדי לקנות \u0003מצה ומרור.\u0004","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 \u0003הא אכילה אחריתי היא\u0004 \u0005[זו אכילה אחרת היא]\u0006 ואיננה שייכת לפסח ואסור להמנות אחר על הפסח לשם כך. \u0003ורבי סבר: כיון\u0004 ש\u0003הכשירו דפסח הוא\u0004 שהרי הפסח נאכל על מצות ומרורים \u0003כגופא דפסח דמי\u0004 \u0005[כגופו של פסח\u0006 הוא \u0005נחשב]\u0006","\u0003וחד אמר\u0004 \u0005[ואחד\u0006 מהם \u0005אמר]:\u0006 \u0003במצה ומרור נמי כולי עלמא לא פליגי\u0004 \u0005[גם כן הכל אינם חלוקים],\u0006 שכיון שנאמר: \u0003\"על מצות ומררים יאכלהו\"\u0004 (שמות יב, ח), ש\u0003כיון\u0004 ש\u0003מכשירין\u0004 של ה\u0003פסח נינהו — כפסח דמי\u0004 \u0005[הם —\u0006 \u0005כפסח נחשבים]\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה כגון \u0003ליקח בו חלוק, ליקח בו טלית, רבנן סברי\u0004 \u0005[חכמים סבורים]\u0006 \u0003\"מהיות משה\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 והכוונה היא \u0003החייהו לשה\u0004 ודאג לעניני אכילת הפסח אבל לעצמך לא, \u0003ורבי סבר: החיה עצמך\u0004 בכל דבר \u0003משה.\u0004","ושואלים: ולשיטת \u0003אביי\u0004 ש\u0003אמר: אי לאו דאוקמה\u0004 \u0005[אם לא העמידה]\u0006 \u0003ר' אושעיא לההיא\u0004 \u0005[לאותה\u0006 משנה\u0005]\u0006 \u0003בממנה זונה על פסחו ורבי היא הוי מוקמינן לה\u0004 \u0005[היינו מעמידים\u0006 ברייתא \u0005זו]\u0006 \u0003בקדשים קלים ואליבא\u0004 \u0005[ולפי שיטת]\u0006 \u0003ר' יוסי הגלילי,\u0004 ש\u0003אמר קדשים קלים ממון בעלים הוא, אבל בפסח לא משייר איניש\u0004 \u0005[אין אדם משייר]\u0006 לעצמו בקדושתו ומקדיש כולו","\u0003הא קתני בהדיא\u0004 \u0005[הרי שנוי במפורש]\u0006 שלא כדבריו: \u0003שעל מנת כן הקדישו ישראל את פסחיהן\u0004 שהפסח עצמו אינו מוקדש לחלוטין ואפשר למכור. ודוחים: \u0003אימא\u0004 \u0005[אמור\u0006 תקן\u0005]\u0006 בלשון זו: \u0003שעל מנת כן הקדישו ישראל מעות פסחיהן\u0004 אבל הפסח עצמו כולו מוקדש.","\u0003זב שראה שתי ראיות\u0004 של זוב שדינו שהוא טמא טומאה חמורה, ואם עברו עליו שבעה ימים שלא ראה בהם זוב (\"נקיים\") וטבל הריהו נטהר ואם חל שביעי שלו בערב פסח הרי \u0003שוחטין עליו\u0004 (בשבילו) \u0003בשביעי,\u0004 שהרי בלילה יוכל לאכול מן הפסח. \u0003ראה שלש\u0004 ראיות שאינו נטהר טהרה גמורה עד שיוסיף ויביא קרבן ביום השמיני — \u0003שוחטין עליו\u0004 את הפסח אם חל ערב פסח \u0003בשמיני שלו\u0004 ויביא קרבנו ביום זה ובלילה יאכל.","\u0003שומרת יום כנגד יום\u0004 שאשה שראתה דם בימים שאינם ימי נידתה, שאם תראה שלוש פעמים — הרי היא טמאה בזיבה, וכשראתה רק יום או יומיים היא \"שומרת\" (ממתינה) יום אחד למחרת ראייתה, אם תטהר \u0003שוחטין עליה\u0004 ביום \u0003שני\u0004 שלה שכיוון שספרה לטהרתה מקצת היום, הריהו ככולו ודי לה בכך, \u0003ראתה שני ימים — שוחטין עליה בשלישי,\u0004","\u0003והזבה\u0004 שראתה שלושה ימים וצריכה עכשיו לספור לטהרתה שבעה ימים נקיים וצריכה להביא קרבן טהרה בשמיני \u0003שוחטין עליה\u0004 ביום \u0003השמיני.\u0004","\u0003אמר רב יהודה אמר רב: שוחטין\u0004 קרבן פסח \u0003וזורקין\u0004 את דמו \u0003על\u0004 (עבור) \u0003טבול יום\u0004 (מי שנטמא וכבר טבל ביום ארבעה עשר בניסן ויטהר בערב) וגם עבור \u0003מחוסר כפורים\u0004 שנטהר ואינו חסר אלא הבאת כיפורים שיביא קרבן כפרה, שאלה יהיו ראויים לאכול מן הקרבן בלילה."],["\u0003ואין שוחטין וזורקין על טמא שרץ\u0004 אף שבידו לטבול בו ביום ויהא דינו כטבול יום! \u0003ועולא אמר: אף שוחטין וזורקין על טמא שרץ.\u0004","ושואלים: לשיטת \u0003רב, מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003טבול יום דחזי לאורתא\u0004 \u0005[\u0006שהוא \u0005ראוי\u0006 להיות טהור \u0005לערב]\u0006 \u0003טמא שרץ נמי חזי לאורתא\u0004 \u0005[גם כן ראוי לערב]\u0006 שבוא הערב מטהרו! ומשיבים: \u0003מחוסר טבילה\u0004 הוא וכיון שמחוסר הוא מעשה של טבילה אינו ראוי עדיין.","ומקשים: אם כן \u0003טבול יום נמי\u0004 \u0005[גם כן]\u0006 \u0003מחוסר הערב שמש!\u0004 ומשיבים: \u0003שמשא ממילא ערבא\u0004 \u0005[השמש ממילא שוקעת]\u0006 ואין הוא צריך לעשות מעשה בכך, ולכן אין הדבר נחשב כמחוסר מעשה.","ומקשים: אם כן \u0003מחוסר כפורים נמי\u0004 \u0005[גם כן]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 הוא \u0003מחוסר כפרה\u0004 מעשה של הבאת קרבן כפרתו! ומשיבים: \u0003שקינו בידו\u0004 שזוג התורים או בני היונה (\"קן\") שצריך לכפרה נמצא כעת בידו ועומדים להקריבו.","ומקשים: אם כן \u0003טמא שרץ נמי\u0004 \u0005[גם כן]\u0006 נאמר בו: \u0003הרי מקוה לפניו\u0004 ויטבול! ומשיבים: בטמא שרץ יש לחשוש \u0003דילמא פשע\u0004 \u0005[שמא יתרשל]\u0006 ולא יטבול. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003מחוסר כפורים נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש \u0003דילמא פשע\u0004 \u0005[שמא יתרשל]\u0006 ולא יקריב! ומשיבים: \u0003כגון דמסרינהו\u0004 \u0005[שמסר אותם\u0006 את קרבנותיו\u0005]\u0006 \u0003לבית דין\u0004 של כהנים ואז אין לחשוש עוד,","וכדברי \u0003רב שמעיה,\u0004 ש\u0003אמר: חזקה אין בית דין של כהנים עומדין משם\u0004 ממקום מושבם במקדש \u0003עד שיכלו מעות שבשופרות\u0004 כלומר: כל הכסף שנצטבר בקופה המיועדת לקינים דואגים להוציאו ולהקריב את כל הקרבנות של אותו יום,","ושואלים: האם לשיטת \u0003רב, מדאורייתא מיחזא חזי ורבנן הוא דגזרו ביה\u0004 \u0005[מן התורה ראוי הוא\u0006 טמאי שרץ שישחטו עבורו אלא \u0005חכמים הם שגזרו בו]\u0006 אולם אם כן, \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003אמר רב\u0004 לענין ציבור שהיה חציו טהור וחציו טמא \u0003מטמאין אחד מהם בשרץ\u0004 כדי שיהא רוב צבור טמא, ויעשו הכל בטומאה, ואם טמא שרץ ראוי מן התורה הריהו איפוא כטהור גמור ואיך יוכרע דינו של כל הציבור בשלו לעשות את הפסח בטומאה","\u0003אלא\u0004 יש לומר כי לשיטת \u0003רב מדאורייתא נמי לא חזי\u0004 \u0005[מן התורה גם כן אינו ראוי]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"איש איש כי יהיה טמא לנפש...\u0004 ועשה פסח לה' בחודש השני בארבעה עשר יום\u0003\"\u0004 (במדבר ט, ט-י). \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 בכל אלה הקרויים טמאי מתים (\"טמא לנפש\") ואפילו \u0003שחל שביעי שלו להיות בערב הפסח\u0004 שאם יזו עליו בו ביום יטהר לגמרי \u0003דהיינו\u0004 \u0005[שזהו]\u0006 \u0003טומאת שרץ\u0004 ובכל זאת \u0003אמר רחמנא: נידחי\u0004 \u0005[אמרה התורה: שידחה]!\u0006","\u0003וכי תימא ממאי דהכי\u0004 \u0005[ואם תאמר: מנין שכך]?\u0006 שמדובר בטמא שרץ, אולי המדובר בטמא מת וכפי שאכן נאמר בפסוק (\"טמא לנפש\"), וטמא מת אינו ראוי לערב?","ומשיבים: \u0003סבר לה כר' יצחק\u0004 ש\u0003אמר:\u0004 אותם אנשים טמאים שבאו לשאול את משה במדבר \u0003טמאי מת מצוה היו שחל שביעי שלהן להיות בערב הפסח, שנאמר: \"ולא יכלו לעשת הפסח ביום ההוא\"\u0004 (במדבר ט, ו) ונדייק: \u0003ביום ההוא הוא שאינן יכולין לעשות, אבל למחר יכולין לעשות\u0004 אם היו נטהרים בו ביום ובכל זאת \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003נדחו\u0004 \u0005[שידחו].\u0006","\u0003תנן\u0004 \u0005[שנינו במשנה]:\u0006 \u0003זב שראה שתי ראיות שוחטין עליו בשביעי\u0004 שלו כשחל בארבעה עשר בניסן. \u0003מאי לאו דלא טביל\u0004 \u0005[האם לא\u0006 מדובר כאן בזב \u0005ש\u0006עדיין \u0005לא טבל]\u0006 שלא היה סיפק בידו לטבול בו ביום ו\u0003שמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003שוחטין וזורקין על טמא שרץ\u0004 שדרגת טומאתו זהה לזב בעל שתי ראיות! וקשה על רב.","ודוחים: \u0003לא,\u0004 יש לומר \u0003דטביל\u0004 \u0005[שטבל\u0006 כבר\u0005].\u0006 ומקשים: \u0003אי טביל מאי קא משמע לן\u0004 \u0005[אם טבל מה משמיע לנו\u0006 בכך\u0005]\u0006 הלוא בשעת אכילה יהא טהור ודאי! ומשיבים \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003מחוסר\u0004 עדיין \u0003הערב שמש, קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דשמשא משילא ערבא\u0004 \u0005[שהשמש ממילא שוקעת]\u0006 ואין זה קרוי מחוסר מעשה.","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 \u0003מדקתני סיפא\u0004 \u0005[ממה ששנינו בסופה\u0006 של משנתינו\u0005]:\u0006 \u0003ראה שלש ראיות שוחטין עליו בשמיני. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 \u0003זב שראה שתי ראיות שוחטין עליו בשביעי\u0004 ומדובר כאן \u0003דטביל\u0004 \u0005[שטבל כבר]\u0006 הזב הרי \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 לומר הלכה נוספת זו שיש בה חידוש","\u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003ראה שתי ראיות\u0004 והריהו עומד \u0003בשביעי הוא\u0004 ש\u0003לא מחוסר מעשה\u0004 שהרי כבר טבל \u0003אבל ראה שלש\u0004 והריהו עומד \u0003בשמיני\u0004 ש\u0003מחוסר מעשה\u0004 שהרי הוא \u0003מחוסר כפרה לא\u0004 יהא דינו כן, לכן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 שהוא \u0003מחוסר כפרה\u0004 בכל זאת \u0003שוחטין וזורקין עילויה\u0004 \u0005[עליו].\u0006","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהאמור במשנה \u0003ראה שתי ראיות\u0004 ועומד \u0003בשביעי\u0004 מדובר כאן \u0003דלא טביל\u0004 \u0005[ש\u0006עדיין \u0005לא טבל]\u0006 \u0003ראה שלש\u0004 ועומד \u0003בשמיני למה לי\u0004 לומר?","הלוא אפשר ללמוד זאת בקל וחומר \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003יש לומר\u0004 שזב ש\u0003ראה שתי ראיות\u0004 ועומד \u0003בשביעי דלא טביל\u0004 \u0005[שלא טבל]\u0006 \u0003דטמא מעליא הוא\u0004 \u0005[שטמא גמור הוא]\u0006 ובכל זאת \u0003שחטינן וזרקינן עילויה\u0004 \u0005[שוחטין וזורקין אנו עליו],\u0006 \u0003ראה שלש\u0004 ראיות ועומד \u0003בשמיני דטביל\u0004\u0005,\u0006 \u0003ליה בשביעי\u0004 \u0005[ש\u0006כבר \u0005טבל בשביעי]\u0006 \u0003דקלישא\u0004 \u0005[שקלושה]\u0006 \u0003טומאה\u0004 שבו שהרי אין הוא טמא אפילו בטומאת טבול יום אלא שאסור לו עוד לבוא למקדש משום שהוא מחוסר כיפורים \u0003לא כל שכן דשחטינן וזרקינן עילויה\u0004 \u0005[שאנו שוחטים וזורקים עליו].\u0006","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 \u0003ראה שתי ראיות\u0004 ועומד \u0003בשביעי דשחטינן עילויה\u0004 \u0005[שאנו שוחטים עבורו]\u0006 מדובר בזב \u0003דטביל\u0004 \u0005[שטבל].\u0006","ודוחים: \u0003לא, לעולם אימא לך דלא טביל\u0004 \u0005[\u0006יכול \u0005אני לומר לך\u0006 שמדובר \u0005בשלא טבל]\u0006 ובכל זאת \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 ללמדנו גם לענין זב שראה שלוש ראיות. כי \u0003סלקא דעתך אמינא\u0004 \u0005[עולה על דעתך לומר]\u0006 \u0003בשביעי הוא\u0004 שמותר משום ש\u0003בידו לתקן\u0004 בעצמו, שיכול ללכת למקוה ולטבול,","\u0003אבל בשמיני\u0004 ש\u0003אין בידו להקריב קרבן\u0004 והוא תלוי באחרים, \u0003אימא פשעי ביה כהנים\u0004 \u0005[שמא יתרשלו בו הכהנים]\u0006 וכל עוד לא הקריבו יהא פסול, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם כאן אין לחשוש \u0003כדרב שמעיה\u0004 שאפשר לסמוך על בית דין של כהנים.","שנינו במשנה: \u0003והזבה שוחטין\u0004 עליה בשמיני לזיבתה. \u0003תני תנא קמיה\u0004 \u0005[שנה\u0006 חוזר המשניות \u0005לפני]\u0006 \u0003רב אדא בר אהבה: \"והזבה שוחטין עליה בשביעי שלה\". אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זבה בשביעי שלה מי חזיא\u0004 \u0005[האם\u0006 היא \u0005ראויה]?\u0006 \u0003אפילו ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר שוחטין וזורקין על טמא שרץ — הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים ב\u0003טמא שרץ\u0004 בלבד, \u0003דחזי לאורתא\u0004 \u0005[שראוי\u0006 לאכול \u0005בערב]\u0006 ואילו \u0003הא\u0004 \u0005[זו,\u0006 הזבה\u0005]\u0006 \u0003עד למחר דמתיא\u0004 \u0005[כש\u0006היא \u0005מביאה]\u0006 \u0003כפרה לא חזיא\u0004 \u0005[ראויה]!\u0006 אלא \u0003אימא\u0004 \u0005[אמור]\u0006 בגירסת ברייתא שבידך \u0003\"בשמיני\".\u0004","ומקשים: אם כן, \u0003פשיטא\u0004 \u0005[פשוט\u0006 מובן מאליו\u0005]!\u0006 ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כיון דמחסרא כפרה\u0004 \u0005[שמחוסרת כפרה]\u0006 עדיין, הריהי כמחוסרת מעשה ולא תהא ראויה, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003כדרב שמעיה,\u0004 שיש לסמוך בזה על בית דין של כהנים.","\u0003רבינא אמר: \"נדה\" תנא קמיה\u0004 \u0005[שנה לפניו]\u0006 חוזר המשניות: \"\u0003והנדה שוחטין עליה בשביעי\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נדה בשביעי מי חזיא\u0004 \u0005[האם היא ראויה]?\u0006 שהרי \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 \u0003שוחטין וזורקין על טמא שרץ\u0004 הרי זה משום \u0003דחזי לאורתא\u0004 \u0005[שהוא ראוי לערב],\u0006 ואילו \u0003נדה לאורתא דשביעי הוא דטבלה\u0004 \u0005[לערב שביעי הוא שטובלת]\u0006 שאין טבילת נדה אלא בלילה ולא ביום ואם כן, \u0003עד שמיני דעבדה\u0004 \u0005[שהיא עושה]\u0006 \u0003הערב שמש לא חזיא\u0004 \u0005[אינה ראויה]\u0006 שהריהי עדיין טבולת יום ואסורה בקדשים עד למחרת! \u0003אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 נדה \u0003\"בשמיני\".\u0004","ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 \u0003השתא ומה זבה דמיחסרא כפרה\u0004 \u0005[עכשיו ומה זבה שמחוסרת\u0006 קרבן \u0005כפרה]\u0006 \u0003שוחטין וזורקין עליה בשמיני, נדה דלא מיחסרא כפרה\u0004 \u0005[שאינה מחוסרת כפרה]\u0006 \u0003צריכה למימר\u0004 \u0005[לומר]\u0006 \u0003דשחטינן וזרקינן עלה\u0004 \u0005[שאנו שוחטים וזורקים עליה]?!\u0006","ומשיבים: \u0003נדה איצטריכא ליה\u0004 \u0005[הוצרכה לו],\u0006 \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 חידוש: \u0003בשמיני — אין\u0004 \u0005[כן]\u0006 \u0003בשביעי — לא, כדתניא\u0004 \u0005[כפי ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כל חייבי טבילות\u0004 שבתורה \u0003טבילתן\u0004 בשעות ה\u0003יום,\u0004 אבל \u0003נדה ויולדת טבילתן בלילה.\u0004","ומקור לדבר בברייתא אחרת: \u0003יכול תהא\u0004 הנדה או היולדת \u0003טובלת מבעוד יום\u0004 כשאר חייבי טבילה? \u0003תלמוד לומר: \"\u0004ואשה כי תהיה זבה דם יהיה זובה בבשרה \u0003שבעת ימים תהיה בנדתה\"\u0004 (ויקרא טו, יט). נאמר פעמיים המילה \"תהיה\" ללמד: \u0003תהא בנדתה כל שבעה\u0004 ימים שלמים עד שיגמר כל היום השביעי, ולכן יכולה לטבול רק אור לשמיני. ואילו \u0003יולדת איתקש\u0004 \u0005[הושוותה\u0006 בכתוב\u0005]\u0006 \u0003לנדה:\u0004 \"אשה כי תזריע וילדה...כימי נידת דוותה תטמא\".","\u0003האונן\u0004 (האבל על מת שעדיין לא נקבר)"],["\u0003והמפקח את הגל\u0004 (המפנה גל אבנים מעל אדם שנפלה עליו מפולת), ויתכן שמת כבר אותו אדם והוא מטמא את מפנה הגל. \u0003וכן מי שהבטיחוהו להוציאו מבית האסורים\u0004 בליל הפסח, \u0003והחולה והזקן שהן יכולין לאכול כזית\u0004 — כל אלה \u0003שוחטין עליהן\u0004 בתוך חבורה אחת.","אולם \u0003על כולם אין שוחטין עליהן בפני עצמן\u0004 שאין עושים חבורה שכולה אנשים בעלי ספקות כאלה, \u0003שמא יביאו את הפסח לידי פסול.\u0004","ועוד מוסיפים בדיניהם: \u0003לפיכך\u0004 כיון שהם נמנים לכתחילה על הפסח גם \u0003אם אירע בהן פסול\u0004 ולא יכלו לאכול מן הפסח — \u0003פטורין מלעשות פסח שני, חוץ מן המפקח בגל\u0004 ונמצא האיש הקבור במפולת מת \u0003שהוא טמא מתחלתו\u0004 שהרי ודאי שהאהיל על המת ונתברר אם כן שהיה טמא משעה שהתחיל לפקח בגל שאף בשעת שחיטה היה טמא, ולא עלה לו קרבנו כלל.","\u0003אמר רבה בר הונא אמר ר' יוחנן: לא שנו\u0004 שאין שוחטים את הפסח על האסור בבית האסורים אלא בתוך חבורה אחרת \u0003אלא\u0004 דווקא בנמצא ב\u0003בית האסורין\u0004 של \u0003גוים, אבל\u0004 המצוי ב\u0003בית האסורין דישראל — שוחטין\u0004 עליו אפילו \u0003בפני עצמו, כיון דאבטחינהו, מפיק ליה\u0004 \u0005[שהבטיחוהו\u0006 שיצא, ודאי \u0005יוציאו אותו]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שארית ישראל לא יעשו עולה ולא ידברו כזב\"\u0004 (צפניה ג, יג) ואפשר לסמוך עליהם.","\u0003אמר רב חסדא: הא דאמרת\u0004 \u0005[זה שאומר אתה]\u0006 כי היושב ב\u0003בית האסורין\u0004 של \u0003גוים\u0004 אין שוחטים עליו בפני עצמו \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 שהיה בית האסורין \u0003חוץ לחומת בית פאגי\u0004 (מחוץ למקום היתר אכילת פסחים) \u0003אבל\u0004 היה בית האסורים \u0003לפנים מחומת בית פאגי שוחטין עליו\u0004 אפילו \u0003בפני עצמו. מאי טעמא\u0004 \u0005[מה טעם] —\u0006 גם אם לא יוציאוהו משם \u0003אפשר דאמטו לה ואכיל ליה\u0004 \u0005[אפשר שיביאו לו\u0006 מן הקרבן לתוך בית האסורים \u0005ויאכל ממנו].\u0006","שנינו במשנה: \u0003לפיכך אם אירע\u0004 פסול במסופקים אלו לאחר שנשחט עליהם הפסח הריהם פטורים מפסח שני, חוץ מהמפקח על הגל. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: לא שנו\u0004 שהמפקח את הגל חייב לעשות פסח שני \u0003אלא\u0004 כשמצאו ב\u0003גל עגול,\u0004 שתוך כדי פינויו ודאי האהיל על המת ונטמא \u0003אבל\u0004 אם היה זה \u0003גל ארוך\u0004 מתוך שיתכן שהיה המת מצוי בצד אחר של הגל והמפקח בגל לא האהיל עליו — \u0003פטור מלעשות פסח שני, אימא\u0004 \u0005[אמור]:\u0006 שמא \u0003טהור היה בשעת שחיטה\u0004 ואם נטמא היה זה רק לאחר מכן ומאחר שהוא ספק שוב אינו מביא פסח שני.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003ר' שמעון בנו של ר' יוחנן בן ברוקה אומר: מפקח בגל\u0004 ל\u0003עתים פטור\u0004 מלעשות פסח שני ל\u0003עתים חייב. כיצד?\u0004 היה זה \u0003גל עגול ונמצאת טומאה תחתיו — חייב\u0004 בפסח שני שודאי האהיל עליו קודם לכן, אבל אם היה זה \u0003גל ארוך ונמצאת טומאה תחתיו — פטור, אימא\u0004 \u0005[אמור]\u0006 שמא \u0003טהור היה בשעת שחיטה.\u0004","\u0003אין שוחטין את הפסח על היחיד\u0004 עבור אדם אחד בלבד. אלא בחבורה. אלו \u0003דברי ר' יהודה, ור' יוסי מתיר,\u0004 שהדבר תלוי רק ביכולת האכילה, ולכן \u0003אפילו חבורה של מאה שאינן יכולין לאכול כזית אין שוחטין עליהן.\u0004","ועוד הלכה: \u0003ואין עושין חבורת\u0004 פסח של \u0003נשים ועבדים וקטנים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאין שוחטין את הפסח על היחיד — תלמוד לומר: \"לא תוכל לזבח את הפסח באחד\u0004 שעריך אשר ה' אלהיך נותן לך\u0003\"\u0004 (דברים טז, ה) והוא דורש שבאדם יחיד אין לזבוח את הפסח, אלו \u0003דברי ר' יהודה. ור' יוסי אומר:\u0004 אפילו אדם \u0003יחיד ויכול לאכלו\u0004 כלומר, כזית ממנו \u0003— שוחטין עליו\u0004 ואילו \u0003עשרה ואין יכולין לאכלו — אין שוחטין עליהן.\u0004","ושואלים: \u0003ור' יוסי האי \"באחד\" מאי עביד ליה\u0004 \u0005[אותו\u0006 פסוק שאומר \u0005\"באחד\"\u0006 שעריך \u0005מה עושה הוא בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך הוא אותו]\u0006 לכמו שדרשו \u0003ר' שמעון. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' שמעון אומר: מניין לזובח את פסחו בבמת יחיד\u0004 מזבח שהיו מקריבים בו יחידים קרבנות נדבתם בדורות מסוימים \u0003בשעת איסור הבמות שהוא\u0004 עובר \u0003בלא תעשה —\u0004","\u0003תלמוד לומר: \"לא תוכל לזבח את הפסח באחד שעריך\"\u0004 משמע שבכל מקום שיש איסור במות דין הפסח כקרבן ציבור ולא כקרבן יחיד ואינו קרב בבמה. \u0003יכול אף בשעת היתר הבמות כן\u0004 יהא דינו כקרבן ציבור שיעבור בו על לא תעשה, \u0003תלמוד לומר: \"באחד שעריך\" לא אמרו\u0004 איסור זה \u0003אלא בשעה שכל ישראל נכנסין בשער אחד\u0004 לבית הבחירה להביא קרבנותיהם. אבל בזמן שאין מקום מיוחד שכל ישראל חייבים להיות בו אפשר לשחוט גם את הפסח כקרבן יחיד.","ושואלים: \u0003ור' יהודה האי מנא ליה\u0004 \u0005[\u0006דרשה \u0005זו\u0006 לגבי במת יחיד \u0005מנין לו]?\u0006 ומשיבים: \u0003תרתי שמעת מינה\u0004 \u0005[שני\u0006 דברים \u0005אתה שומע מכאן]\u0006 שמלשון הכתוב אפשר ללמוד את שני הדברים.","ושואלים: \u0003ול\u0004שיטת \u0003ר' יוסי, ממאי דלהכי דקאמר\u0004 \u0005[מנין\u0006 לו שהפסוק מתפרש \u0005לכמו שאמר]\u0006 \u0003ר' שמעון? דילמא כדקאמר\u0004 \u0005[שמא\u0006 לענין מה \u0005שאמר]\u0006 \u0003ר' יהודה הוא דאתא\u0004 \u0005[שבא]?\u0006 ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה ר' יוסי \u0005לומר לך],\u0006 \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כן \u0003דהא כתיב\u0004 \u0005[שהרי נאמר]\u0006 בדיני הפסח: \u0003\"איש לפי אכלו\u0004 תכוסו על השה\u0003\"\u0004 (שמות יב, ד), משמע שאפילו יחיד יכול לאכול את הפסח.","\u0003רמי ליה\u0004 \u0005[הקשה לו,\u0006 הראה סתירה\u0005]\u0006 \u0003רב עוקבא בר חיננא\u0004 מהמקום \u0003פרישנא לרבא: מי\u0004 \u0005[האם]\u0006 \u0003אמר ר' יהודה\u0004 באמת \u0003אין שוחטין את הפסח על היחיד? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ששנינו: \u0003אשה\u0004 בפסח \u0003ראשון — שוחטין עליה בפני עצמה,\u0004 בפסח \u0003שני עושין אותה טפילה לאחרים\u0004 אבל אין שוחטין עבורה בלבד, אלו \u0003דברי ר' יהודה.\u0004 הרי שר' יהודה מתיר לעשות פסח עבור יחיד! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003לא תימא\u0004 \u0005[תאמר\u0006 אל תבין\u0005]\u0006 שכוונתו ששוחט עבור אשה \u0003בפני עצמה, אלא אימא\u0004 \u0005[אמור]:\u0006 לנשים שוחטין \u0003בפני עצמן.\u0004","\u0003אמר\u0004 לו והקשה על פירוש זה: \u0003מי עבדינן\u0004 \u0005[האם עושים אנו]\u0006 לדעת הכל \u0003חבורה שכולה נשים? והתנן\u0004 \u0005[והרי\u0006 במשנתנו \u0005שנינו]:\u0006 \u0003אין עושין חבורת נשים ועבדים וקטנים, מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003נשים לחודייהו\u0004 \u0005[לעצמן],\u0006 \u0003ועבדים לחודייהו\u0004 \u0005[לעצמם],\u0006 \u0003וקטנים לחודייהו\u0004 \u0005[לעצמם]\u0006 שאין עושים חבורה שלימה מאלה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 הכוונה היא שאין עושים חבורות מצורפות של \u0003נשים ועבדים וקטנים.\u0004 והטעם הוא: \u0003נשים ועבדים\u0004 יחד לא יעשו \u0003משום תפלות\u0004 כלומר משום חשש זנות, \u0003קטנים ועבדים\u0004 לא יעשו \u0003משום\u0004"],["\u0003פריצותא\u0004 \u0005[פריצות]\u0006 מחשש משכב זכור.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של הבעיה בענין חבורת נשים. שנינו: \u0003אשה\u0004 בפסח \u0003ראשון — שוחטין עליה בפני עצמה ובשני — עושין אותה טפילה\u0004 (נוספת, נספחת) \u0003לאחרים,\u0004 אלו \u0003דברי ר' יהודה. ר' יוסי אומר: אשה\u0004 בפסח \u0003שני שוחטין עליה בפני עצמה, ואין צריך לומר\u0004 ששוחטים לה בפני עצמה אף בפסח \u0003ראשון. ר' שמעון אומר: אשה\u0004 אפילו \u0003בראשון עושין אותה טפילה לאחרים, בשני אין שוחטין עליה כל עיקר.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומסבירים: \u0003ר' יהודה סבר\u0004 נאמר: \u0003\"במכסת נפשת...\u0004 תכוסו על השה\u0003\"\u0004 (שמות יב, ד), ודורש: \"נפשות\" הרי הכל בכלל זה \u0003ואפילו נשים. וכי תימא אי הכי אפילו בשני נמי\u0004 \u0005[ואם תאמר אם כך אפילו\u0006 פסח \u0005שני גם כן]\u0006 יעשו עבור נשים לבדן, לכן \u0003כתיב\u0004 \u0005[נאמר]\u0006 במי שהקריב גם את הפסח השני \u0003\"חטאו ישא האיש ההוא\"\u0004 (במדבר ט, יג) ללמדנו: \u0003איש — אין\u0004 \u0005[כן]\u0006 \u0003אשה — לא,\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אפילו\u0004 כ\u0003טפילה נמי\u0004 \u0005[גם כן]\u0006 \u0003בשני לא\u0004 תביא אשה, ומשיבים: לכך \u0003אהני\u0004 \u0005[הועיל]\u0006 מה שכתוב בפסח שני: \u0003\"ככל חקת הפסח\u0004 יעשו אותו\u0003\"\u0004 (במדבר ט, יב) שמשווה פסח שני לראשון \u0003לטפילה בעלמא\u0004 \u0005[בלבד],\u0006 של הנשים בו.","ושואלים: \u0003ור' יוסי מאי טעמיה\u0004 \u0005[מה טעמו]?\u0006 משום \u0003דכתיב\u0004 \u0005נאמר\u0006 בפסח \u0003ראשון: \"במכסת נפשת\"\u0004 והרי \u0003אפילו אשה\u0004 בכלל זה \u0003וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]\u0006 \u0003בפסח שני: \"\u0004וחדל לעשות הפסח \u0003ונכרתה הנפש ההיא מעמיה\"\u0004 (במדבר ט, יג) ומכאן נלמד: \u0003נפש — ואפילו נשים. ואלא\u0004 מה שנאמר בסוף הפסוק: \u0003\"חטאו ישא האיש ההוא\"\u0004 שיש בו לשון הדגשה ומיעוט, \u0003למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 ילד \u0003קטן\u0004 הבטל מקרבן פסח מחיוב \u0003כרת,\u0004 והדיוק הוא מן הכתוב \"איש\" — ולא קטן.","\u0003ור' שמעון\u0004 מה טעמו — \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפסח \u0003ראשון: \"איש\u0004 לפי אכלו תכוסו על השה \u0003\"\u0004ללמדנו: \u0003איש — אין\u0004 \u0005[כן]\u0006 \u0003אשה — לא. וכי תימא אי הכי אפילו טפילה נמי\u0004 \u0005[ואם תאמר אם כן אפילו כטפילה גם כן]\u0006 אין לצרף אשה, אלא ודאי \u0003אהני ליה\u0004 \u0005[הועיל לו]\u0006 הכתוב \u0003\"במכסת נפשת\"\u0004 שאינו מיוחד לאנשים, \u0003לטפילה.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 לטעם זה \u0003אפילו בשני נמי\u0004 \u0005[גם כן]\u0006 אפשר יהא לצרף אשה כטפילה לחבורת עושי הפסח אלא \u0003מיעט רחמנא\u0004 \u0005[מיעטה התורה]\u0006 נשים \u0003בשני דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"חטאו ישא האיש\"\u0004 לדייק: \u0003איש — אין\u0004 \u0005[כן]\u0006 \u0003אשה — לא.\u0004 ושואלים: אותה הדגשה \"איש\" \u0003ממאי קממעיט ליה.\u0004 \u0005[ממה ממעט אותו\u0006 כתוב\u0005]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 תאמר \u0003מחיוב\u0004 גמור לעשות פסח שני, \u0003השתא בראשון לא\u0004 \u0005[עכשיו,\u0006 הרי אומרים אנו שאפילו \u0005בראשון אין\u0006 האשה חייבת\u0005]\u0006 \u0003בשני מיבעיא\u0004 \u0005[נצרכה לומר]?\u0006 והרי אין השני אלא השלמה לראשון! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה לפטור את האשה אפילו \u0003מטפילה.\u0004","ושואלים: \u0003ומאי\u0004 \u0005[ומה הוא]\u0006 אותו כתוב שנאמר בו \u0003\"איש\"\u0004 בפסח ראשון \u0003דקאמר\u0004 \u0005[שאמר]\u0006 וציטט \u0003ר' שמעון? אי נימא\u0004 \u0005[אם תאמר]\u0006 שהתכוון לכתוב: \u0003\"ויקחו להם איש שה לבית אבת\u0004 שה לבית\u0003\"\u0004 (שמות יב, ג) אולם \u0003ההוא\u0004 \u0005[אותו]\u0006 כתוב \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 ללימוד אחר, וכמו שדרשו \u0003ר' יצחק,\u0004 ש\u0003אמר\u0004 מכאן למדים: ש\u0003איש\u0004 גדול \u0003זוכה\u0004 בקנינו או בקבלתו חפץ לאחר, אבל \u0003אין קטן זוכה,\u0004 שאין לקטן אישיות משפטית כדי לזכות בקנין.","\u0003ואלא\u0004 תאמר שמן הכתוב \u0003\"איש לפי אכלו\u0004 תכוסו על השה\" (שמות יב, ד), אולם \u0003הא\u0004 \u0005[הרי]\u0006 כיון ש\u0003ר' יוסי סבר\u0004 בדין במת יחיד \u0003כר' שמעון\u0004 שאין מקריבין בה את הפסח, מן הסתם \u0003ר' שמעון נמי\u0004 \u0005[גם כן]\u0006 \u0003סבר לה כר' יוסי\u0004 ששוחטים פסח על יחיד ואם כן \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 \"איש לפי אכלו תכוסו על השה\" \u0003מיבעי ליה\u0004 \u0005[נצרכה לו]\u0006 ללמדנו ש\u0003שוחטין את הפסח על היחיד\u0004 ולא ללימוד אחר שהרי זהו מקור דינו של ר' יוסי.","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 ר' שמעון \u0003אם כן\u0004 שרק לדבר זה היה הכתוב בא \u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003\"לפי אכלו\"\u0004 שהיא לשון יחיד ונבין ששוחטים אף על היחיד, \u0003מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"איש\"\u0004 האמורה כאן \u0003שמעת מינה תרתי\u0004 \u0005[לומד אתה\u0006 \u0003מכאן\u0004 \u0005שני\u0006 דברים\u0005],\u0006 הן ההיתר ליחיד לשחוט עליו את הפסח, והן שיהיה זה איש ולא אשה.","ושואלים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר ר' אלעזר: אשה\u0004 בפסח \u0003ראשון — חובה,\u0004 בפסח \u0003שני — רשות, ודוחה את השבת.\u0004 עוד טרם בירור השאלה תוהים: \u0003אי\u0004 \u0005[אם]\u0006 הקרבת פסח שני לנשים \u0003רשות\u0004 הינה \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003דוחה את השבת? אלא אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 את המשפט וגרוס כך: בפסח \u0003שני רשות ובראשון חובה ודוחה את השבת. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 כשיטת \u0003ר' יהודה\u0004 שראינו שזו דעתו.","אגב דברים קודמים מביאים מה ש\u0003אמר ר' יעקב אמר ר' יוחנן: אין עושין\u0004 בפסח \u0003חבורה שכולה גרים שמא ידקדקו בו ויביאוהו לידי פסול\u0004 שכיון שהגרים נלהבים ומדקדקים הרבה בדברי תורה, שמא יוסיפו בו דקדוקי מצוות יתירים, ויביאו לידי פסול שלא כדין.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 קרבן \u0003פסח ומצה ומרור\u0004 בלילה ה\u0003ראשון\u0004 של פסח \u0003חובה\u0004 לאוכלם, \u0003מכאן ואילך רשות, ר' שמעון אומר: באנשים חובה ובנשים רשות.\u0004","ותחילה נברר: \u0003אהייא קאי\u0004 \u0005[על איזה\u0006 דבר \u0005מתייחסת\u0006 הלכה זו\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר כאן בקרבן \u0003פסח,\u0004 וכי \u0003פסח כל שבעה מי איכא\u0004 \u0005[האם ישנו]?\u0006 והרי ודאי שלאחר לילה ראשון אין מקום לדבר בו לא על חובה ולא על רשות! \u0003ואלא\u0004 תאמר שמדובר כאן על \u0003מצה ומרור, אימא סיפא\u0004 \u0005[אמור את סופה\u0006 של אותה ברייתא\u0005]:\u0006 \u0003ר' שמעון אומר: באנשים חובה ובנשים רשות,\u0004","וכי \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 \u0003ר' שמעון הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' אלעזר: נשים חייבות באכילת מצה דבר תורה!\u0004 ולא רק מתקנת חכמים, אף שהיא מצוות עשה שהזמן גרמא, \u0003שנאמר: \"לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות\"\u0004 (דברים טז, ג), ללמדנו: \u0003כל\u0004 מי \u0003שישנו\u0004 (שחל עליו) איסור של \u0003בל תאכל חמץ — ישנו\u0004 גם במצות עשה של \u0003קום אכול מצה. והני\u0004 \u0005[ואותן]\u0006 \u0003נשים הואיל וישנן ב\"בל תאכל חמץ\"\u0004 שהרי הנשים חייבות להשמר בכל איסורים של התורה כגברים — \u0003ישנן גם בקום אכול מצה\u0004 ואם כן אי אפשר לומר כן.","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003פסח מצה ומרור\u0004 ביום ה\u0003ראשון\u0004 של פסח \u0003חובה, מכאן ואילך רשות\u0004 לאכול את המצה והמרור. \u0003ר' שמעון אומר: פסח\u0004 מעיקרו \u0003באנשים חובה\u0004 ו\u0003בנשים רשות\u0004 כשיטתו שכבר נתבררה קודם.","\u0003אונן\u0004 מי שמת לו קרוב ועדיין לא נקבר, ואסור באכילת קדשים בו ביום — \u0003טובל\u0004 על פי תקנת חכמים שעשו הבדל בין אונן ואדם אחר, \u0003ואוכל את פסחו לערב, אבל לא בקדשים\u0004 אחרים. שגזרו חכמים שתקופת האנינות (שבה אסור לאדם להתעסק ולאכול מן הקדשים) חלה גם על הלילה שלאחר יום האבל, ולענין קרבן פסח לא עמדו על גזרתם משום שהקפידה התורה במצוה זו ויש חיוב כרת על מי שאינו מקריב פסח. ועוד לענין זה: \u0003השומע על מתו\u0004 לאחר זמן, וחלה עליו אנינות רק מדברי חכמים,"],["\u0003והמלקט לו\u0004 את \u0003עצמות\u0004 הוריו שתחילה קברום באדמה עד שיכלה הבשר, כדי להביאם לקבורת קבע שחייב באבילות כל אותו יום — \u0003טובל ואוכל\u0004 אפילו \u0003בקדשים\u0004 כי האבלות ביום לקוט עצמות היא רק מדברי סופרים והם לא גזרו על אנינות בלילה שאחרי זה.","\u0003גר שנתגייר בערב פסח, בית שמאי אומרים: טובל ואוכל את פסחו לערב, ובית הלל אומרים: הפורש מן הערלה\u0004 ונימול \u0003כפורש מן הקבר\u0004 כאילו נטמא במת וצריך שיזו עליו מי חטאת ביום השלישי וביום השביעי, ואינו ראוי לאכול מן הקרבנות עד ליום השמיני לגירותו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 התירו למי שמת לו מת לאכול פסחו לערב? ומשיבים: \u0003קא סבר\u0004 \u0005[סבור הוא]\u0006 \u0003אנינות\u0004 של \u0003לילה\u0004 שלאחר יום המיתה היא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד, \u0003וגבי פסח לא העמידו\u0004 הם \u0003דבריהם\u0004 שיהא אסור משום אנינות \u0003במקום כרת\u0004 שהרי הנמנע מן הפסח חייב כרת, ואילו \u0003גבי\u0004 שאר \u0003קדשים העמידו\u0004 חכמים \u0003דבריהם במקום\u0004 שיש בו רק מצות \u0003עשה\u0004 של אכילת קדשים.","במשנה נאמר ש\u0003השומע\u0004 שמועה רחוקה \u0003על מתו\u0004 והמלקט עצמות טובל ואוכל בקדשים. ותוהים: \u0003מלקט עצמות? הא בעי\u0004 \u0005[הרי צריך]\u0006 \u0003הזאת שלישי ושביעי\u0004 ככל הנוגע בעצמות המת! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 לא מלקט בעצמו אלא מי \u0003שליקטו לו עצמות\u0004 והוא לא נגע בהן, ולכן יש כאן אכן דין אבלות מסוימת מדברי סופרים אבל טומאה אין כאן.","במשנה שנינו ש\u0003גר שנתגייר\u0004 בערב פסח נחלקו בית שמאי ובית הלל אם טובל ואוכל את הפסח לערב. \u0003אמר רבה בר בר חנה אמר ר' יוחנן: מחלוקת\u0004 בית שמאי ובית הלל היא \u0003בערל גוי\u0004 שנימול לשם גירות","ש\u0003בית הלל סברי\u0004 \u0005[סוברים]:\u0006 \u0003גזירה שמא יטמא\u0004 במת \u0003לשנה הבאה, ויאמר: אישתקד\u0004 \u0005[בשנה שעברה],\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא טבלתי ואכלתי\u0004 מיד בלא הזייה? \u0003עכשיו נמי\u0004 \u0005[גם כן]\u0006 \u0003אטבול ואוכל. ולא ידע\u0004 שיש הבדל יסודי במצבו, ש\u0003אשתקד\u0004 (שנה שעברה) \u0003גוי הוה\u0004 \u0005[היה]\u0006 \u0003ולא מקבל טומאה\u0004 שמדברי תורה אין טומאה בגוים ו\u0003עכשיו\u0004 הוא \u0003ישראל ומקבל טומאה,\u0004 ולכן גזרו שיזה שלישי ושביעי וימתין כדי להרגילו.","\u0003ובית שמאי סברי\u0004 \u0005[סבורים]\u0006 \u0003לא גזרינן\u0004 \u0005[גוזרים אנו]\u0006 מפני חשש זה. \u0003אבל ערל ישראל\u0004 שלא נימול עד עתה מסיבה כלשהי ועתה כשנימול — \u0003דברי הכל טובל ואוכל את פסחו לערב,\u0004 שהרי יודע להבדיל בין אשתקד להשנה \u0003ולא גזרינן\u0004 \u0005[גוזרים אנו]\u0006 דין \u0003ערל ישראל משום ערל גוי.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003אמר ר' שמעון בן אלעזר: לא נחלקו בית שמאי ובית הלל על ערל ישראל ששטובל ואוכל את פסחו לערב,\u0004 אלא \u0003על מה נחלקו על ערל גוי\u0004 שנתגייר \u0003שבית שמאי אומרים: טובל ואוכל את פסחו לערב, ובית הלל אומרים: הפורש מן הערלה כפורש מן הקבר.\u0004","\u0003אמר רבא:\u0004 בדין \u0003ערל\u0004 שנתגייר בדין \u0003הזאה\u0004 ובדין \u0003איזמל העמידו\u0004 חכמים \u0003דבריהן,\u0004 ולא ויתרו על גזירותיהם אפילו \u0003במקום\u0004 שיש בו חיוב \u0003כרת.\u0004 אולם בדין \u0003אונן ומצורע ובית הפרס — לא העמידו דבריהן במקום\u0004 שיש בו חיוב \u0003כרת.\u0004","ומבארים את הפרטים: \u0003ערל — הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 בדברים הקודמים שמשום גזירה ביטלו בית הלל את הגר מלהקריב קרבן פסח, אף שמן התורה הריהו מצווה על כך וחייב כרת על ביטולו.","\u0003הזאה —\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 במשנה: \u0003הזאה\u0004 עצמה אסורה בשבת רק משום \u0003שבות\u0004 שגזרו חכמים ובכל זאת \u0003אינו דוחה את השבת\u0004 ואם חל ערב פסח בשבת, הרי מי שצריך להזות עליו בשבת — אינו נטהר ובטל מקרבן פסח.","\u0003איזמל — דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 אם שכחו ולא הביאו אזמל למול בו בשבת \u0003כשם שאין מביאין אותו\u0004 את האזמל \u0003דרך רשות הרבים\u0004 ואין עוברים בכך על דברי תורה \u0003כך אין מביאין אותו דרך גגות ודרך חצרות ודרך קרפיפות\u0004 (בקעות מגודרות) אף כי הדבר אסור רק מתקנת חכמים, ואם כך עמדו חכמים על דבריהם ובשל תקנתם נדחית מצוות המילה, הרי מי שיש לו בן שלא נימול הוא עצמו אסור באכילת פסחו אף שעל ביטולו הריהו מתחייב כרת.","\u0003אונן\u0004 שחכמים לא העמידו דבריהם בו \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 במשנתנו.","\u0003מצורע מאי היא\u0004 \u0005[מה הוא]\u0006 ענינו? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מצורע ש\u0004טבל ביום שביעי לטהרתו ו\u0003חל\u0004 יום \u0003שמיני שלו בערב הפסח,\u0004 וראוי היה באותו יום להביא קרבן כפרה ואז יאכל מן הפסח, \u0003וראה קרי בו ביום,\u0004 ובעל קרי טמא הוא ואסור להכנס למקדש — \u0003טובל\u0004 לקריו ומביא את קרבנותיו להתכפר \u0003ואוכל\u0004 בפסח בלילה.","\u0003אמרו חכמים: אף על פי שטבול יום\u0004 אחר \u0003אינו נכנס\u0004 לבית המקדש שעדיין יש בו טומאה מסויימת, \u0003זה — נכנס.\u0004 והטעם: \u0003מוטב יבא עשה\u0004 של קרבן פסח \u0003שיש בו כרת, וידחה עשה שאין בו כרת\u0004 של \"וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש\" שבשלו משלחים את טבול היום מן העזרה.","\u0003ואמר ר' יוחנן:\u0004 יתר על כן, \u0003דבר תורה אפילו\u0004 מצוות \u0003עשה\u0004 מן התורה \u0003אין בו\u0004 שתאסור טבול יום להכנס למקדש, \u0003שנאמר: \"ויעמד יהושפט בקהל יהודה וירושלים בבית ה' לפני החצר החדשה\"\u0004 (דברי הימים ב' כ, ה) \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003חצר החדשה — שחדשו בו\u0004 באותו מקום \u0003דבר, ואמרו: טבול יום לא יכנס במחנה לויה\u0004 בירושלים — בכל תחום הר הבית. ואם כן איסור זה הוא רק מתקנת חכמים ולא העמידו חכמים דבריהם אלה.","\u0003בית הפרס\u0004 שלא העמידו חכמים דבריהם, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ושוין\u0004 בדעתם \u0003בית שמאי ובית הלל\u0004"],["\u0003שבודקין\u0004 את מקום בית הפרס לפני שעובר בו (אם אין לו דרך אחרת) כדי לעשות את הפסח לדעת אם נוגע או מאהיל על עצמות מתים, ואם לא נמצאו — הריהו טהור עבור \u0003עושי פסח,\u0004 אבל \u0003אין בודקין\u0004 לצורך \u0003אוכלי תרומה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003בודקין,\u0004 מה היא בדיקה זו שאמרנו שעושים לצורך \u0003עושי פסח? אמר רב יהודה אמר שמואל: מנפח\u0004 אדם \u0003בית הפרס\u0004 בפיו שהוא נופח באבק הדרך, כדי לדעת אם טמונה עצם כלשהי בתוך האבק. \u0003רב יהודה בר אביי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה אמר\u0004 בדומה לזה: \u0003בית הפרס\u0004 שעברו בו רבים וכבר \u0003נידש\u0004 ברגלים \u0003טהור,\u0004 שאנו מניחים שבדריסת הרגל הוסרו ונשברו העצמות שהיו בו, ומאחר שכל טומאת בית הפרס היא מדברי סופרים הרי לענין פסח לא גזרו לחשוש שמא עדיין נשאר דבר מה, מה שאין כן לתרומה.","","\u0003מי שהיה טמא או בדרך רחוקה ולא עשה את\u0004 הפסח \u0003הראשון\u0004 בארבעה עשר בניסן — \u0003יעשה את\u0004 הפסח \u0003השני\u0004 בארבעה עשר באייר. ובכלל \u0003שגג\u0004 וטעה בענין הפסח \u0003או נאנס\u0004 באונס כלשהו \u0003ולא עשה את\u0004 הפסח \u0003הראשון\u0004 — אף הוא \u0003יעשה את\u0004 הפסח \u0003השני. אם כן,\u0004 שכל מיני אונס בכלל זה \u0003למה נאמר\u0004 בתורה \u0003טמא, או שהיה בדרך רחוקה?\u0004 לומר \u0003שאלו\u0004 הטמא והרחוק \u0003פטורין מהכרת\u0004 אם לא עשו פסח שני \u0003ואלו חייבין בהכרת\u0004 וכאשר עוד יבואר בתלמוד.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: מי ש\u0003היה בדרך רחוקה ושחטו וזרקו עליו\u0004 (עבורו) את דם הפסח, והגיע לעת ערב לאכול את הפסח, אבל בשעת שחיטה היה רחוק, מה דינו? \u0003רב נחמן אמר: הורצה\u0004 בזריקה זו ואינו צריך לעשות פסח שני. \u0003רב ששת אמר: לא הורצה\u0004 ויעשה פסח שני. ומסבירים את שיטותיהם. \u0003רב נחמן אמר: הורצה,\u0004 כי מי שהיה טמא או בדרך רחוקה \u0003מיחס\u0004 \u0005[לחוס]\u0006 \u0003הוא\u0004 ש\u0003חס רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003עליו\u0004 שתהא לו תקנה אחרת ויעשה פסח שני. \u0003ואי עביד\u0004 \u0005[ואם עשה]\u0006 בכל זאת בפסח ראשון — \u0003תבא עליו ברכה. ורב ששת אמר: לא הורצה,\u0004 שאדם זה \u0003מידחא דחייה רחמנא\u0004 \u0005[דחה אותו הכתוב]\u0006 \u0003כטמא.\u0004 שכשם שהטמא אינו רשאי להקריב אם ירצה בכך, כן נדחה גם זה שהיה בדרך רחוקה. \u0003אמר רב נחמן: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את דעתי זו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שהיה טמא או בדרך רחוקה ולא עשה את הראשון — יעשה את השני.\u0004 ונדייק מהלשון \"ולא עשה\": \u0003מכלל דאי בעי\u0004 \u0005[מכאן שאם היה רוצה] —\u0006 \u0003עבד\u0004 \u0005[היה עושה]\u0006 ונפטר מן השני ולכן היה צורך לומר שלא עשה את הראשון. ומעירים: \u0003ורב ששת אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 בדחייה להוכחה זו: \u0003אי הכי\u0004 \u0005[אם כך\u0006 אתה מבין\u0005]\u0006 \u0003סיפא דקתני\u0004 \u0005[סופה\u0006 של המשנה \u0005ששנינו]:\u0006 \u0003שגג או נאנס ולא עשה את הראשון — יעשה את השני. מדקתני\u0004 \u0005[מתוך ששנה]\u0006 \u0003ולא עשה, מכלל\u0004 הדברים אתה לומד לשיטתך \u0003דאי בעי\u0004 \u0005[שאם היה רוצה] —\u0006 \u0003עבד\u0004 \u0005[היה עושה].\u0006 ואולם הסבר כזה אינו מתקבל על הדעת, ש\u0003הרי\u0004 נאמר במפורש \u0003שגג, והרי\u0004 נאמר גם \u0003נאנס,\u0004 ולא יכול לעשות!","","","\u0003אלא\u0004 חייב אתה להבין את המשנה בעל כורחך באופן אחר ואף שאין הדבר מפורש, שהרי ודאי גם \u0003מזיד\u0004 מי שהזיד ולא עשה \u0003קתני בהדייהו\u0004 \u0005[שנה יחד אתם]\u0006 עם המקרים האחרים. ויש להבין את הכתוב במשנה ולא עשה את הראשון, שנמנע מעשייתו במזיד, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 באותו אופן פירוש ההתחלה: \u0003אונן קתני בהדייהו\u0004 \u0005[שנה יחד אתם]\u0006 בתוך המשפט הראשון טמא או בדרך רחוקה או מי שלא עשה את הראשון מפני אונס אחר של אנינות.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 על פי הסבר זה, \u0003דקתני\u0004 \u0005[ששנינו]:\u0006 \u0003אלו פטורין מהכרת ואלו חייבין בהכרת,\u0004 ונברר: \u0003אהייא\u0004 \u0005[על איזה\u0006 מהם\u0005]\u0006 הכוונה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שנאמר חיוב כרת על ה\u0003שוגג ונאנס,\u0004 וכי \u0003שוגג ונאנס בני כרת נינהו\u0004 \u0005[הם]?!\u0006 והרי אין אדם חייב כרת אלא על מה שחטא בזדון ומדוע יתחייבו כרת! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 אותו ביטוי \"חייבין כרת\" מדובר ב\u0003מזיד ואונן\u0004 שאם לא יביאו פסח שני — יהיו חייבים כרת.","\u0003ורב נחמן אמר לך\u0004 כנגד נימוקים אלה: \u0003לעולם\u0004 יש לפרש שבמשנה נרמז בתוספת רק \u0003מזיד לחודיה\u0004 \u0005[לבדו]\u0006 ואין לדייק מלשון ריבוי \"חייבין\" \u0003ובדין הוא דאיבעי ליה למיתנא\u0004 \u0005[שהיה צריך לו לשנות]\u0006 \u0003\"חייב\"\u0004 בלשון יחיד, \u0003והאי דקתני\u0004 \u0005[וזה ששנינו]\u0006 \u0003\"חייבין\"\u0004 הוא מפני גדר הלשון \u0003איידי דתנא רישא\u0004 \u0005[על ידי,\u0006 מתוך \u0005ששנה בתחילה]\u0006 \u0003\"פטורין\"\u0004 בלשון רבים \u0003תנא סיפא\u0004 \u0005[שנה בסופה]\u0006 גם כן בלשון רבים \u0003\"חייבין\"\u0004 ואין להוכיח מכאן. עד כאן הוכחתו של רב נחמן ודחייתה על ידי רב ששת.","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את דעתי זו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' עקיבא אומר: נאמר \"טמא\" ונאמר \"בדרך רחוקה\"\u0004"],["\u0003מה טמא, שספק בידו לעשות\u0004 לולא שאסרה התורה עליו ולכן \u0003אינו עושה. אף\u0004 המצוי ב\u0003דרך רחוקה נמי\u0004 \u0005[גם כן]\u0006 מדובר \u0003שספק בידו לעשות\u0004 על ידי שליחים ולאכול בלילה \u0003ואינו עושה\u0004 שפטרתו התורה, וכשם שהטמא שנזרק עליו הדם — לא הורצה, אף מי שהיה בדרך רחוקה ונזרק עליו הדם בהיותו עדיין שם — לא הורצה!","\u0003ורב נחמן אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 ולדחות ראיה זו בנימוק הבא: \u0003ר' עקיבא לטעמיה\u0004 \u0005[לשיטתו]\u0006 \u0003דקסבר\u0004 \u0005[שסבור הוא]\u0006 \u0003אין שוחטין וזורקין על טמא שרץ\u0004 אף על פי שיכול לטבול ביום ויהא טהור גמור בשעת אכילת פסחים. משמע שלשיטתו כל שאינו ראוי בשעת זריקה אינו ראוי כלל. \u0003ואנא סבירא לי\u0004 \u0005[ואני סבור]\u0006 \u0003כ\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר שוחטין וזורקין על טמא שרץ\u0004 ולכן אין דברי ר' עקיבא נוגעים לשיטתו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003אלו שעושין את\u0004 הפסח \u0003השני: הזבין והזבות, המצורעין והמצורעות ונדות ובועלי נדות והיולדות, השוגגין\u0004 ושאר \u0003האנוסין והמזידין, וטמא\u0004 מת \u0003ושהיה בדרך רחוקה.\u0004","\u0003אם כן\u0004 שכל מי שלא עשה בראשון מכל טעם שהוא עושה בשני \u0003למה נאמר טמא?\u0004 ותוהים: \u0003למה נאמר?\u0004 הלא הוא צריך להכתב \u0003דאי בעי למיעבד בראשון לא שבקינן ליה\u0004 \u0005[שאם רוצה הוא לעשות\u0006 בפסח \u0005ראשון אין מניחים לו]!\u0006 \u0003אלא\u0004 כך צריך לתקן הלשון: \u0003אם כן למה נאמר בדרך רחוקה — לפוטרו מן הכרת\u0004 אם לא עשה אף בפסח שני. \u0003וכ\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר,\u0004 רב נחמן, שאם שלח את קרבנותיו בראשון \u0003הורצה\u0004 ולפיכך יש חילוק בין טמא ושהיה בדרך רחוקה, ויש טעם לומר את שניהם.","בברייתא זו הוזכרו כמה נשים טמאות שאינן עושות בראשון אלא בשני, ושואלים: \u0003אשה בשני מי מיחייבא\u0004 \u0005[האם חייבת]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול לא יהו עושין את\u0004 הפסח \u0003השני אלא טמא נפש\u0004 (טמא מת) ומי \u0003שהיה בדרך רחוקה\u0004 כמפורש במקומו בתורה, \u0003זבין ומצורעין ובועלי נדות\u0004 שהיו טמאים בראשון ונטהרו בשני \u0003מנין\u0004 שאף הם יעשו \u0003תלמוד לומר: \"איש איש\u0004 כי יהיה טמא לנפש או בדרך רחוקה... ועשה פסח לה'\u0003\"\u0004 (במדבר ט, י), נכפלה המילה \"איש\" לרבות גם אחרים, אבל בריבוי זה אין הנשים נכללות!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 הברייתא הראשונה הכוללת נשים — כשיטת \u0003ר' יוסי\u0004 שלדעתו שוחטים עבור נשים בפסח שני (לעיל פסחים צא, ב), \u0003הא\u0004 \u0005[זה]\u0006 הברייתא השניה שאינה מרבה אלא את הזכרים הטמאים — כשיטת \u0003ר' יהודה ור' שמעון\u0004 האומרים (במדבר ט, י) שבפסח שני אין חיוב גמור, או אין כל חיוב, לנשים להשתתף.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 מי שביטל עשיית פסח במזיד \u0003חייב כרת על\u0004 ביטול הפסח \u0003הראשון,\u0004 וכן אדם אחר המבטל את הפסח השני \u0003חייב כרת על\u0004 ביטול הפסח \u0003השני,\u0004 אלו \u0003דברי רבי. ר' נתן אומר: חייב כרת על הראשון, ופטור על השני\u0004 אם ביטל את הראשון בשוגג והזיד בשני, כיון שבו לא נאמר כרת. \u0003ר' חנניא בן עקביא אומר: אף על הראשון אינו חייב כרת\u0004 אף אם ביטלו במזיד \u0003אלא אם כן\u0004 הזיד ו\u0003לא עשה את השני.\u0004","ומסבירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והלכו\u0006 רבי ור' נתן \u0005לשיטותיהם]\u0006 שמחלוקת זו קשורה במחלוקת אחרת של חכמים אלה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003גר שנתגייר בין שני פסחים\u0004 אחרי פסח ראשון ולפני פסח שני, \u0003וכן קטן שהגדיל\u0004 ונתחייב במצוות \u0003בין שני פסחים — חייב לעשות פסח שני,\u0004 אלו \u0003דברי רבי. ר' נתן אומר: כל שזקוק\u0004 וחייב בעשיית פסח \u0003ראשון — זקוק לשני, כל שאין זקוק לראשון\u0004 כגון שהיה אז קטן או גוי — \u0003אין זקוק\u0004 גם \u0003לשני.\u0004","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]?\u0006 \u0003רבי סבר:\u0004 פסח \u0003שני רגל בפני עצמו הוא,\u0004 וכל אדם ואפילו זה שלא היה ראוי בראשון חייב בפסח שני אלא אם כן עשה כבר פסח ראשון.","ואילו \u0003ר' נתן סבר:\u0004 פסח \u0003שני\u0004 רק \u0003תשלומין\u0004 של פסח \u0003ראשון הוא,\u0004 שאם היה אדם צריך להקריב בראשון ונאנס ולא יכול — עושה את השני, אבל \u0003תקוני\u0004 \u0005[לתקן]\u0006 את ה\u0003ראשון, לא מתקין ליה\u0004 \u0005[מתקן אותו].\u0006 שאין הפסח השני פוטר מחיוב כרת אדם שהזיד ולא עשה את הראשון, אפילו אם עשה את השני. ואם שגג בראשון, אף על פי שהזיד בשני — פטור.","\u0003ור' חנניא בן עקביא סבר: שני תקנתא\u0004 \u0005[תקנתו]\u0006 של ה\u0003ראשון הוא,\u0004 שאמנם אינו חובה לעצמו, אבל המקריב בו מתקן כל מה שהחסיר בראשון ולכן אם לא עשה בראשון אפילו במזיד, אם יעשה בשני יתכפר לו ואינו חייב כרת.","ומעירים: כי \u0003שלשתן מקרא אחד דרשו\u0004 בצורות שונות שנאמר: \u0003\"והאיש אשר הוא טהור ובדרך לא היה\u0004 וחדל לעשות הפסח ונכרתה הנפש ההיא מעמיה כי קרבן ה' לא הקריב במועדו חטאו ישא האיש ההוא\u0003\"\u0004 (במדבר ט, יג) \u0003רבי סבר\u0004 כך יש להבין: \u0003\"וחדל לעשות הפסח ונכרתה\"\u0004 כלומר, ש\u0003לא עבד\u0004 \u0005[עשה]\u0006 בפסח \u0003ראשון,\u0004 והמשיך הכתוב ואמר \"כי קרבן ה' לא הקריב במועדו\" ומשמעות \"כי\" לדברי רבי היא \"או\" כלומר \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 חזר ועבר באיסור נוסף ש\u0003\"קרבן ה' לא הקריב במעדו\"\u0004 כלומר, בפסח ה\u0003שני\u0004 — רק עליו נאמר \"חטאו ישא האיש ההוא\".","ושואלים \u0003וממאי\u0004 \u0005[וממה\u0006 מנין יודעים אנו\u0005]\u0006 \u0003דהאי\u0004 \u0005[שאותו]\u0006 ביטוי \u0003\"חטאו ישא\"\u0004 הכוונה לעונש \u0003כרת הוא?\u0004 ושמא הכוונה לעונש אחר?"],["\u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003מגדף\u0004 האמור בתורה \"והנפש אשר תעשה ביד רמה מן האזרח ומן הגר, את ה' הוא מגדף ונכרתה הנפש ההיא מקרב עמה\" (במדבר טו, ל), ולא ברור מה משמע מגדף ואם הכוונה לחטא מסוים או לכל עבירה שבמזיד. ולדעת רבי: מגדף זה \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003מברך\u0004 (בלשון נקיה, כלומר: מקלל) \u0003השם. וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003במברך את השם: \"\u0004ואל בני ישראל תדבר לאמר איש איש כי יקלל אלהיו \u0003ונשא חטאו\"\u0004 (ויקרא כד, טו) ואם כן נאמר במגדף \"ונשא חטאו\" וכוונתו כפי המבואר בפסוק המקביל — לכרת.","\u0003וגמר האי\u0004 \u0005[ולמד\u0006 את המקרא \u0005הזה]\u0006 \u0003\"\u0004נשא \u0003חטאו\" דהכא\u0004 \u0005[\u0006הנאמר \u0005כאן]\u0006 במי שלא עשה פסח, \u0003מ\"\u0004 נשא \u0003חטאו\" דהתם\u0004 \u0005[ש\u0006נאמר \u0005שם].\u0006 ולכן, \u0003מה להלן\u0004 במגדף הכוונה לעונש \u0003כרת, אף כאן נמי\u0004 \u0005[גם כן]\u0006 במי שלא עשה פסח \"חטאו\" פירושו עונש \u0003כרת,\u0004 זוהי שיטת רבי.","ואילו \u0003ר' נתן סבר\u0004 שיש להבין את הכתוב באופן אחר: מה שנאמר \u0003\"וחדל לעשות הפסח ונכרתה\u0004 הנפש ההיא מעמיה כי קרבן ה' לא הקריב במעדו\" (במדבר ט, יג) \u0003דהאי\u0004 \u0005[שאותו]\u0006 \u0003\"כי\"\u0004 שנאמר בפסוק זה \u0003לשון דהא\u0004 \u0005[שהרי]\u0006 \u0003הוא\u0004 שהמלה כי משמשת בכמה משמעויות ואחת מהן בתור דהא = שהרי, \u0003והכי קאמר רחמנא\u0004 \u0005[וכך אמר,\u0006 יש להבין את מה \u0005שאמרה התורה]\u0006 \"כי את קרבן ה' לא הקריב\" \u0003דהא\u0004 \u0005[שהרי]\u0006 את \u0003\"קרבן ה' לא הקריב במעדו\"\u0004 כלומר בפסח \u0003ראשון,\u0004 ודינו כרת.","ושואלים: אם כן, \u0003האי\u0004 \u0005[אותו]\u0006 קטע מהפסוק שנאמר בו \u0003\"חטאו ישא\" מאי עביד ליה\u0004 \u0005[מה עושה לו\u0006 כיצד יבין אותו\u0005]?\u0006 ומשיבים: \u0003סבר\u0004 ר' נתן כי \u0003מגדף לאו היינו\u0004 \u0005[אינו]\u0006 \u0003מברך את השם\u0004 אלא מזמר ומשורר לעבודה זרה, ואם כן לא נתברר במפורש עונשו בידי שמים של מקלל ה', \u0003וגמר\u0004 \u0005[ולמד]\u0006 בגזירה שוה \u0003האי \"חטאו\" דהתם\u0004 \u0005[אותו\u0006 מילה \"ונשא \u0005חטאו\"\u0006 האמור \u0005שם]\u0006 במברך ה' \u0003מהאי \"חטאו\" דהכא\u0004 \u0005[מ\"חטאו\" זה\u0006 הכתוב \u0005כאן]\u0006 בפסח, \u0003מה \"חטאו\"\u0004 האמור \u0003הכא\u0004 \u0005[כאן]\u0006 בפסח לדברי ר' נתן הוא עונש \u0003כרת, אף התם\u0004 \u0005[שם]\u0006 במגדף \"ונשא את חטאו\" הכוונה היא לעונש \u0003כרת.\u0004","\u0003ור' חנניא בן עקביא סבר: \"וחדל לעשות הפסח ונכרתה\u0004 כי קרבן ה' לא הקריב במועדו\u0003\"\u0004 ומשמעות המילה \"כי\" לדבריו היא \"או\" כשיטת רבי, אולם לשיטתו יש לפרש את דברי הפסוק כך: \"כי\" כלומר \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"קרבן ה' לא הקריב במועדו\"\u0004 ומתי — אף בפסח \u0003שני — חייב כרת.\u0004","ושואלים: \u0003והאי\u0004 \u0005[וזה\u0006 הכתוב\u0005]\u0006 \u0003\"חטאו ישא\" מאי עביד ליה\u0004 \u0005[מה עושה בו\u0006 כיצד יבין אותו\u0005]?\u0006 ומשיבים: \u0003כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 וכדברי ר' נתן שבא ללמד לענין מברך השם.","\u0003הלכך\u0004 \u0005[לכן],\u0006 המסקנות המעשיות מן המחלוקת אלו הן: מי ש\u0003הזיד בזה ובזה\u0004 שהזיד ולא עשה לא פסח ראשון ולא פסח שני — \u0003דברי הכל חייב\u0004 כרת, \u0003שגג בזה ובזה — דברי הכל פטור.\u0004","\u0003הזיד בראשון ושגג בשני\u0004 לשיטת \u0003רבי ור' נתן — מחייבי\u0004 \u0005[מחייבים]\u0006 אותו כרת, שהרי בפסח ראשון הזיד ולא תיקן בפסח שני, ואילו \u0003לר' חנניא בן עקביא פטור\u0004 שלשיטתו אין חייב אלא מי שהזיד בשניהם.","\u0003שגג בראשון והזיד בשני,\u0004 לשיטת \u0003רבי\u0004 הרי \u0003חייב,\u0004 שהרי לדעתו פסח שני הוא רגל לעצמו, ומי שלא עשה את הראשון חייב לעשות את השני. ואילו \u0003לר' נתן ולר' חנניא בן עקביא\u0004 שאין השני אלא מילואים של הראשון, כיון שבראשון לא נתחייב (שהרי היה שוגג) גם על השני \u0003פטור.\u0004","\u0003איזו היא דרך רחוקה\u0004 האמורה בתורה שהמצוי בה פטור מלהקריב בפסח ראשון כשנמצא \u0003מן\u0004 העיר \u0003מודיעים ולחוץ וכמדתה\u0004 כשיעור מרחק זה מירושלים \u0003לכל רוח,\u0004 אלו \u0003דברי ר' עקיבא. ר' אליעזר אומר: מאיסקופת\u0004 (מפתן) \u0003העזרה ולחוץ\u0004 זוהי דרך רחוקה שמי שנמצא בשעת שחיטה מחוץ לעזרה פטור מפסח ראשון. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוסי: לפיכך נקוד\u0004 בתורה \u0003על \"ה'\"\u0004 במלה \"רחוקה\" כדי \u0003לומר\u0004 שיש לצמצם את הוראת המלה ולהבין \u0003לא מפני שרחוק ודאי אלא\u0004 אפילו \u0003מאיסקופת העזרה ולחוץ.\u0004","\u0003אמר עולא:\u0004 המרחק \u0003מן\u0004 העיר \u0003מודיעים לירושלים חמשה עשר מילין הויא\u0004 \u0005[הוא].\u0006 \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כי הא\u0004 \u0005[כ\u0006שיטה \u0005זו]\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כמה מהלך אדם\u0004 בינוני \u0003ביום\u0004 בינוני — \u0003עשרה פרסאות\u0004 שהם ארבעים מיל וחלוקת הזמנים: \u0003מעלות השחר ועד הנץ החמה\u0004 הולך הוא מרחק של \u0003חמשת מילין, משקיעת החמה ועד צאת הכוכבים\u0004 מהלך \u0003חמשת מילין, פשו לה תלתין\u0004 \u0005[נשארו להם שלשים]\u0006 מיל שהולך במשך היום עצמו, \u0003חמיסר מצפרא לפלגא דיומא\u0004 \u0005[חמשה עשר\u0006 מילין \u0005מהבוקר עד חצי היום]\u0006 \u0003וחמיסר מפלגא דיומא לאורתא\u0004 \u0005[וחמשה עשר\u0006 מילין \u0005מחצי היום לערב].\u0006","ומסבירים: כי \u0003עולא לטעמיה\u0004 \u0005[לטעמו\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר עולא: אי זה הוא דרך רחוקה — כל שאין יכול ליכנס\u0004 למקדש \u0003בשעת שחיטה.\u0004 וחיוב שחיטת הפסח מאימתי הוא מתחיל — מחצות היום ואילך ולכן אם הוא נמצא בזמן שחיטת הפסח במרחק של חמשה עשר מיל מירושלים, הרי הוא בדרך רחוקה לפי שאינו יכול להגיע לירושלים עד תום זמן שחיטה, והריהו דחוי מן הקרבן.","באותו ענין דנים, \u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003מעלות השחר עד הנץ החמה\u0004 מהלך \u0003חמשת מילין, מנא לן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכמו השחר עלה ויאיצו המלאכים\u0004 בלוט לאמור קום קח את אשתך ואת שתי בנותיך הנמצאות פן תספה בעוון העיר\u0003\"\u0004 (בראשית יט, טו) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"השמש יצא על הארץ ולוט בא צערה\"\u0004 (בראשית יט, כג) הרי שמעלות השחר עד הנץ החמה (זמן יציאת השמש) הוא המהלך מסדום לצוער. \u0003ואמר ר' חנינא: לדידי חזי לי ההוא אתרא\u0004 \u0005[אני ראיתי אותו מקום]\u0006 \u0003והויא\u0004 \u0005[והוא]\u0006 מרחק של \u0003חמשה מילין\u0004 ואפשר איפוא ללמוד מן הכתובים שיעור זמן זה.","\u0003גופא\u0004 \u0005[לגופו\u0006 של ענין שהזכרנו\u0005]\u0006 בקביעת דרך רחוקה \u0003אמר עולא: איזה הוא דרך רחוקה — כל שאין יכול ליכנס בשעת שחיטה\u0004 לעזרה. \u0003ורב יהודה אמר: כל שאין יכול ליכנס בשעת אכילה\u0004 לירושלים שרחוק עד כדי כך שלא יוכל להגיע לעיר עד סוף זמן אכילה בחצות הלילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לעולא: לדידך קשיא\u0004 \u0005[לשיטתך קשה]\u0006 \u0003ול\u0004שיטת \u0003ר' יהודה קשיא\u0004 \u0005[קשה].\u0006 \u0003לדידך קשיא\u0004 \u0005[לשיטתך קשה],\u0006 ש\u0003אמרת כל שאין יכול ליכנס בשעת שחיטה, והא\u0004 \u0005[והרי]\u0006 \u0003טמא שרץ\u0004 ש\u0003אין יכול ליכנס בשעת שחיטה\u0004 מפני טומאתו \u0003וקאמרת\u0004 \u0005[ואומר אתה]\u0006 כי \u0003שוחטין וזורקין על טמא שרץ,\u0004 אף שבשעת שחיטה עדיין טמא הוא ולא יטהר אלא בערב, בשעת אכילה.","\u0003ו\u0004אף \u0003לרב יהודה קשיא\u0004 \u0005[קשה],\u0006 ש\u0003אמר: כל שאין יכול ליכנס בשעת אכילה, והא\u0004 \u0005[והרי]\u0006 \u0003טמא שרץ\u0004 ש\u0003יכול ליכנס בשעת אכילה וקאמר\u0004 \u0005[ואמר]\u0006 הוא עצמו היפך שיטתו: \u0003אין שוחטין וזורקין על טמא שרץ\u0004 אף כי יכול הוא להטהר בשעת אכילה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003לא לדידי קשיא\u0004 \u0005[לא לשיטתי קשה]\u0006 \u0003ולא\u0004 לשיטת \u0003רב יהודה קשיא\u0004 \u0005[קשה].\u0006 \u0003לדידי לא קשיא\u0004 \u0005[לשיטתי אינו קשה]\u0006 משום שאני סבור כי \u0003דרך רחוקה\u0004 נאמרה רק \u0003לטהור ואין\u0004 שיקול של \u0003דרך רחוקה לטמא,\u0004 וכל שהוא רחוק כעת נדחה מיד מחובת הפסח ואין דנים בו אם יוכל להטהר ולאכול לאחר מכן."],["ואף \u0003לרב יהודה לא קשיא\u0004 \u0005[אינו קשה],\u0006 כי לשיטתו \u0003טמא שרץ רחמנא דחייה\u0004 \u0005[התורה\u0006 עצמה \u0005דחתה אותם]\u0006 שנאמר: \u0003\"איש איש כי יהיה טמא לנפש\"\u0004 (במדבר ט, י) \u0003מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 אפילו במקרה \u0003שחל שביעי שלו\u0004 של הטמא מת (\"טמא לנפש\") \u0003להיות בערב הפסח,\u0004 שבלילה היה יכול להיות טהור, \u0003ואפילו הכי אמר רחמנא לידחי\u0004 \u0005[ואפילו כך אמרה התורה שידחה]\u0006 משמע שכל שאינו ראוי בשעת שחיטת הפסח — ידחה, אף שיהיה ראוי בשעת אכילתו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 \u0003היה עומד חוץ\u0004 לעיר \u0003מודיעים ויכול ליכנס\u0004 לירושלים \u0003בסוסים ובפרדים\u0004 אבל לא בהליכה ברגל \u0003יכול יהא חייב\u0004 כרת אם לא בא לירושלים והקריב את קרבן פסח — \u0003תלמוד לומר: \"ובדרך לא היה\"\u0004 במדבר ט, יא) \u0003והלה\u0004 מכל מקום \u0003היה בדרך\u0004 רחוקה.","ולהיפך: \u0003היה עומד לפנים מן המודיעים\u0004 אולם \u0003אין יכול ליכנס מפני גמלים וקרונות המעכבות אותו, יכול לא יהא חייב\u0004 בקרבן פסח שהרי אינו יכול להכנס — \u0003תלמוד לומר \"ובדרך לא היה\"\u0004 (שם) כלומר הכל נקבע לפי המרחק, ואם אדם המצוי במקום קרוב אינו יכול להכנס — איננו קרוי מי שהיה בדרך רחוקה.","כיון שהזכרנו קודם כמה מהלך של אדם בינוני מביאים כמה ענינים הנסמכים במידה מסוימת על מאמר זה. \u0003אמר רבא: שיתא אלפי פרסי הוי עלמא\u0004 \u0005[ששת אלפים פרסות הוא\u0006 גודל \u0005העולם]\u0006 \u0003וסומכא דרקיעא אלפא פרסי\u0004 \u0005[עובי הרקיע אלף פרסות]\u0006 \u0003חדא\u0004 \u0005[אחד]\u0006 מן המספרים הללו, זה המתייחס לגודל העולם \u0003גמרא\u0004 \u0005[מסורת],\u0006 \u0003וחדא\u0004 \u0005[ואחת]\u0006 היא \u0003סברא\u0004 שסבר מדעתו.","כיצד? \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 כפי ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: כמה מהלך אדם בינוני ביום — עשר פרסאות\u0004 שהם ארבעים מיל. ומפרטים: \u0003מעלות השחר ועד הנץ החמה\u0004 מהלך \u0003חמשה מילין, משקיעת החמה עד צאת הכוכבים\u0004 מהלך \u0003חמשה מילין, נמצא עוביו של רקיע אחד מששה ביום.\u0004 שהרי כל היום כולו הנץ החמה ועד שקיעתה שבו מהלכת השמש ממזרח עד מערב הוא מהלך של ששת אלפים פרסות, הוא מהלך של שלושים מילים לאדם בינוני, והמרחק שהשמש עוברת מתחילת הופעתה עד שהיא יוצאת ונגלית מה שרבא קורא עוביו של רקיע שהוא זמן הדמדומים, בשחר ובערב, מהלכת חמה במשך זמן זה מהלך של חמשה מילין, שהוא אחד מששה של כל היום כולו, הוה אומר עוביו של רקיע הוא אחד מששה מן העולם והוא אלף פרסות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא: \u0003ר' יהודה אומר: עוביו של רקיע אחד מעשרה ביום. תדע\u0004 שכן הוא, \u0003כמה מהלך אדם בינוני ביום\u0004 (מעלות השחר ועד צאת הכוכבים) \u0003— עשר פרסאות\u0004 שהם ארבעים מיל, \u0003ומעלות השחר עד הנץ החמה\u0004 רק מהלך \u0003ארבעת מילין\u0004 (שהם פרסה אחת) ו\u0003משקיעת החמה ועד צאת הכוכבים ארבעת מילין, נמצאת עוביו של רקיע\u0004 רק \u0003אחד מעשרה ביום.\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לשיטת \u0003רבא.\u0004 וכמו כן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לשיטת \u0003עולא,\u0004 שלדעתו מהלך אדם בחצי יום חמשה עשר מיל, ולפי דברי ר' יהודה אדם מהלך בחצי יום ששה עשר מיל! ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006\u0003.\u0004","והשאלה היא: \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא זו קושיה חמורה]\u0006 גם לשיטת \u0003ר' יוחנן,\u0004 במה שמסר רבה בר בר חנה משמו כמה מהלך אדם ביום, ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 ר' יוחנן: \u0003אנא ביממא הוא דאמרי\u0004 \u0005[אני\u0006 שיעור מהלכו של כל \u0005היום הוא שאמרתי]\u0006 ולא קבעתי חלוקה פנימית בתוך היום, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שקבעו ואמרו שמעלות השחר ועד הנץ החמה הוא מהלך חמשה מילין ולא ארבעה — הם ש\u0003טעו, דקא חשבן דקדמא וחשוכא\u0004 \u0005[שהם החשיבו\u0006 את הזמן קצת \u0005מוקדם\u0006 וקצת \u0005מאוחר]\u0006 מזמן הדמדומים האמיתי.","ושואלים: \u0003לימא תיהוי תיובתא\u0004 \u0005[האם לומר שתהא\u0006 זו \u0005קושיה]\u0006 על דברי \u0003ר' חנינא\u0004 שהוכיח מן המקראות שמעלות השחר עד הזריחה הוא מהלך חמשה מילים! ודוחים: \u0003לא\u0004 אין להוכיח משם דבר כי שם נאמר: \"ויאיצו המלאכים בלוט\", משמע שהיו ממהרים ביותר, ולכן \u0003\"ויאיצו\" שאני\u0004 \u0005[שונה]\u0006 שבמקום ללכת כרגיל ארבעה מילין הלכו במהירות יתירה מרחק יותר גדול.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 עוד ראיות לענין גודלו של העולם, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 גודלה של \u0003מצרים היא ארבע מאות פרסה על ארבע מאות פרסה, ומצרים\u0004 היא \u0003אחד מששים\u0004 מגודלה של \u0003כוש, וכוש\u0004 היא \u0003אחד מששים בעולם,\u0004 וה\u0003עולם\u0004 גודלו \u0003אחד מששים בגן, וגן אחד מששים בעדן ועדן אחד מששים בגיהנם, נמצא כל העולם כולו ככיסוי קדירה\u0004 שהוא חלק קטן בלבד מגודל הקדרה לגבי \u0003גיהנם.\u0004 ועל כל פנים מחישוב גודלן של מצרים וכוש יוצא שהעולם גדול מששת אלפים פרסה.","ועוד; \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה אחרת: \u0003דתנא דבי אליהו\u0004 \u0005[ששנה בבית\u0006 מדרשו של \u0005אליהו]\u0006 \u0003ר' נתן אומר: כל הישוב כולו\u0004 כל החלק המיושב בעולם, \u0003תחת כוכב אחד יושב. תדע\u0004 שכן הוא, \u0003שהרי אדם נותן עינו בכוכב אחד, הולך למזרח\u0004 הישוב כמה שירצה \u0003עומד\u0004 הכוכב \u0003כנגדו\u0004 באותו מקום וכן הולך \u0003לארבע רוחות העולם\u0004 עדיין \u0003עומד\u0004 הכוכב \u0003כנגדו, מכלל\u0004 \u0005[מכאן]\u0006 ש\u0003כל הישוב כולו תחת כוכב אחד יושב\u0004 וכיון שאנו רואים כה הרבה כוכבים הרי שכל העולם כולו גדול מששת אלפי פרסה. ומעירים, אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לשיטת רבא.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממקור אחר, ששנינו: מערכת המזלות הקרויה \u0003עגלה\u0004 היא בצד \u0003צפון, ועקרב בדרום וכל הישוב כולו אינו יושב אלא בין עגלה לעקרב\u0004 שהרי בכל מקום בישוב רואים יחס זה בין המזלות. ועוד, \u0003וכל הישוב כולו אינו הוה אלא שעה אחת ביום\u0004 שהיחס בין העולם כולו וחלק הישוב שבו הוא כשעה ביום \u0003שאין חמה נכנסת לישוב אלא שעה אחת ביום\u0004 ובשאר חלקי היום היא במקומות מחוץ לו,","ו\u0003תדע\u0004 שכן הוא שהרי בשעה \u0003חמש\u0004 לזריחה \u0003חמה\u0004 עדיין \u0003במזרח, ובשבע חמה במערב, חצי שש\u0004 (חמש וחצי) \u0003וחצי שבע\u0004 (שש וחצי) \u0003חמה עומדת בראש כל אדם\u0004 שבכל איזורי הישוב חמה מצויה אז במרום השמים וזוהי השעה בה היא מהלכת מעל הישוב, והרי אף זו \u0003תיובתא\u0004 \u0005[קושיה]\u0006 לשיטת רבא.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 עוד ראיה, ש\u0003אמר רבן יוחנן בן זכאי: מה תשובה השיבתו בת קול לאותו רשע\u0004 נבוכדנצר ש\u0003אמר \"אעלה על במתי עב אדמה לעליון\"\u0004 (ישעיה יד, יד), \u0003יצתה בת קול ואמרה לו: רשע בן רשע,\u0004"],["\u0003בן בנו\u0004 (כלומר: הולך בדרכיו) \u0003של נמרוד הרשע, שהמריד את כל העולם כולו עלי במלכותו\u0004 בכך שהשיא עצה לאנשי דור הפלגה לבנות מגדל להלחם באמצעותו בצבא השמים, \u0003כמה\u0004 הן \u0003שנותיו של אדם\u0004 בסך הכל? \u0003שבעים שנה ואם בגבורת\u0004 שמאריך ימים יותר — יחיה \u0003שמונים שנה, שנאמר: \"ימי שנותינו בהם שבעים שנה ואם בגבורות שמונים שנה\"\u0004 (תהלים צ, י)","ואילו \u0003מן הארץ עד לרקיע מהלך חמש מאות שנה, ועוביו של רקיע מהלך חמש מאות שנה\u0004 שהוא כמליון ושמונה מאות אלפי פרסות \u0003ובין כל רקיע לרקיע\u0004 שוב \u0003מהלך חמש מאות שנה וכן בין כל רקיע ורקיע\u0004 וכיצד יוכל אדם להגיע עד שם בימי חייו, ואיך יכול אדם לומר \"אדמה לעליון\" \u0003\"אך אל שאול תורד אל ירכתי בור\"\u0004 (ישעיה יד, טו). ועל כל פנים מכאן \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לשיטת רבא, שאמר שעובי הרקיע הוא אלף פרסה בלבד.","ואגב דיונים אלה בעניני העולם ומבנהו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חכמי ישראל אומרים: גלגל\u0004 מקום שבו הכוכבים נעים \u0003קבוע, ומזלות חוזרין\u0004 שהם המסתובבים במקומם בגלגל. \u0003וחכמי אומות העולם אומרים גלגל\u0004 כולו \u0003חוזר\u0004 (מסתובב) \u0003ומזלות קבועין\u0004 בו. \u0003אמר רבי: תשובה\u0004 (סתירה) \u0003לדבריהם\u0004 שאין גלגל המזלות כולו מסתובב ש\u0003מעולם לא מצינו\u0004 מערכת המזלות הקרויה \u0003עגלה בדרום ועקרב בצפון.\u0004 משמע שהכוכבים עצמם הם המסתובבים מעט במקומותיהם ולא הגלגל כולו שאם לא כן לא יתכן שבאופן קבוע יהיה מזל עגלה בדרום ועקרב בצפון.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הוכחה זו \u0003רב אחא בר יעקב: ודילמא\u0004 \u0005[ושמא]\u0006 הכוכבים בגלגל קבועים \u0003כבוצינא דריחיא\u0004 \u0005[כברזל הרחיים]\u0006 שאבני הריחים מסתובבות סביבו והוא עומד יציב במקומו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003כצינורא דדשא\u0004 \u0005[כציר הדלת]\u0006 שהוא קבוע במקומו והדלת סובבת סביבו סיבוב גדול וכן הוא מהלך המזלות שהם קבועים בתוך גלגל הקבוע בתוך גלגל אחר והגלגל הפנימי עומד במקום קבוע ולכן נראים המזלות תמיד במקום אחד והגלגל החיצוני סובב סביבו ומוליך את החמה הקבועה בו סביב כל המזלות. ואם כן אין דברי רבי הוכחה גמורה.","ועוד מחלוקת מעין זו: \u0003חכמי ישראל אומרים: ביום חמה מהלכת למטה מן הרקיע\u0004 ולכן היא נראית \u0003ובלילה\u0004 עולה \u0003למעלה מן הרקיע. וחכמי אומות העולם אומרים: ביום חמה מהלכת למטה מן הרקיע ובלילה למטה מן הקרקע\u0004 סביב לכדור הארץ. \u0003אמר רבי: ונראין דבריהן מדברינו,\u0004 וראיה לדבר \u0003שביום מעינות\u0004 שנובעים מעומק האדמה \u0003צוננין, ובלילה רותחין\u0004 (חמים) בהשוואה למזג האויר מסביב והרי זה כסיוע לסברה שהם מתחממים מכוח חום החמה שמתחת לקרקע.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' נתן אומר: בימות החמה חמה מהלכת בגובה של רקיע, לפיכך כל העולם כולו רותח\u0004 (חם) \u0003ומעינות\u0004 שהם נמוכים על פני הקרקע \u0003צוננין\u0004 ואילו \u0003בימות הגשמים חמה מהלכת בשיפולי\u0004 (בתחתית) \u0003רקיע לפיכך כל העולם כולו צונן\u0004 אבל \u0003מעינות רותחין\u0004 ביחס למזג האויר שסביבן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בארבעה שבילין חמה מהלכת\u0004 בארבע עונות השנה ובכל שינוי מזג האויר: \u0003ניסן אייר וסיון — מהלכת\u0004 חמה \u0003בהרים, כדי לפשר\u0004 (להפשיר, להמיס) \u0003את השלגין\u0004 שהצטברו בחורף, \u0003תמוז אב ואלול — מהלכת\u0004 החמה \u0003בישוב, כדי לבשל את הפירות, תשרי מרחשון וכסליו — מהלכת\u0004 החמה \u0003בימים, כדי ליבש את הנהרות\u0004 שאז הנהרות נובעים פחות מבכל ימות השנה, והמים נעשים ענני גשם, \u0003טבת שבט ואדר — מהלכת במדבר, שלא ליבש את הזרעים\u0004 שנזרעו בישוב ומתחילים לצמוח בעונה זו.","במשנה שנינו ש \u0003ר' אליעזר אומר\u0004 שאדם המצוי \u0003מאיסקופת\u0004 העזרה ולחוץ הרי הוא כמצוי בדרך רחוקה. ושואלים: \u0003ואף על גב דמצי עייל, ולא אמרינן ליה קום עייל\u0004 \u0005[ואף על פי שהוא יכול להכנס אין אנו אומרים לו קום הכנס]?!\u0006 וסומכים על כך שברגע הקובע אין החיוב חל עליו לפי שלא היה בתוך העזרה עצמה? \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יהודי ערל\u0004 מבוגר \u0003שלא מל — ענוש כרת\u0004 בפסח, כי הערל אינו אוכל בפסח, ולכך אומרים לו למול את עצמו ואם לא מל הרי שהזיד ולא הקריב כתוצאה מכך קרבן פסח וחייב. אלו \u0003דברי ר' אליעזר.\u0004 ומכאן שר' אליעזר עצמו סבור כי חייב אדם לעשות מאמץ שתחול עליו חובת הפסח ומי שאינו עושה כן הריהו כמזיד!","\u0003אמר אביי: דרך רחוקה\u0004 נאמרה לענין פטור מפסח ראשון רק \u0003לטהור, ואין\u0004 נאמרה \u0003דרך רחוקה לטמא\u0004 ולפסול, ולכן אף שלטמא או לפסול (כגון ערל) אין היתר של דרך רחוקה ולכן אם לא מל חייב כרת וצריך להזהירו על כך, מכל מקום לגבי הטהור שנאמר בו היתר דרך רחוקה אינו חייב כרת על ביטולו, שוב אין צורך להזהירו על כך.","\u0003רבא אמר: תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 שנחלקו בשיטת ר' אליעזר \u0003דתניא\u0004 \u0005[שכן\u0006 \u0005שנינו\u0006 בברייתא]: \u0003ר' אליעזר אומר: נאמר ריחוק מקום בפסח ונאמר ריחוק מקום במעשר\u0004 שני ככתוב: \"כי ירחק ממך המקום אשר יבחר ה' אלהיך לשום שמו שם\" (דברים יד, כד), \u0003מה להלן\u0004 במעשר הכוונה היא ריחוק \u0003חוץ\u0004 למקום \u0003אכילתו\u0004 שאין המעשר נאכל אלא בירושלים, \u0003אף כאן\u0004 ריחוק מקום אינו אלא מ\u0003חוץ\u0004 למקום \u0003אכילתו\u0004 שהוא כל תחום העיר ירושלים, והמצוי בה נתחייב בפסח.","ואילו \u0003ר' יוסי בר ר' יהודה אומר משום ר' אליעזר:\u0004 הכוונה \u0003חוץ לעשייתו\u0004 כלומר מקום שחיטתו בעזרה.","ושואלים: \u0003כמאן אזלא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת]\u0006 הלכה זו ש\u0003אמר ר' יצחק בר רב יוסף: בטמאים\u0004 כלומר בקביעת המנין אם יש רוב טהורים או רוב טמאים \u0003הלך אחר רוב העומדין בעזרה\u0004 ואין מונים את כל ישראל שבעיר. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 כשיטת \u0003ר' יוסי בר ר' יהודה שאמר משום ר' אליעזר,\u0004 שלדעתו מצב המביא לשינוי בזמן הקרבת הפסח כגון דרך רחוקה או הקרבת הפסח בטומאה, נקבעים לפי מצב הדברים בזמן ובמקום השחיטה בעזרה.","במשנה שנינו כי \u0003אמר לו ר' יוסי: לפיכך\u0004 נקוד על ה' של \"רחוקה\". \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יוסי הגלילי אומר\u0004 אילו נאמר רק \u0003\"דרך\u0004 רחוקה\u0003\" שומע אני מהלך שנים או שלשה ימים\u0004 לפחות, אולם \u0003כשהוא אומר\u0004 בהמשך \u0003\"\u0004והאיש אשר הוא טהור \u0003ובדרך לא היה\"\u0004 (במדבר ט, יג) ואינו מזכיר רחוקה \u0003מגיד\u0004 ללמד \u0003שמאסקופת העזרה ולחוץ קרוי דרך\u0004 ואין צריכים דווקא דרך רחוקה כמשמעה."],["\u0003מה בין פסח הראשון לשני? הראשון אסור ב\"בל יראה\" ו\"בל ימצא\"\u0004 חמץ, \u0003והשני — חמץ ומצה\u0004 יכולים להיות \u0003עמו בבית.\u0004 והבדל נוסף \u0003הראשון טעון הלל\u0004 בשעת \u0003אכילתו, והשני אינו טעון הלל\u0004 בשעת \u0003אכילתו.\u0004 ובכך שניהם שווים: \u0003זה\u0004 הראשון \u0003וזה\u0004 השני \u0003טעון הלל\u0004 בשעת \u0003עשייתן\u0004 (שחיטתן) \u0003ונאכלין\u0004 שניהם \u0003צלי על מצה ומרורים, ודוחין את השבת\u0004 לענין שחיטה וזריקת הדם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במדרש הלכה בענין פסח שני: \u0003\"\u0004לא ישאירו ממנו עד בוקר ועצם לא ישברו בו \u0003ככל חקת הפסח יעשו אתו\"\u0004 (במדבר ט, יב), מלשון הכתוב \"אותו\" נלמד — \u0003במצוה שבגופו הכתוב מדבר,\u0004 שבכל הדברים הנוגעים בגופו של קרבן הפסח צריך לנהוג כמו בפסח ראשון,","\u0003מצוה שעל גופו\u0004 שאינה מעצם עשיית הקרבן אבל קשורה בו, \u0003מנין\u0004 שאף היא חלה בפסח שני כבפסח ראשון? \u0003תלמוד לומר: \"על מצות ומררים יאכלהו\"\u0004 (במדבר ט, יא). \u0003יכול אפילו\u0004 יקיימו בו \u0003כל מצות\u0004 פסח \u0003שלא על גופו\u0004 כלל, כגון חובת ביעור חמץ — \u0003תלמוד לומר: \"ועצם לא ישברו בו\"\u0004 (במדבר ט, יב), ונלמד: \u0003מה שבירת העצם מיוחד\u0004 משאר מצוות בפסח שהיא \u0003מצוה שבגופו — אף כל מצוה שבגופו\u0004 בלבד, שרק בה חובת פסח שני.","\u0003איסי בן יהודה אומר\u0004 שאינו צריך ללמוד זאת מכתוב זה אלא מעצם המלים \u0003\"יעשו אתו\"\u0004 אתה למד כי \u0003במצות שבגופו הכתוב מדבר.\u0004","ומבררים את הברייתא לפרטיה, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יכול אף מצוה שלא על גופו\u0004 צריך יהיה לקיימה בפסח שני, ותוהים: \u0003הא אמרת\u0004 \u0005[הרי אמרת]\u0006 \u0003במצוה שבגופו הכתוב מדבר\u0004 ומהיכן תלמד להוסיף אף מצוות אלה?","ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003השתא דאמרת\u0004 \u0005[עכשיו שאמרת]\u0006 גם הלכה נוספת זו \u0003\"על מצות ומררים יאכלהו\" אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003\"יעשו אתו\" לאו\u0004 \u0005[לא]\u0006 \u0003דוקא הוא,\u0004 אינו מדויק ומצמצם, ובכלל מצוות פסח שני גם מצוות אחרות, שאינן קשורות ממש לגופו של הקרבן, \u0003אימא\u0004 \u0005[אמור]\u0006 שמא \u0003הוה ליה\u0004 \u0005[יהיה לו]\u0006 כתוב זה נדרש במדת \u0003פרט וכלל\u0004 שתחילה נאמר \"על מצות ומרורים יאכלוהו\" ו\"לא ישאירו ממנו עד בוקר\" ואחר כך כלל \"ככל חוקת הפסח יעשו אותו\" ולפי כללי מדרש ההלכה \u0003נעשה כלל מוסיף על הפרט, ואפילו כל מילי נמי\u0004 \u0005[הדברים גם כן]\u0006 ילמדו מתוך הכלל, לדמות פסח שני לראשון לכל דבר ואפילו לענין השבתת שאור, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הפסוק \"ועצם לא ישברו בו\" ללמד שאין הדבר כן אלא כל מצוה שאינה על גופו אינה צריכה שתתקיים בשני.","ושואלים: \u0003איסי בן יהודה, האי\u0004 \u0005[זה]\u0006 הכתוב של \u0003\"עצם\u0004 לא ישברו בו\u0003\"\u0004 שאינו למד ממנו לענין הגבלת ההשוואה בין פסח ראשון ושני, \u0003מאי עביד ליה\u0004 \u0005[מה עושה הוא בו],\u0006 ומה למד הוא ממנו? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נחוץ לו]\u0006 ללמוד ממנו שאיסור שבירת עצם קיים \u0003אחד עצם שיש בו מוח\u0004 בתוכו \u0003ואחד עצם שאין בו מוח.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שלא דרשו כאיסי \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 שנאמר: \u0003\"יעשו אתו\" מאי עבדי ליה\u0004 \u0005[מה עושים הם בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריכים\u0006 הם \u0005לו]\u0006 ללמד: \u0003שאין שוחטין את הפסח על היחיד\u0004 כי \"יעשו\" לשון רבים הוא, ואף שאין איסור גמור בכך, מכל מקום \u0003כמה\u0004 ש\u0003אפשר לאהדורי מהדרינן\u0004 \u0005[לחזר\u0006 ולהוסיף מנויים לפסח \u0005מחזרים].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: נאמר \u0003\"ככל חקת הפסח יעשו אתו\" יכול כשם\u0004 שהפסח \u0003הראשון אסור ב\"בל יראה\" ו\"בל ימצא\"\u0004 חמץ \u0003כך\u0004 פסח \u0003שני אסור ב\"בל יראה\" ו\"בל ימצא\" — תלמוד לומר: \"על מצות ומררים יאכלהו\"\u0004 בלבד ולא מצוות אחרות האמורות בפסח ראשון.","\u0003ואין לי אלא\u0004 שבפסח שני חייבים ב\u0003מצות עשה\u0004 שבפסח ראשון, \u0003מצות לא תעשה\u0004 שבפסח ראשון \u0003מנין\u0004 שחייבים אף בהן? \u0003תלמוד לומר: \"לא ישאירו ממנו עד בקר\u0004 ועצם לא ישברו בו\u0003\"\u0004 (במדבר ט, יב).","\u0003ואין לי\u0004 מכתוב זה \u0003אלא\u0004 שצריך לקיים בפסח שני \u0003מצות לא תעשה שניתק לעשה,\u0004 כלומר אותן מצוות לא תעשה שיש להן תיקון על ידי מצוות עשה כגון האיסור להשאירו עד בוקר שיש לו תיקון במצוות עשה מיוחדת שאת הנותר שורפים באש. \u0003מצות לא תעשה גמור מנין? תלמוד לומר: \"ועצם לא ישברו בו\"\u0004 ומדוגמאות אלה נלמד: \u0003מה הפרט\u0004 אותן מצוות שפורטו במצות פסח שני — \u0003מפורש,\u0004 והריהו כולל \u0003מצות עשה, ולא תעשה שניתק לעשה, ולא תעשה גמור — אף כל מצות עשה ולא תעשה שניתק לעשה ולא תעשה גמור\u0004 כלולים בכך.","כבאור לברייתא זו שואלים: \u0003בכלליה\u0004 \u0005[על ידי הכלל]\u0006 של \u0003\"מצות ומררים\"\u0004 שהרי הכלל של \"ככל חוקת הפסח\" מתפרש שהוא מוסב על כל מיני הפרטים שקדמוהו, וכלל זה \u0003מאי קא מרבי\u0004 \u0005[מה הוא\u0006 בא \u0005לרבות,\u0006 להוסיף\u0005]\u0006 על הפרט? ומשיבים: הריהו בא לרבות מצוות \u0003צלי אש,\u0004 שאף פסח שני חייב להיות צלי אש. ושואלים: \u0003בפרטיה מאי ממעיט ליה\u0004 \u0005[בפירוטו מה הוא ממעט]?\u0006 שהרי יש גם פרט בדבר! ומשיבים: פרט זה בא ללמדנו שלא הכל נלמד מן הכלל, שאיננו חייב בפסח שני במצות \u0003השבתת שאור.\u0004 ושואלים: \u0003איפוך אנא\u0004 \u0005[אהפוך אני]\u0006 ואומר להיפך: שלא יהיה פסח שני חייב להיעשות צלי, ויהא חייב בהשבתת שאור! ומשיבים: \u0003מצוה דגופיה\u0004 \u0005[שבגופו]\u0006 \u0003עדיף,\u0004 שמסתבר שיש לדמות פסח שני לפסח ראשון קודם כל במצוות הנוגעות לעצם עשייתו.","ועוד שואלים: \u0003בכלליה\u0004 \u0005[בכלל\u0006 של\u0005]\u0006 \u0003\"לא ישאירו ממנו עד בקר\" מאי קא מרבה ליה\u0004 \u0005[מה הוא מרבה\u0006 מוסיף, \u0005בו]?\u0006 ומשיבים: הריהו מוסיף את המצוה שהיא כיוצא בו והוא \u0003\"לא תוציא ממנו\u0004 החוצה \u0003\"\u0004שאין להוציא את הפסח מחבורה לחבורה \u0003דדמי ליה\u0004 \u0005[ש\u0006הוא \u0005דומה לו]\u0006 לפרט של \"לא ישאירו\". \u0003דהאי\u0004 \u0005[שזה]\u0006 ב\"לא ישאירו\" הוא \u0003מיפסל\u0004 \u0005[נפסל]\u0006 \u0003בנותר, והאי\u0004 \u0005[וזה]\u0006 ב\"לא תוציא\" הוא \u0003מיפסל\u0004 \u0005[נפסל]\u0006 \u0003ביוצא\u0004 מחוץ לתחומו\u0005.\u0006","ושואלים: \u0003בפרטיה מאי קא ממעט ליה\u0004 \u0005[על ידי פירוטו מה הוא ממעט]?\u0006 ומשיבים: לא תעשה של \u0003\"לא יראה ולא ימצא\u0004 חמץ \u0003\"\u0004\u0003דדמי ליה\u0004 \u0005[שדומה לו],\u0006 \u0003דהאי\u0004 \u0005[ש\u0006על \u0005זה\u0006 \"לא ישאירו\"\u0005]\u0006 \u0003אינו לוקה דהוה\u0004 \u0005[שהריהו]\u0006 \u0003לאו שניתק לעשה\u0004 שכן יש לו תיקון בשריפה. \u0003והאי\u0004 \u0005[וזה]\u0006 \"לא יראה\" \u0003אינו לוקה דהוה ליה\u0004 \u0005[שהריהו]\u0006 גם כן \u0003לאו שניתק לעשה\u0004 שאף בו יש תיקון על ידי שריפה. ושוב מקשים: \u0003איפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 ואומר שהכלל בא לרבות ביעור חמץ ובפרט בא למעט את הנותר! ומשיבים: \u0003מצוה דגופיה\u0004 \u0005[שבגופו]\u0006 \u0003עדיף\u0004 על מצוה שאינה בגופו לענין השואת פסח שני לראשון, ולכן יש לרבות את הנותר.","ושואלים עוד: \u0003בכלליה\u0004 \u0005[בכלל של]\u0006 \u0003\"עצם לא ישברו בו\"\u0004"],["\u0003מאי קא מרבה\u0004 \u0005[מה הוא מוסיף]\u0006 על האמור במפורש? ומשיבים: את מצות \u0003\"אל תאכלו ממנו נא\"\u0004 (שמות יב, ט). ושואלים: \u0003בפרטיה מאי קא ממעטי\u0004 \u0005[בפרוטו מה הוא ממעט]?\u0006 ומשיבים: למעט את מצות \u0003\"לא תשחט על חמץ דם זבחי\"\u0004 (שמות לד, כה). ומקשים: \u0003איפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 ואומר להיפך! ומשיבים: \u0003מצוה דגופיה עדיף\u0004 \u0005[שבגופו עדיפה]\u0006 להשוות בעשיית פסח שני לראשון, ולכן יש לרבות לאסור בו לאכילת נא ולמעט שחיטת הפסח על חמץ.","שנינו במשנה שהפסח \u0003הראשון טעון הלל באכילתו\u0004 ולא השני. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 מה מקורם במקרא? \u0003אמר ר' יוחנן משום ר' שמעון בן יהוצדק: אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"השיר יהיה לכם כליל התקדש חג\"\u0004 (ישעיה ל, כט) ומכאן נלמד: \u0003לילה המקודש לחג\u0004 שנוהגים בו איסורי יום טוב כליל פסח הראשון — \u0003טעון הלל, לילה שאין מקודש לחג\u0004 שהרי ליל פסח השני איננו חג — \u0003אין טעון הלל.\u0004","במשנה אמרנו: \u0003זה וזה טעונין הלל בעשייתן.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של דבר\u0005]\u0006 ומה המקור לדין זה שעשיית פסח שני טעון הלל? ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003לילה קא ממעט\u0004 \u0005[את\u0006 דיני הפסח הנעשים ב\u0005לילה ממעט]\u0006 הכתוב שאמר \"כליל התקדש חג\" אבל את דיני הפסח הנעשים ב\u0003יום לא קא ממעט\u0004 \u0005[אינו ממעט]\u0006 וכיון שכן נוהגים בדין אמירת הלל בשעת השחיטה בפסח שני כבראשון שחיטת הפסח נעשית ביום. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שדבר זה מובן מן הסברה: \u0003אפשר ישראל\u0004 מקיימים את המצוה ו\u0003שוחטין את פסחיהן\u0004 בפסח או \u0003נוטלין את לולביהן\u0004 בסוכות \u0003ואין אומרים\u0004 דברי \u0003הלל?\u0004 אלא ודאי אומרים הלל אף בשחיטת פסח שני, ודבר זה אינו צריך מקרא מפורש.","שנינו עוד במשנה, כי שני הפסחים \u0003נאכלין צלי\u0004 ודוחים את השבת. ונדייק מכאן: \u0003שבת — אין\u0004 \u0005[כן]\u0006 דוחה פסח שני, אולם \u0003טומאה — לא\u0004 דוחה. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא\u0004 כשיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 פסח שני \u0003דוחה את השבת, ואין דוחה את הטומאה. ר' יהודה אומר: אף דוחה את הטומאה.\u0004","ומסבירים: \u0003מאי טעמיה דתנא קמא\u0004 \u0005[מה טעמו של התנא הראשון],\u0006 סבור הוא: \u0003מפני טומאה דחיתיו\u0004 לאותו אדם שלא יעשה פסח ראשון ועתה \u0003יחזור ויעשה בטומאה?! ור' יהודה\u0004 סבור: \u0003התורה חזרה\u0004 (השתדלה, רצתה) \u0003עליו\u0004 על הטמא שיזכה \u0003לעשותו\u0004 (את הפסח) \u0003בטהרה,\u0004 אם לבסוף נתברר ש\u0003לא זכה — יעשה\u0004 בכל אופן ואפילו \u0003בטומאה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: \u0003פסח ראשון דוחה את השבת,\u0004 וכן \u0003פסח שני דוחה את השבת. פסח ראשון דוחה את הטומאה\u0004 וכן \u0003פסח שני דוחה את הטומאה. פסח ראשון טעון לינה\u0004 בליל החג ואסור לזובחים לחזור לבתיהם שמחוץ לעיר ואף \u0003פסח שני טעון לינה.\u0004","ומבררים: \u0003דוחה את הטומאה כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 \u0003כר' יהודה.\u0004","אולם וכי לשיטת \u0003ר' יהודה\u0004 פסח שני \u0003טעון לינה? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003ר' יהודה אומר: מניין לפסח שני שאין טעון לינה שנאמר\u0004 בפסח: \u0003\"\u0004ובישלת ואכלת במקום אשר יבחר ה' אלהיך בו \u0003ופנית בבקר והלכת לאהליך\"\u0004 (דברים טז, ז) \u0003וכתיב\u0004 \u0005[וכתוב]\u0006 מיד לאחר מכן: \u0003\"ששת ימים תאכל מצות\u0004 וביום השביעי עצרת לה' אלהיך לא תעשה מלאכה\u0003\"\u0004 (דברים טז, ח) ומן הסמיכות נלמד: פסח שיש בו דין מצה \u0003הנאכל לששה\u0004 והוא חג המצות שבניסן \u0003טעון לינה,\u0004 פסח \u0003שאין נאכל\u0004 בו מצות \u0003לששה — אין טעון לינה,\u0004 והרי זו סתירה בשיטת ר' יהודה!","ומשיבים: \u0003תרי תנאי\u0004 \u0005[שני תנאים\u0006 הם\u0005]\u0006 ושניהם \u0003אליבא\u0004 \u0005[על פי\u0006 שיטת\u0005]\u0006 \u0003ר' יהודה,\u0004 אחד סבור שלדבריו פסח שני טעון לינה, ואחד סבור שלדבריו אינו טעון לינה.","\u0003הפסח שבא בטומאה\u0004 כשרוב ישראל היו טמאים, בכל זאת \u0003לא יאכלו ממנו זבין וזבות נדות ויולדות\u0004 שהרי נדחתה טומאה בפסח לרוב ישראל היא טומאת מת ולא טומאה אחרת. אולם אם עברו ו\u0003אכלו — פטורין מכרת\u0004 כי אף שאוכל קדשים בטומאה חייב כרת, כיון שפסח זה כולו בטומאה הוא — אף אלו פטורים.","\u0003ור' אליעזר פוטר\u0004 טמאים אלה מכרת \u0003אף על ביאת מקדש\u0004 בטומאה, שאפילו אלה שלא הותרו בפסח, מכל מקום כיון שכל ישראל נכנסים אז למקדש בטומאה אף אלה אינם חייבים על ביאה בטומאה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003זבין וזבות נדות ויולדות שאכלו\u0004 מן ה\u0003פסח שבא בטומאה, יכול יהו חייבין\u0004 כרת על אכילה זו \u0003תלמוד לומר:\u0004 \"והבשר אשר יגע בכל טמא לא יאכל באש ישרף והבשר \u0003כל טהור יאכל בשר, והנפש אשר תאכל בשר מזבח השלמים אשר לה' וטומאתו עליו ונכרתה\u0004 הנפש ההיא מעמיה\" (ויקרא ז יט — כ)","ומצירוף הכתובים יש להבין כך: אם היה הקרבן \u0003נאכל\u0004 רק \u0003לטהורים — חייבים עליו משום\u0004 אכילת \u0003טמא, ושאינו נאכל לטהורין — אין טמאין חייבין עליו משום טמא.\u0004","\u0003ר' אליעזר אומר: יכול דחקו זבין\u0004 או מצורעים \u0003ונכנסו לעזרה\u0004 במקום שאסורים בכניסה לשם \u0003בפסח הבא בטומאה, יכול יהו חייבין\u0004 כרת על ביאת מקדש בטומאה \u0003תלמוד לומר: \"וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש\"\u0004 (במדבר ה, ב) ומכאן נלמד: \u0003בזמן שטמאי מתים משתלחין\u0004 מן המחנה והמקדש אף \u0003זבין ומצורעין משתלחין, אין טמאי מתים משתלחין\u0004 שהרי הם מקריבים ואוכלים בטומאה — אף \u0003אין זבין ומצורעין משתלחין.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף\u0004 בהמשך להלכות הקודמות: \u0003דחקו טמאי מתים ונכנסו להיכל\u0004 שהוא מקום שאין נעשים בו צרכי הפסח והכניסה שם לכתחילה מותרת רק לכהנים והיה זה \u0003בפסח הבא בטומאה, מהו,\u0004 מה דינם? \u0003מדאישתרי\u0004 \u0005[מ\u0006כיון \u0005שהותרה]\u0006 \u0003טומאת עזרה\u0004 לשם עשיית צרכי הפסח \u0003אישתרי נמי\u0004 \u0005[הותרה גם כן]\u0006 \u0003טומאת היכל, או דילמא\u0004 \u0005[שמא]\u0006 \u0003מאי דאישתרי\u0004 \u0005[מה שהותר] —\u0006 \u0003אישתרי\u0004 \u0005[הותר],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 ש\u0003לא אישתרי\u0004 \u0005[הותר] —\u0006 \u0003לא אישתרי\u0004 \u0005[הותר],\u0006 וחייבים על כניסה זו!","\u0003אמר רבא\u0004 פיתרון לדבר: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 באותו ענין \u0003\"וישלחו מן המחנה\"\u0004 ו\"מן המחנה\" הוא לשון מיעוט ומשמע: \u0003אפילו מקצת מחנה,\u0004 כלומר: מצוות השילוח חלה אפילו לגבי מקצת מחנה, ואף בפסח הבא בטומאה שמותרים במקצת מחנה שכינה, שמביאים פסח לעזרת ישראל לא הותרו בכל מחנה שכינה והאיסור על כניסה להיכל נשאר במקומו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003אמר רבא\u0004 פתרון אחר: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"וישלחו מן המחנה\u0004 כל צרוע וכל זב וכל טמא לנפש מזכר עד נקבה תשלחו \u0003אל מחוץ למחנה תשלחום\"\u0004 (במדבר ה, ב-ג), וכך הוא מדייק: \u0003כל היכא דקרינן ביה\u0004 \u0005[כל מקום שאנו קוראים בו]\u0006 במקרא וחל עליו הדין של \u0003\"אל מחוץ למחנה תשלחום\"\u0004 מכל המחנה בשלמות — \u0003קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 גם \u0003\"וישלחו מן המחנה\"\u0004 אפילו ממקצתו של מחנה. ואם אין משלחים מכל המחנה — שוב אין אותו איסור חל אפילו על חלקו.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב יוסף\u0004 שאלה בדומה לזה: \u0003דחקו טמאי מתים ואכלו\u0004 באיסור \u0003אימורי\u0004 (חלקי קרבן — כליות, אליה ויותרת הכבד — הנשרפים על המזבח) של \u0003פסח הבא בטומאה,\u0004 האם חייבים משום אכילת קדשים בטומאה?"],["\u0003מהו\u0004 דינם האם חייבים כרת משום אוכלי קודשים בטומאה? והשיקולים: \u0003מדאישתרי\u0004 \u0005[מ\u0006כיון \u0005שהותרה]\u0006 \u0003טומאת בשר אישתרי נמי\u0004 \u0005[הותרה גם כן]\u0006 \u0003טומאת אימורין, או דילמא\u0004 \u0005[שמא]\u0006 נאמר: \u0003מאי דאישתרי\u0004 \u0005[מה שהותר] —\u0006 \u0003אישתרי\u0004 \u0005[הותר],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 ש\u0003לא אישתרי\u0004 \u0005[הותר] —\u0006 \u0003לא אישתרי\u0004 \u0005[הותר].\u0006","\u0003אמר רבא: מכדי\u0004 \u0005[הרי]\u0006 \u0003טומאת אימורין מהיכא איתרבי\u0004 \u0005[מהיכן נתרבתה]\u0006 מהיכן למדוה שאף בה נוהג דין טומאה — \u0003מטומאת בשר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \"והנפש אשר תאכל בשר מזבח השלמים \u0003אשר לה'\u0004 ונכרתה הנפש ההיא מעמיה\" (ויקרא ז, כ), ולמדנו מהריבוי \u0003\"אשר לה'\" — לרבות את האימורין\u0004 שאכילתו בטומאה ומחייבת כרת.","וכיון שזה המקור, ממילא יש בו הגבלה: \u0003כל היכא דאיתיה\u0004 \u0005[היכן שישנו]\u0006 \u0003ל\u0004איסור \u0003טומאת בשר, איתיה\u0004 \u0005[ישנו]\u0006 אף \u0003לטומאת אימורין. כל היכא דליתיה\u0004 \u0005[היכן שאינו]\u0006 אסור \u0003לטומאת בשר\u0004 כגון בפסח הבא בטומאה, אף \u0003ליתיה\u0004 \u0005[אינו]\u0006 \u0003לטומאת אימורין.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' זירא: אימורי פסח מצרים\u0004 אותו פסח ראשון שהביאו ישראל לפני צאתם ממצרים \u0003היכא אקטרינהו\u0004 \u0005[היכן הקטירו,\u0006 שרפו \u0005אותם]?\u0006 שהרי לא נאמר שבנו שם מזבח. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 מה מקום לשאלה זו? \u0003ומאן לימא לן\u0004 \u0005[ומי יאמר לנו]\u0006 ש\u0003לא שויסקי עבוד\u0004 \u0005[עשו אותם\u0006 בשר \u0005צלי]\u0006 ואכלום? שהרי כל הדינים שנאמרו בתורה בדיני קרבנות עדיין לא ניתנו לישראל, ולא חילקו בין הבשר ובין החלבים ומן הסתם צלאום ואכלום יחד (ערוך).","\u0003ועוד, הא תנא\u0004 \u0005[הרי שנה]\u0006 \u0003רב יוסף: שלשה מזבחות היו שם\u0004 במצרים לצורך הזאת הדם: \u0003על המשקוף ועל שתי המזוזות, ותו מידי אחרינא\u0004 \u0005[ועוד דבר אחר,\u0006 נוסף\u0005]\u0006 \u0003לא הוה\u0004 \u0005[היה]\u0006 שלא היה להם כל מזבח אחר, ולא הקטירו חלבים ואימורים, ומה שלא נתפרש שנעשה במצרים — אין להניח שקיימו בו.","\u0003מה בין פסח\u0004 שעשו ישראל בשעתו \u0003במצרים לפסח דורות,\u0004 שעושים ישראל בכל הדורות? \u0003פסח מצרים מקחו\u0004 (לקיחתו) של הקרבן הוא \u0003מבעשור\u0004 לחודש ניסן, \u0003וטעון\u0004 דמו \u0003הזאה באגודת אזוב\u0004 שלא כפסח דורות, ודמו היה מוזה \u0003על המשקוף ועל שתי המזוזות, ונאכל בחפזון\u0004 (במהירות), וכל הפסח כולו אינו אלא \u0003בלילה אחד, ופסח דורות נוהג כל שבעה\u0004 ימים של יום טוב ובאיסור חמץ.","שואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שדברים שנאמרו בפסח מצרים אינם נוהגים בכל הדורות? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"דברו אל כל עדת ישראל לאמר בעשר לחדש הזה ויקחו\u0004 להם איש שה לבית אבות שה לבית\u0003\"\u0004 (שמות יב, ג), ונדקדק מן המלים \"בעשור לחודש הזה ויקחו\" כי \u0003זה\u0004 פסח מצרים \u0003מקחו\u0004 (לקיחתו) \u0003מבעשור ואין פסח דורות מקחו מבעשור.\u0004","ותוהים: \u0003אלא מעתה\u0004 אם כך אתה מבין בכתובים, הרי האמור הלאה באותו ענין \u0003\"והיה לכם למשמרת עד ארבעה עשר יום לחדש הזה\"\u0004 (שמות יב, ו) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 נדייק לומר כי \u0003זה\u0004 פסח מצרים \u0003טעון ביקור\u0004 (שמירה ובדיקה) \u0003ארבעה ימים קודם שחיטה, ואין\u0004 קרבן \u0003אחר טעון ביקור\u0004 ארבעה ימים קודם שחיטתו?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בן בג בג אומר: מניין\u0004 לקרבן \u0003תמיד שטעון ביקור ארבעה ימים קודם שחיטה — שנאמר\u0004 בתמיד: \u0003\"\u0004צו את בני ישראל ואמרת אלהם את קרבני לחמי לאישי ריח ניחוחי \u0003תשמרו להקריב לי במועדו\"\u0004 (במדבר כח, ב), \u0003ולהלן\u0004 לגבי פסח \u0003הוא אומר: \"והיה לכם למשמרת עד ארבעה עשר\"\u0004 (שמות יב, ו) \u0003מה להלן\u0004 בדין הפסח \u0003טעון ביקור ארבעה ימים קודם שחיטה, אף כאן טעון ביקור ארבעה ימים קודם שחיטה!\u0004 הרי ראיה שאין מדייקים מן ה\"חדש הזה\" שהפסח צריך ביקור.","ומתרצים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בדין הביקור לגבי קרבן התמיד \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תשמרו\"\u0004 ואינו נלמד בבנין אב אלא בגזרה שווה, שאין מקום לצמצום משמעות זה.","ומעירים: \u0003ופסח דורות נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 בו: \u0003\"\u0004והיה כי יביאך ה' אל ארץ הכנעני והחיתי והאמורי והחיוי והיבוסי אשר נשבע לאבותיך לתת לך ארץ זבת חלב ודבש \u0003ועבדת את העבדה הזאת בחדש הזה\"\u0004 (שמות יג, ה), ומשם למדים \u0003שיהו כל עבודות חדש זה\u0004 האמורות בפסח בכל הדורות \u0003כזה\u0004 כמו שהיה פסח מצרים, פרט לשיהא מקחו מבעשור שנתמעט מהמילה \"הזה\".","ושואלים: \u0003אלא\u0004 ודאי \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003\"הזה\"\u0004 שנאמר במצוות ביקור מה בא הוא למעט? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003פסח שני דכוותיה\u0004 \u0005[שכמותו],\u0006 שאין דינים האמורים בפסח ראשון אמורים גם בפסח שני.","ומקשים עוד על העיקרון הקודם: \u0003אלא מעתה דכתיב\u0004 \u0005[\u0006מה \u0005שנאמר]:\u0006 \u0003\"ואכלו את הבשר בלילה הזה\"\u0004 (שמות יב, ח) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003זה\u0004 פסח מצרים \u0003נאכל בלילה ואין אחר\u0004 פסח דורות \u0003נאכל בלילה?!\u0004 ומתרצים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ועבדת את העבדה\u0004 הזאת בחודש הזה\u0003\"\u0004 (שמות יג, ה), ללמד שדינים אלה של פסח מצרים חלים גם לדורות.","ושואלים: \u0003אלא\u0004 אם כן \u0003\"הזה\"\u0004 שנאמר כאן \u0003למה לי?\u0004 שהרי כל מה שנעשה בפסח מצרים נעשה לדורות! ומשיבים: שהוא נחוץ לכמו שדרשוהו \u0003ר' אלעזר בן עזריה ור' עקיבא\u0004 במסכת ברכות.","ומקשים: \u0003אלא מעתה דכתיב\u0004 \u0005[שנאמר]\u0006 בפסח מצרים: \u0003\"וכל ערל\u0004 (ישראל) \u0003לא יאכל בו\"\u0004 (שמות יב, מח), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\"בו\" הוא לשון מיעוט והגבלה ותלמד מכאן ש\u0003בו\u0004 בפסח מצרים \u0003אינו אוכל, אבל אוכל בפסח דורות?!\u0004 ומתרצים: הלא \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"ועבדת\"\u0004 ללמוד מפסח מצרים לפסח דורות.","ושואלים: \u0003אלא\u0004 אם כן, \u0003\"בו\"\u0004 שנאמר כאן \u0003למה לי?\u0004 ומתרצים: דיוק זה בא ללמד: \u0003\"בו\"\u0004 בפסח \u0003אינו אוכל\u0004 הערל, \u0003אבל הוא אוכל במצה ומרור\u0004 שהוא חייב ככל ישראל באכילתם.","ועוד מקשים: \u0003אלא מעתה\u0004 מה שנאמר: \u0003\"כל בן נכר לא יאכל בו\"\u0004 (שמות יב, מג), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003\"בו\"\u0004 בפסח מצרים \u0003אינו אוכל, אבל אוכל הוא בפסח לדורות?!\u0004 ומשיבים: \u0003אמר קרא \"ועבדת\"\u0004 שפסח דורות יהא כפסח מצרים וכל שנאסר באכילתו במצרים נאסר אף בפסח דורות.","ושואלים שוב: \u0003אלא\u0004 לשון המיעוט \u0003\"בו\" למה לי?\u0004 ומשיבים: למעט לענין אחר \u0003\"בו\"\u0004 לענין פסח \u0003משומדות פוסלת\u0004 מלאכול, כי פירוש המושג \"בן נכר\" הוא מי שנתנכרו מעשיו לאביו שבשמים \u0003ואין משומדות פוסלת בתרומה\u0004 שכהן שהמיר את דתו מותר לאכול בתרומה.","\u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 בתורה איסור מיוחד שעניינו \u0003\"ערל\", ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"בן נכר\". דאי\u0004 \u0005[שאילו]\u0006 \u0003כתב רחמנא\u0004 \u0005[המקרא]\u0006 רק \"\u0003ערל\",\u0004 הייתי אומר שהוא אסור לאכול מן הפסח \u0003משום דמאיס\u0004 \u0005[שמאוס]\u0006 שעורלה דבר גנאי הוא, \u0003אבל בן נכר\u0004 ש\u0003לא מאיס\u0004 \u0005[מאוס],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה בו איסור, על כן \u0003צריכא\u0004 \u0005[צריך\u0006 לומר\u0005]\u0006 אף \"בן נכר\". \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 \u0003\"בן נכר\"\u0004 בלבד, היינו אומרים שאינו אוכל בפסח \u0003משום\u0004 ש\u0003אין לבו לשמים\u0004 שהרי המיר דתו \u0003אבל ערל,\u0004 ש\u0003לבו לשמים אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהא אסור — לכן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר גם בו.","ומקשים עוד לעיקר הענין: \u0003אלא מעתה\u0004 מה שנאמר בפסח מצרים \u0003\"תושב ושכיר לא יאכל בו\"\u0004 (שמות יב, מה) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר: \u0003\"בו\"\u0004 בפסח מצרים \u0003הוא\u0004 ש\u0003אינו אוכל, אבל אוכל הוא בפסח דורות?!\u0004 ומשיבים: הלא \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"ועבדת\"\u0004 — שכל עבודות פסח יהיו כבפסח מצרים. ושואלים: \u0003אלא\u0004 אם כן \u0003\"בו\"\u0004 זה שבא למעט \u0003למה לי?\u0004 ומשיבים שבא למעט: \u0003\"בו\"\u0004 בפסח \u0003משומדות פוסלת, ואין משומדות פוסלת בתרומה\u0004 כי כתוב זה בתושב ושכיר אינו צריך ללמוד ממנו לגופו שהרי ישראל הוא, ואם אינו ענין לגופו נותנין אותו ענין לנושא אחר, שההדגשה \"בו\" באה למעט לאותו ענין.","ומקשים עוד: \u0003אלא מעתה\u0004 מה שנאמר: \u0003\"\u0004וכל עבד איש מקנת כסף \u0003ומלתה אתו אז יאכל בו\"\u0004 (שמות יב, מד) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר \u0003\"בו\"\u0004 בפסח מצרים הוא ש\u0003אינו אוכל אבל אוכל\u0004 הוא \u0003בפסח דורות?!\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"ועבדת\"\u0004 ללמד לפסח דורות. ושואלים: \u0003אלא \"בו\"\u0004 למעט \u0003למה לי?\u0004 ומסבירים: \u0003\"בו\"\u0004 בפסח \u0003מילת זכריו ועבדיו מעכבת\u0004 את האב והאדון שלא יאכל מן הפסח עד שבני ביתו ימולו, \u0003ואין מילת זכריו ועבדיו מעכבת\u0004 אותו לאכול \u0003בתרומה\u0004 אם הוא עצמו זכאי לה.","ומקשים עוד: \u0003אלא מעתה דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועצם לא ישברו בו\"\u0004 (במדבר ט, יב) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003בו\u0004 בפסח מצרים \u0003אינו שובר אבל שובר\u0004 עצם \u0003בפסח דורות?!\u0004 ומשיבים: \u0003אמר קרא \"ועבדת\"\u0004 ללמד לפסח דורות. ושואלים: \u0003אלא \"בו\"\u0004 לצמצם \u0003למה לי?\u0004 ומסבירים: \u0003\"בו\"\u0004 לשון מיעוט היא ללמדנו כי בפסח \u0003כשר\u0004 אסור לשבור עצם, \u0003ולא\u0004 נאמר איסור זה בפסח \u0003פסול.\u0004","ושואלים עוד: \u0003אלא מעתה דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אל תאכלו ממנו נא\u0004 ובשל מבושל במים\u0003\"\u0004 (שמות יב, ט), האם נאמר גם כן שמלשון המיעוט \"ממנו\" אתה מדייק \u0003\"ממנו\"\u0004 בפסח מצרים \u0003אי אתה אוכל\u0004 נא, \u0003אבל אתה אוכל נא בפסח דורות?!\u0004 ומשיבים: הלא \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"ועבדת\"\u0004 ללמד לדורות. ושואלים: \u0003אלא \"ממנו\"\u0004 שהוא לשון מיעוט \u0003למה לי?\u0004 ומשיבים: כדברי \u0003רבה\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יצחק\u0004 שמכתוב זה למדים על ידי גזירה שוה שערל אסור אף באכילת מעשר.","נאמר במשנה כי פסח מצרים \u0003נאכל בחפזון\u0004 (במהירות) ולא פסח דורות. ושואלים \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 דין זה? ומשיבים: ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ואכלתם אתו בחפזון\u0004 פסח הוא לה'\" (שמות יב, יא), המלה \"אותו\" לשון מיעוט וצמצום היא, ללמדנו: \u0003\"אותו\" נאכל בחפזון, ואין\u0004 פסח \u0003אחר נאכל בחפזון.\u0004","נאמר במשנה כי \u0003פסח דורות נוהג כל שבעה.\u0004 ושואלים: \u0003אמאי קאי\u0004 \u0005[למה הוא מתייחס]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 לענין מצוות הקרבת ה\u0003פסח\u0004 עצמה, \u0003פסח כל שבעה מי איכא\u0004 \u0005[האם ישנו]\u0006 הלא אין מקריבים קרבן פסח אלא בארבעה עשר בניסן!"],["\u0003אלא\u0004 הכוונה \u0003אחמץ\u0004 \u0005[על חמץ],\u0006 שבפסח דורות אסור החמץ כל שבעה ימים. ושואלים: \u0003מכלל\u0004 הדברים אתה לומד ש\u0003בפסח מצרים לילה אחד\u0004 בלבד היה אסור בחמץ \u0003ותו לא\u0004 \u0005[ולא עוד]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 בניגוד לכך, ש\u0003ר' יוסי הגלילי אומר: מנין לפסח מצרים שאין חימוצו\u0004 (איסור חמץ שבו) \u0003נוהג\u0004 שבעה ימים \u0003אלא יום אחד — תלמוד לומר: \"ולא יאכל חמץ\"\u0004 (שמות יג, ג) \u0003וסמיך ליה\u0004 \u0005[וסמוך לו מיד]:\u0006 \u0003\"היום אתם יצאים\u0004 בחודש האביב\u0003\"\u0004 (שמות יג, ד) — ללמד שאיסור זה של אכילת חמץ נאמר בשעתו רק ליום אחד, יום היציאה ממצרים. ומכל מקום מוכח שחל אז איסור חמץ לא רק בליל הפסח אלא גם ביומו!","\u0003אלא\u0004 יש לתרץ ולומר כי \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 במשנה: פסח מצרים מצותו \u0003לילה אחד והוא הדין לפסח דורות, וחימוצו\u0004 איסור חמץ שבו \u0003כל היום ופסח דורות נוהג\u0004 איסור זה \u0003כל שבעה.\u0004","\u0003אמר ר' יהושע: שמעתי\u0004 מרבותי שתי דינים: שמעתי דין אחד \u0003שתמורת פסח קריבה\u0004 במקרה מסויים אחר הפסח כשלמים, ושמעתי עוד דין אחר ש\u0003תמורת\u0004 ה\u0003פסח\u0004 במקרה אחר \u0003אינה קריבה, ואין לי לפרש\u0004 את דבריהם, שאיני זוכר על איזה מקרה נאמרו שני דינים אלו.","\u0003אמר ר' עקיבא: אני אפרש.\u0004 שה\u0003הפסח\u0004 שאבד והפריש אחר תחתיו ו\u0003נמצא\u0004 אותו השה שאבד \u0003קודם שחיטת הפסח — ירעה\u0004 השה \u0003עד שיסתאב\u0004 (שיפול בו מום ויפסל מקרבן) ואז \u0003ימכר\u0004 לחולין, \u0003ויביא בדמיו שלמים. וכן\u0004 הדין לגבי \u0003תמורתו,\u0004 שאם אמר אדם על שה זה שיהא אחר תמורתו שאז קדושה שיש בו חלה גם על התמורה. ואם המיר שה בשה הפסח שאבד, אף הוא ירעה עד שיסתאב וימכר והוא שאמרו תמורת הפסח אינה קריבה.","ואם נמצא אותו שה שאבד \u0003אחר שחיטת הפסח — קרב\u0004 הוא עצמו \u0003שלמים. וכן תמורתו\u0004 קריבה וזהו ביאור השמועה האחרת שתמורת הפסח קריבה.","על הסברו של ר' עקיבא מקשים: אם כן \u0003לימא\u0004 \u0005[שיאמר]\u0006 בנוסח: \u0003פסח קרב ופסח אינו קרב,\u0004 שהרי אין הדבר תלוי בתמורה אלא בקרבן הפסח עצמו. ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 על ידי ניסוח זה של האימרה: \u0003דאיכא\u0004 \u0005[שיש]\u0006 מקרה של \u0003תמורת הפסח דלא קרבה\u0004 \u0005[שאינה קריבה].\u0006 שיכולנו לחשוב שתמורת הפסח יהא דינה תמיד כמותר הפסח ותקרב שלמים, לכן הודיענו שיש מקרה שאינה קריבה כלל משום שהיא באה תמורת הפסח שאינו ראוי להיקרב.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בנוסח המשנה, \u0003רבה אמר:\u0004 נמצא \u0003קודם שחיטה\u0004 של השני ונמצא \u0003לאחר שחיטה\u0004 של השני \u0003שנינו,\u0004 וזהו נוסח המשנה: \u0003ר' זירא אמר:\u0004 נמצא \u0003קודם חצות\u0004 היום שהוא הזמן הקובע לגבי הפסח ואז הריהו נקבע כפסח, ונמצא \u0003לאחר חצות שנינו\u0004 שאפילו אם נמצא לפני השחיטה עצמה כיון שלא הוקבע לפסח — הריהו שלמים.","ושואלים: \u0003ולר' זירא, הא קתני\u0004 \u0005[הרי שנה]\u0006 במשנה במפורש \u0003קודם שחיטת הפסח\u0004 וכיצד יכול הוא לשנות את הגירסה? ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003כך\u0004 צריך היה להבין לדעתו: שקודם שחיטה אינו תלוי במעשה אלא הכוונה היא \u0003קודם זמן\u0004 הראוי של \u0003שחיטת הפסח\u0004 — שהוא בחצי היום.","ומעירים: כי מחלוקת אמוראים זאת היא \u0003כתנאי\u0004 \u0005[כתנאים\u0006 שנחלקו בענין זה\u0005]:\u0006 \u0003הפסח שנמצא קודם שחיטה\u0004 של השני \u0003ירעה\u0004 — עד שיפול בו מום וימכר לחולין ויביא שלמים בדמיו, נמצא \u0003לאחר שחיטה — יקרב\u0004 הוא עצמו שלמים. \u0003ר' אליעזר אומר:\u0004 נמצא \u0003קודם חצות — ירעה,\u0004 נמצא \u0003לאחר חצות — יקרב\u0004 כדברי ר' זירא.","שנינו במשנה: אם נמצא \u0003אחר שחיטת הפסח יביא\u0004 אותו כקרבן \u0003שלמים\u0004 וכן תמורתו. \u0003אמר רבא: לא שנו\u0004 הלכה זו שהתמורה קריבה \u0003אלא\u0004 כ\u0003שנמצא\u0004 אותו שה\u0003אחר שחיטה\u0004 של השני \u0003והמיר בו אחר שחיטה,\u0004 שהפסח שאבד היה ראוי לשלמים. \u0003אבל\u0004 אם \u0003נמצא קודם שחיטה,\u0004 אפילו \u0003המיר בו אחר שחיטה\u0004 של השני — אינו בא שלמים, כי \u0003תמורתו מכח קדושה דחויה קא אתא\u0004 \u0005[באה],\u0006 שהרי היה הראשון לפנינו ונדחה, ולכן תמורתו \u0003לא קרבה\u0004 אינה יכולה להיות מוקרבת, שכן הפסח הראשון לא היה ראוי כלל להקרבה, והיה צריך לרעות עד שיסתאב.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 מברייתא: \u0003\"אם כשב\u0004 הוא מקריב את קרבנו\u0003\"\u0004 (ויקרא ג, ז) \u0003מה תלמוד לומר \"אם כשב\"\u0004 ומה באה התוספת \"אם\" ללמדנו? הרי זה \u0003לרבות תמורת הפסח אחר הפסח שקרבה שלמים.\u0004","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם לומר]\u0006 שמדובר כאן \u0003שנמצא\u0004 אותו שה\u0003אחר שחיטה והמיר בו\u0004 שה אחר \u0003אחר שחיטה\u0004 הרי \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ו\u0003למה לי קרא\u0004 \u0005[מקרא]?\u0006 והרי יודעים אנו שפסח אחר זמנו דינו כשלמים! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003שנמצא קודם שחיטה והמיר בו\u0004 שה אחר \u0003אחר שחיטה\u0004 ואותו שה תמורה בא הכתוב לרבותו שקרב שלמים, ובניגוד לדברי רבא!","ודוחים: \u0003לא, לעולם\u0004 יש לפרש \u0003שנמצא אחר שחיטה והמיר בו אחר שחיטה,\u0004 ואף שהדבר פשוט, מכל מקום \u0003קרא\u0004 \u0005[והמקרא]\u0006 שהובא לראיה באותה ברייתא אינו אלא \u0003אסמכתא בעלמא\u0004 \u0005[סמך,\u0006 רמז \u0005בלבד]\u0006 ולא לשם כך בא הכתוב.","ושואלים: \u0003אלא\u0004 אם כן \u0003קרא\u0004 \u0005[המקרא]\u0006 הזה \u0003למאי אתא\u0004 \u0005[למה,\u0006 לאיזה ענין \u0005בא]?\u0006 ומשיבים: \u0003כדתניא\u0004 \u0005[כפי ששנויה\u0006 ברייתא אחרת\u0005]\u0006 \u0003\"כשב\" לרבות את\u0004 קרבן \u0003הפסח\u0004 שאף הוא טעון הקרבת \u0003אליה\u0004 למזבח שלא נתפרש הדבר בדיני הקרבת הפסח.","\u0003כשהוא אומר \"אם כשב\"\u0004 שמוסיף מקרים של קרבנות נוספים, כתמורות ומותרות, הרי זה בא \u0003לרבות\u0004 שה שהוקדש ל\u0003פסח\u0004 אבל \u0003עברה שנתו\u0004 ועתה כיון שהוא יותר מבן שנה שוב אינו ראוי לפסח, או \u0003שלמים הבאין מחמת פסח\u0004 (מכוח תמורה או מכוח פסח שנתכפרו בעליו באחר) \u0003לכל מצות שלמים\u0004 שקרבן זה שוב אינו חשוב כפסח אלא כשלמים לכל דבר ולכן \u0003טעון סמיכה ונסכים\u0004 ו\u0003תנופת חזה ושוק\u0004 כבשלמים,","\u0003וכשהוא אומר \"ואם עז\u0004 קרבנו\u0003\"\u0004 (ויקרא ג, יב) — \u0003הפסיק\u0004 את \u0003הענין\u0004 הקודם, ו\u0003לימד על העז שאין טעונה\u0004 הקרבת \u0003אליה\u0004 על המזבח.","זו היתה גירסה אחת של דברי רבא ואביי ושיטותיהם. \u0003איכא דמתני לה ארישא\u0004 \u0005[יש ששונים את\u0006 המחלוקת \u0005הזו על תחילת\u0006 המשנה\u0005],\u0006 שנאמר בה: \u0003הפסח שנמצא קודם שחיטת הפסח — ירעה עד שיסתאב וימכר ויביא בדמיו שלמים וכן\u0004 דין \u0003תמורתו,\u0004","ועל כך \u0003אמר רבא: לא שנו אלא שנמצא קודם שחיטה\u0004 ואף \u0003המיר בו\u0004 שה אחר \u0003קודם שחיטה אבל\u0004 אם \u0003נמצא קודם שחיטה והמיר בו אחר שחיטה — תמורתו קריבה שלמים. מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לדעתו — \u0003כי קבעה\u0004 \u0005[כאשר קובעת]\u0006 \u0003שחיטה\u0004 ועושה שינוי הלכתי בין קרבן לקרבן הרי זה לגבי \u0003מידי דחזי ליה\u0004 \u0005[דבר שראוי לו\u0006 להקרבה\u0005]\u0006 שלגבי הפסח עצמו יש הבדל אם היה לפני שחיטה או אחריה אבל \u0003מידי\u0004 \u0005[דבר]\u0006 ש\u0003לא חזי ליה\u0004 \u0005[ראוי לו]\u0006 שהוא התמורה, שממילא אינה קריבה לפסח, השחיטה \u0003לא קבעה\u0004 \u0005[קובעת].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 מאותה ברייתא: \u0003\"אם כשב\" מה תלמוד לומר?\u0004 הרי זה \u0003לרבות תמורת הפסח אחר הפסח שקריבה שלמים,\u0004"],["\u0003יכול אף\u0004 תמורת הפסח שנמצא \u0003לפני הפסח\u0004 דינו \u0003כן\u0004 שקריבה שלמים? \u0003תלמוד לומר: \"הוא\",\u0004 להדגיש: \u0003הוא\u0004 פסח כשר \u0003קרב, ואין תמורת הפסח קריבה.\u0004","ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 הדבר\u0005]\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שנמצא\u0004 אותו קרבן \u0003קודם שחיטה, והמיר בו קודם שחיטה — פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ו\u0003למה לי קרא\u0004 \u0005[מקרא]\u0006 מיוחד ללמדני? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003שנמצא קודם שחיטה והמיר בו\u0004 ל\u0003אחר שחיטה\u0004 ועליו נאמר שאין תמורתו קריבה! הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 ל\u0003רבא,\u0004 ומסכמים אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה],\u0006 ונדחו דבריו לפי גירסה זו.","\u0003אמר שמואל\u0004 כלל בדיני קדשים: \u0003כל\u0004 שאירע פסול בבהמת קרבן \u0003שבחטאת\u0004 הדין שהיא \u0003מתה,\u0004 כלומר שגורמים שתמות מעצמה \u0003—\u0004 במקרה כגון זה \u0003בפסח קרב שלמים. וכל\u0004 שדינה שמחמת הפסול \u0003בחטאת רועה\u0004 עד שיפול בה מום \u0003—\u0004 דינה ש\u0003בפסח נמי\u0004 \u0005[גם כן]\u0006 \u0003רועה. ור' יוחנן אמר: אין הפסח\u0004 עצמו \u0003קרב שלמים אלא כשנמצא\u0004 השה האבוד \u0003אחר שחיטה\u0004 של השני, \u0003אבל\u0004 נמצא \u0003קודם שחיטה — לא.\u0004","על דברי שמואל \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב יוסף:\u0004 וכי \u0003כללא\u0004 \u0005[כלל]\u0006 \u0003הוא?\u0004 כלומר: וכי נכון הכלל בכל המקרים? \u0003והרי חטאת שעברה שנתה\u0004 שיש להקריבה עד שהיא בת שנה אחת, ואם עבר זמנה ש\u0003לרעיה אזלא\u0004 \u0005[הולכת]\u0006 עד שיפול בה מום, ש\u0003אמר ר' שמעון בן לקיש: חטאת שעברה שנתה רואין אותה כאילו היא עומדת בבית הקברות\u0004 מקום שאין הכהן יכול להכנס ולהוציאה משם, ולכן \u0003רועה\u0004 עד שיפול בה מום ונמכרת לחולין ונופלים דמיה לשלמים.","\u0003ואילו בפסח כי האי גוונא\u0004 \u0005[כגון זה]\u0006 \u0003קרב שלמים, דתניא\u0004 \u0005[שהרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"כשב\"\u0004 הרי זה בא \u0003לרבות את הפסח\u0004 שאף ממנו צריך להקריב \u0003אליה, כשהוא אומר \"אם כשב\" לרבות את הפסח שעברה שנתו ושלמים הבאין מחמת פסח\u0004 ששוב אינם חשובים כפסח אלא כשלמים \u0003לכל מצות שלמים, שטעונים סמיכה ונסכים ותנופת חזה ושוק. כשהוא אומר\u0004 בהמשך \u0003\"ואם עז\" — הפסיק הענין\u0004 בדין כבשים ופתח בענין חדש \u0003ללמד על העז שאין טעון אליה.\u0004 ומברייתא זו למדנו שפסח שעברה שנתו קרב שלמים מיד ואינו רועה!","\u0003אמר ליה\u0004 \u0005[ לו]:\u0006 \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003שמואל\u0004 את כללו, לא אמרו אלא לגבי קרבנות שהיו \u0003אבודין\u0004 ובהם דן אבל \u0003בדחויין\u0004 מחמת פסול אחר \u0003לא אמר.\u0004","וממשיכים להקשות: וכי בדין \u0003אבוד מי משכחת לה\u0004 \u0005[האם אתה מוצא אותה]\u0006 שההכללה של שמואל תהא נכונה? \u0003והרי\u0004 חטאת שהיתה \u0003אבודה בשעת הפרשה\u0004 כלומר חטאת שאבדה והפריש אחרת תחתיה ונמצאה לפני הקרבה, \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 ש\u0003לרעיה אזלא\u0004 \u0005[הולכת]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו]:\u0006 \u0003הפריש חטאתו ואבדה, והפריש אחרת תחתיה ונמצאת הראשונה, והרי שתיהן עומדות\u0004 ועליו להקריב אחת מהן \u0003— אחת מהן\u0004 (איזו שירצה) \u0003תקרב ושניה תמות,\u0004 אלה \u0003דברי רבי. וחכמים אומרים: אין חטאת מתה אלא\u0004 אם כן \u0003שנמצאת לאחר שנתכפרו בעלים\u0004 באחרת. \u0003הא\u0004 \u0005[הרי]\u0006 מכאן נלמד כל שנמצאת \u0003קודם שנתכפרו בעלים\u0004 — חטאת כזו \u0003רועה.\u0004","\u0003ואילו בפסח, היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003אבד ונמצא אחר חצות קודם שחיטה — קרב שלמים.\u0004 ואם כן אין כללו של שמואל נכון אף בזה! ומשיבים: \u0003שמואל כרבי סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר אבודה למיתה אזלא\u0004 \u0005[היא הולכת].\u0006","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כל אבודה לרבי מתה\u0004 בכל מקרה שאבדה, \u0003ואילו בפסח היכא\u0004 \u0005[במקום]\u0006 ש\u0003אבד קודם חצות ונמצא קודם חצות\u0004 לאחר שהפרישו אחר — \u0003רועה!\u0004 ודוחים: פסח שאבד \u0003קודם חצות לאו\u0004 \u0005[לא]\u0006 \u0003אבוד הוא,\u0004 וטעמו של דבר כשיטת \u0003רבא,\u0004 ש\u0003אמר רבא: אבידת לילה לאו\u0004 \u0005[לא]\u0006 \u0003שמה אבידה.\u0004","שאם אבד קרבן בשעות הלילה ונמצא בבוקר אינו קרוי אבוד לכל הדינים האמורים בקרבן שאבד, שכיון שהלילה אינו ראוי לשחיטת הקרבן \u0003—\u0004 אינו נחשב לאבידה. ואף קרבן הפסח שאבד לפני חצות ערב הפסח, כיון שאינו ראוי עדיין לשחיטה כשאבד אין זו קרויה אבידה ואין דיני אבוד חלים עליו, אפילו אם הפריש אחרת תחתיה ואפילו לרבי אינה הולכת למיתה אלא לראיה. ושואלים: \u0003אלא,\u0004 אם כן חטאת שיהא דינה ש\u0003רועה ל\u0004שיטת \u0003רבי, היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]?\u0006 שלשיטתו כל חטאת שאבדה הולכת למיתה, ואין חטאת שדינה שרועה, ואם כן אין תוכן לכללו זה של שמואל ש\"כל שבחטאת רועה\" לפי שיטת רבי!"],["ומשיבים: אף לשיטת רבי מוצא אתה חטאת רועה \u0003כ\u0004שיטת \u0003ר' אושעיא. שאמר ר' אושעיא: הפריש שתי חטאות לאחריות\u0004 שמתחילה הפריש שתים כדי שאם תאבד אחת מהן יתכפר בחברתה, \u0003מתכפר באחת מהן ושניה תרעה.\u0004","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אילו\u0004 אירע \u0003בפסח כי האי גוונא\u0004 \u0005[כגון זה]\u0006 היה השני \u0003קרב שלמים,\u0004 שזהו מותר בפסח גמור שדינו להיקרב כשלמים ולא כדברי שמואל! \u0003אלא\u0004 יש לומר כי \u0003שמואל\u0004 כשיטת \u0003ר' שמעון סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר: חמש חטאות מתות\u0004 ובכללן כל אלו שאבדו ואלו שנדחו.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 דין זה של חטאת \u0003רועה לר' שמעון לית ליה\u0004 \u0005[אין לו]\u0006 \u0003כלל\u0004 שלדעתו כל חטאת שנדחתה משום מה מתה ואילו שמואל מזכיר בדבריו אף את החטאת שרועה! ומשיבים: \u0003שמואל נמי חדא קאמר\u0004 \u0005[\u0006דבר \u0005אחד\u0006 בלבד \u0005אמר]\u0006 שלא אמר דבר בענין כל שבחטאת רועה אלא רק \u0003כל שבחטאת מתה — בפסח קרב שלמים.\u0004","ושואלים: \u0003ומאי קא משמע לן\u0004 \u0005[ומה השמיע לנו]\u0006 בכך, הרי כבר נאמר הדבר במפורש במשנה? ומשיבים: אמר זאת \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 מדברי \u0003ר' יוחנן\u0004 ש\u0003אמר: אין הפסח קרב שלמים אלא\u0004 כ\u0003שנמצא אחר שחיטה, אבל\u0004 אם נמצא \u0003קודם שחיטה — לא. אלמא:\u0004 \u0005[מכאן]\u0006 שלדעתו \u0003שחיטה קבע\u0004 מתי נדחה הקרבן. על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמואל כי לדעתו \u0003חצות קבע\u0004 שהדבר תלוי בזמן השחיטה הרגיל ואם נמצא לאחר חצות אף אם עדיין לא נשחט השני הריהו נחשב כאבוד, כיון שבשעת חצות שהיא השעה הקובעת היה אבוד ולכך קרב שלמים.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 באותו ענין הממשיכה את הדיון מן הנקודה בה מוכיחים כי אין להשוות בין פסח לחטאת \u0003ואילו בפסח היכא\u0004 \u0005[במקום,\u0006 במקרה\u0005]\u0006 ש\u0003אבד ונמצא אחר חצות, קודם שחיטה\u0004 של השני \u0003— יקרב שלמים\u0004 ושלא כפי ההשוואה של שמואל! ומשיבים: \u0003שמואל\u0004 ללשון זו כשיטת \u0003רבה סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר: שחיטה קבע\u0004 ולא חצות היום ולכך אף אם עבר חצות היום, אם נמצא לפני שחיטת השני, שוב אינו נחשב כאבוד.","ומקשים: \u0003והא מדקאמר\u0004 \u0005[והרי מ\u0006מה \u0005שאמר]\u0006 \u0003ר' יוחנן עלה\u0004 \u0005[עליה\u0006 על הלכה זו\u0005]:\u0006 \u0003אין הפסח קרב שלמים אלא\u0004 כ\u0003שנמצא אחר שחיטה, אבל\u0004 אם נמצא \u0003קודם שחיטה — לא. אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003שחיטה קבע. מכלל\u0004 הדברים ומהקשרם מובן שכיון שיש מחלוקת בדבר הרי ש\u0003שמואל סבר: חצות קבע\u0004 וכל שבחצות היה אבוד, אף אם נמצא לפני השחיטה, הריהו נחשב כאבוד וקרב שלמים ולא כפי שנתבאר בשיטת שמואל ללשון זו שדעתו ששחיטה קבע.","\u0003אלא\u0004 יש להסביר באופן אחר: \u0003שמואל כרבי סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ש\u0003אמר:\u0004 חטאת \u0003אבודה למיתה אזלא\u0004 \u0005[הולכת]\u0006 בכל מקרה. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כל אבודין ל\u0004דעת \u0003רבי מתין, ואילו בפסח היכא\u0004 \u0005[מקום]\u0006 ש\u0003אבד קודם חצות ונמצא קודם חצות — רועה\u0004 ולא קריבה שלמים! ומשיבים: \u0003קסבר\u0004 \u0005[סבר]\u0006 אבידה \u0003קודם חצות לאו\u0004 \u0005[אינו]\u0006 \u0003אבוד הוא\u0004 שעדיין לא הגיע זמן שחיטתו \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 כי \u0003חצות קבע\u0004 ולא זמן השחיטה.","\u0003המפריש נקבה לפסחו\u0004 והתורה אמרה שהפסח בא מן הזכר, \u0003או\u0004 שהפריש \u0003זכר בן שתי שנים\u0004 בעוד שפסח צריך להיות עד בן שנה — \u0003ירעה עד שיסתאב\u0004 (שיפול בו מום) \u0003ו\u0004אז \u0003ימכר\u0004 קרבן זה \u0003ויפלו דמיו לנדבה לשלמים.\u0004"]]};
